export const MODEL_MANUALS=[{"id":"transient-rectangular","name":"矩形 FVM 非定常熱伝導","source":"docs/dynamic/TRANSIENT_MANUAL_RECTANGULAR_20261107.md","screen":{"href":null,"label":"この画面（動的熱移動実験室）"},"lead":[{"label":"対象モデル","x":"`dynamic/thermal.mjs`（セル中心有限体積法）。画面は `dynamic/index.html`（平板・フィンの実験、`dynamic/lab.mjs`）。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"固体内部を熱が伝わり、場所ごとの温度が時間とともに変わっていく現象（非定常熱伝導）を、平板および2D断面で計算するモデルである。加熱・冷却の進行、複合材料（多層・界面の接触熱抵抗）、内部発熱、表面での対流・放射による放熱を扱う。温度分布の時間変化そのものを見ることが目的で、流体の流れは解かない。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"熱処理（焼入れ・焼戻し）中の鋼板が内部までどの速さで冷えるかの見通し。"},{"x":"電子回路基板や筐体の一部が、発熱部品の影響でどこまで温度上昇するか。"},{"x":"断熱材を含む複合壁（壁＋断熱層）が、外気温の変化に対して室内側へどれだけ遅れて応答するか。"},{"x":"食品や成形品の加熱・冷却で、中心部が目標温度に達するまでの時間の見積り。"}]},{"t":"p","x":"いずれも一次元の見通しや2D断面の学習・概算のためであり、実設計の保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"一定物性・等方性の場合の熱伝導方程式（教科書 §2.1）："},{"t":"p","x":"ρcp ∂T/∂t = ∇·(k∇T) + q‴"},{"t":"p","x":"物性が温度に依存する場合は k(T)・cp(T) を手動表で与え、∇·(k(T)∇T) の形を離散化する。k(T) の定常解は Kirchhoff 変換による連続解と照合して検証している（`docs/dynamic/TEMPERATURE_DEPENDENT_CP.md`、本書の項目10）。"}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["T","温度（内部計算は絶対温度、表示は ℃）","K"],["x, y","位置（幅・高さ方向）","m"],["z","奥行き（2D断面の厚さとして一様）","m"],["k","熱伝導率（k(T) 表を指定可能）","W/(m·K)"],["ρ","密度（一定）","kg/m³"],["cp","比熱（cp(T) 表を指定可能）","J/(kg·K)"],["q‴","体積発熱密度（負は一様冷却）","W/m³"],["h","熱伝達率（入力値。流れから予測しない）","W/(m²·K)"],["ε","放射率（0〜1）","—"],["σ","ステファン・ボルツマン定数 5.670374419×10⁻⁸","W/(m²·K⁴)"],["R","材料界面の接触熱抵抗","m²·K/W"],["α = k/(ρcp)","熱拡散率","m²/s"],["Fo = αt/L²","フーリエ数（代表長さ L に対する無次元時間）","—"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"一様な初期絶対温度、またはセルごとの初期温度場（配列）のどちらかを与える。k(T)／cp(T) の表を使う場合は、初期温度が表の範囲内にあることが必要で、範囲外は外挿せず生成時に拒否される（`dynamic/thermal.mjs`）。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"p","x":"外周4辺と、輪郭で露出した面（edge）に、次の面条件を設定できる。表面までの半セルの伝導抵抗を常に含む。"},{"t":"ul","items":[{"x":"温度固定：表面温度を与える。"},{"x":"熱流束：内向き熱流束 [W/m²] を与える（正が加熱）。"},{"x":"断熱：流束ゼロ。"},{"x":"対流：半セル抵抗と 1/(hA) を直列にした表面温度で評価する。"},{"x":"放射：灰色面から大きな黒い周囲への放射。表面温度を二分法で解く（形態係数1）。"},{"x":"対流＋放射（同時境界）：セル中心と表面の間の伝導 G に対し、G(Tc−Ts) = hA(Ts−T∞) + εσA(Ts⁴−Tr⁴) を解いて共通表面温度 Ts を求める。流体温度 T∞ と放射周囲温度 Tr は別の入力である（`docs/dynamic/SURFACE_EXCHANGE.md`）。"}]},{"t":"p","x":"材料界面では、両側の半セル抵抗に接触熱抵抗 R を直列に加え、面を通過する熱量を両側で等量・逆符号に計上する。"},{"t":"p","x":"自由輪郭を指定した場合、露出面に使えるのは温度固定と断熱のみである。面積に依存する条件（熱流束・対流・放射・同時境界）は生成時に拒否される。理由と範囲の確定は `docs/dynamic/TRANSIENT_CONDUCTION_FREE_CONTOUR_SCOPE_20261107.md` を参照。"}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"セル中心の保存型有限体積法。内部面のコンダクタンスは半セル抵抗の直列 G = A / (dist/(2k_n) + dist/(2k_m) + R)（同一材料では R=0）。境界の半セルコンダクタンスは 2kA/dist。"},{"x":"時間積分は前進 Euler。安定刻みは safeDt = 0.8 × min(C_i / ΣG_i) で、これを超える刻みは拒否される。格子は各方向1〜256、合計16384セル以下。"},{"x":"cp(T) を使うセルは、比エンタルピー h(T) = ∫cp(θ)dθ で熱量を更新してから温度へ逆変換する（cp×温度差の近似ではない。`docs/dynamic/TEMPERATURE_DEPENDENT_CP.md`）。"},{"x":"放射の表面温度は二分法（52回反復）、対流＋放射同時境界の表面温度は Newton 法＋二分法で解く（`dynamic/surface-exchange.mjs`）。"},{"x":"顕熱の収支（初期値との差と外部入力の累積）を常時監視し、非有限値・0 K 以下・表範囲外では更新前の状態で原子的に停止する。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"形状・材料・境界・格子を設定し「適用」で初期状態から計算を始める。"},{"x":"各刻みで、内部面・境界・内部発熱からの正味入力で全セルの熱量を更新する。"},{"x":"表示（温度場・等温線・断面・履歴）と診断（顕熱収支、同時境界の表面温度と各寄与）を確認しながら時間を進める。"}]},{"t":"p","x":"手計算による検算の例："},{"t":"ul","items":[{"x":"一様温度・断熱・発熱のみなら、全セル一様に ΔT = q‴t/(ρcp)。cp(T) の場合は ∫cp(T)dT = q‴t/ρ から求める（アプリ内 #manual「検算・適用範囲」にも記載）。"},{"x":"定常・1D・一定物性なら温度は線形分布となり、熱流束は直列熱抵抗（伝導＋接触＋対流）で手計算できる。"}]}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"温度色は**セル平均温度**の表示である。等温線はセル中心間を三角形に分けた区分線形補間で描かれており、物理的な壁面温度の再構成ではない（アプリ内 #manual「図形・測定・比較」に明記）。"},{"x":"断面グラフは、測定点に近いセル列の温度を実座標の横軸で示す。点温度ではなくセル列の代表値として読む。"},{"x":"時間履歴は保存された計算状態に対するもので、巻き戻しは過去の状態の表示と、そこからの再計算である。"},{"x":"2条件比較（A/B）は同じ物理時刻・同じ色尺度で表示される。形状寸法が違う条件では、測定点は寸法比で対応付けられる。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"ul","items":[{"x":"セル平均と実測点温度を区別する。表面温度は境界条件と半セル抵抗から決まる値で、端のセルの中心温度とは異なる。"},{"x":"収支誤差（エネルギー誤差）は保存則の破れ具合を示す診断であり、温度の離散化誤差そのものではない。両者を混同しない。"},{"x":"検証の実測（出典付き）：","sub":{"t":"ul","items":[{"x":"断熱・一定物性の分離解ベンチマークでは、空間 RMS 誤差 0.00347 K（10×5）→ 0.000867 K（20×10）→ 0.000217 K（40×20）、観測された空間次数 2.0009／2.0003、時間次数 1.0078／1.0039、エネルギー誤差は 10⁻¹⁵ J 級（`docs/dynamic/BENCHMARKS.json`）。"},{"x":"定常解への漸近では、両端等温の平板で測定減衰率 9.866 /s が連続第1固有値 απ²/L² = 9.870 /s と比 0.9997 で一致（フェイリス側検証記録 `TRANSIENT_CLOSURE_VERIFICATION_20261107.md`、ブランチ `feiris/transient-closure-notes`）。"},{"x":"熱流束ゼロ条件（断熱全境界・対称面・等温放射）は専用試験に集約され、断熱の非一様場で体積平均への最大偏差 5.68e-13 K、収支誤差 0 を確認（同記録）。"},{"x":"k(T)／cp(T) × 対流＋放射同時境界の組合せは、製品では現在も拒否されている。独立参照との照合では測定範囲（1D平板・片面のみ同時境界）で最大差 5.8e-3 K 以下・定常極限の一致 1.3e-10 K 以内という裏付けがあるが、受理の解除には残条件がある（同記録）。"}]}}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"2D断面で奥行き方向は一様。薄い板の表裏は断熱。"},{"x":"密度は一定。相変化・潜熱は扱わない。"},{"x":"放射は灰色面と大きな黒い周囲（形態係数1）のモデルで、面同士の囲い放射は扱わない。"},{"x":"熱伝達率 h は入力値であり、風速・浮力・流れ場から推定しない。周囲の流体は解かない。"},{"x":"フィンの実験は、細長い一定断面の1D近似（側面対流を体積あたりの損失として含み、先端は断熱）であり、2D伝導モデルとは別扱いである。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"自由輪郭での面積依存境界は使えない（項目6の確定記録）。"},{"x":"温度依存物性と対流＋放射同時境界の組合せは製品では拒否される（項目10）。"},{"x":"温度依存物性付きフィンは、側面対流との連成検証待ちのため使用できない。"},{"x":"3D解析ではない。複雑形状の一般的な解析精度は保証しない。"},{"x":"研究・設計への無条件の適合は保証しない（アプリ内 #manual「検算・適用範囲」）。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「格子を細かくすれば自由輪郭の表面積も正しくなる」** — 誤り。階段近似の総面積は細分化しても真の面積へ収束しない。面積依存境界を輪郭で拒否する理由である。"},{"x":"**「セルの温度がそのまま表面温度」** — 誤り。表面までは半セルの伝導抵抗があり、表面温度は境界条件と合わせて解かれる。"},{"x":"**「対流と放射はセル温度にそれぞれ加えればよい」** — 誤り。同時境界では表面温度 Ts を共有して収支を解くため、単純加算とは結果が異なる。片方が加熱・片方が冷却になる場合もある。"},{"x":"**「cp(T) のときも cp×温度差で熱量を近似してよい」** — 誤り。本モデルはエンタルピー積分で更新しており、近似式とは平衡温度などが異なる。"},{"x":"**「巻き戻しは熱の方程式を逆向きに解いている」** — 誤り。保存した過去の状態を表示し、そこから前向きに再計算する。"},{"x":"**「安定刻みの範囲内なら精度も保証される」** — 誤り。安定性と精度は別であり、格子と刻みを変えた比較が必要である。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"アプリの教材：§5.3「一次元平板の非定常伝導」（アプリ内 #manual から `../index.html#reader/5.3` へリンク済み）、§5.8「非定常多次元熱伝導」。"},{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、第2章 §2.1（熱伝導方程式）、第5章（非定常・多次元熱伝導）、Appendix A（物性値）。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第3.1節・第3.4節）に基づく。記載した ID はすべて問題バンク `data/questions.json` の実在 ID であり、アプリの演習（`../index.html#quiz`）でそのまま検索できる。"},{"t":"h","x":"矩形モデル本体（第5章、主掲載 70 件から代表 12 件）"},{"t":"p","x":"主掲載は、平板の分布系・一項近似・線図（21件）、矩形の積解（7件）、多次元伝導（9件）、集中熱容量と無次元数の基礎（21件、全非定常モデル共通）、半無限近似（12件、下記の小節）からなる。基礎から応用の順に代表を示す。全件は対応表の第3.1節に記載されている。"},{"t":"ul","items":[{"x":"`supp-section-5-3` — 対称な板の中心面では温度勾配が0になること（第5.3節の学習ノート）。"},{"x":"`supp-expanded-bi-calc` — 集中熱容量近似の適用可否を Bi で判断する計算。"},{"x":"`supp-existing-lumped-time-constant-v1` — 集中熱容量モデルの時定数 τ=mc/(hA_s)。"},{"x":"`supp-found-slab-biot-v1` — 両面同条件の平板について、半厚さ・h・k から Bi を求める。"},{"x":"`supp-transient-gap-one-term-eigen-root-v1` — 一項近似の固有値条件 Bi=λ₁tanλ₁ から Bi を求める。"},{"x":"`supp-transient-gap-chart-center-temperature-v1` — 温度応答線図の考え方で中心温度を求める。"},{"x":"`supp-transient-gap-product-center-v1` — 分離可能な矩形冷却の積解による中心温度。"},{"x":"`supp-transient-gap-multidim-flux-components-v1` — 2次元温度場における熱流ベクトルの成分。"},{"x":"`supp-transient-gap-surface-vs-ambient-v1` — 有限の h を介して冷却する固体の表面温度の扱い。"}]},{"t":"h","x":"半無限近似（矩形モデルの短時間・厚肉極限、主掲載 12 件から代表 3 件）"},{"t":"p","x":"半無限近似は独立モデルではなく本モデルの短時間極限として扱われるため、本小節に置く。全件は対応表の第3.1節（半無限近似）にある。"},{"t":"ul","items":[{"x":"`supp-chapter-ch5-time` — 温度浸透尺度 δ∝√t の時間依存性。"},{"x":"`supp-applied-5-6-v1` — 一定表面温度の半無限固体で erfc を使って温度を求める。"},{"x":"`supp-deep-semi-surface-flux-v1` — 半無限固体の表面熱流束。"}]},{"t":"h","x":"複合材料（多層・界面）— 主掲載 31 件（全件）"},{"t":"p","x":"本モデルが担う複合材料（多層・界面の接触熱抵抗）に対応するのは、定常の直列抵抗網・界面温度・接触抵抗・円筒壁・総括熱伝達係数の問題群である（対応表の第3.4節）。層ごとの蓄熱まで含む「非定常の多層」そのものの問題はバンクに無く、対応は定常抵抗網と界面温度が中心である。"},{"t":"ul","items":[{"x":"`supp-resistance-total` — 二層平板と両側対流を直列に扱う総熱抵抗（最も直接の対応）。"},{"x":"`supp-resistance-flow` — 直列熱抵抗 R と両端温度差から熱移動率を求める。"},{"x":"`supp-audit-resistance-layer-temp-drop` — 直列抵抗網における一つの層の温度降下。"},{"x":"`supp-audit-resistance-overall-u` — 全熱抵抗から総括熱伝達係数 U を求める。"},{"x":"`supp-audit-resistance-one-layer-doubled` — 一層の抵抗を2倍にしたときの影響。"},{"x":"`supp-chapter-ch2-cylinder-resistance` — 円筒壁の半径方向定常熱抵抗。"},{"x":"`supp-chapter-ch2-cylinder-watts` — 円筒壁の熱抵抗と温度差から熱移動率を求める。"},{"x":"`supp-chapter-ch2-series` — 同じ熱が順に通過する直列抵抗系の熱移動率。"},{"x":"`supp-section-2-3` — 直列につないだ抵抗の合成（第2.3節の学習ノート）。"},{"x":"`supp-section-2-4` — 内外の U の数値が異なっても同じに保たれる量（第2.4節の学習ノート）。"},{"x":"`supp-section-2-5` — 同じ熱移動率で抵抗が2倍のときの温度降下（第2.5節の学習ノート）。"},{"x":"`supp-advanced-ch2-calc` — 直列系の熱移動率と中央の抵抗の温度降下。"},{"x":"`supp-applied-2-3-v1` — 直列系における中央の抵抗の温度降下。"},{"x":"`supp-found-resistor-series-v1` — 直列経路の熱移動率。"},{"x":"`supp-found-resistor-parallel-v1` — 並列経路の合計熱移動率。"},{"x":"`supp-found-resistor-interface-temperature-v1` — 直列経路における二つの抵抗の間の界面温度。"},{"x":"`supp-found-resistor-network-principle-v1` — 抵抗ネットワークへ並列経路を追加したときの効果。"},{"x":"`supp-next-three-series-v1` — 3抵抗が直列の経路の熱移動率。"},{"x":"`supp-next-parallel-extra-branch-v1` — 並列経路の追加と合計熱移動率。"},{"x":"`supp-next-parallel-temperature-condition-v1` — 並列接続で各枝に共通な条件。"},{"x":"`supp-batch2-plane-u-v1` — 平板の総括熱伝達係数 U。"},{"x":"`supp-batch2-wall-rpp-v1` — 平板の面積当たり熱抵抗 R″。"},{"x":"`supp-batch2-tube-ratio-v1` — 円筒の内側基準と外側基準の U の比。"},{"x":"`supp-batch2-outer-base-u-v1` — 基準面積を取り替えたときの U。"},{"x":"`supp-batch2-fouling-loss-v1` — 汚れ抵抗の追加による熱移動率の低下。"},{"x":"`supp-batch2-g-times-dt-v1` — 全コンダクタンス UA と温度差から熱移動率を求める。"},{"x":"`supp-batch2-outer-h-decrease-v1` — 外側の h だけが低下したときの全体の UA。"},{"x":"`supp-roadmap-summary-contact-jump-v1` — 接触抵抗による界面の温度ジャンプ。"},{"x":"`supp-roadmap-summary-targeted-improvement-v1` — 中央の抵抗だけを半減したときの熱移動率の変化。"},{"x":"`supp-roadmap-summary-temperature-drop-v1` — 直列抵抗を通過したあとの出口温度。"},{"x":"`supp-roadmap-summary-cylinder-area-v1` — 円筒壁の対流抵抗で使う面積の選び方。"}]}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Patankar, S. V., *Numerical Heat Transfer and Fluid Flow*, Hemisphere, 1980（保存型有限体積法。アプリ内 #manual にも記載）。"},{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（支配方程式 §2.1、非定常伝導 第5章、物性 Appendix A）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/BENCHMARKS.json`、`docs/dynamic/PROVIDED_TEXTBOOK_BENCHMARKS_20261106.md`、`docs/dynamic/SURFACE_EXCHANGE.md`、`docs/dynamic/TEMPERATURE_DEPENDENT_CP.md`、`docs/dynamic/TRANSIENT_CONDUCTION_FREE_CONTOUR_SCOPE_20261107.md`、およびフェイリス側検証記録 `TRANSIENT_CLOSURE_VERIFICATION_20261107.md`（ブランチ `feiris/transient-closure-notes`）。"}]}]}]},{"id":"transient-radial","name":"円筒・球の半径方向 非定常熱伝導","source":"docs/dynamic/TRANSIENT_MANUAL_RADIAL_20261107.md","screen":{"href":"radial.html","label":"円筒・球の半径方向伝導の画面"},"lead":[{"label":"対象モデル","x":"分布モデル `dynamic/radial.mjs` と集中熱容量近似 `dynamic/lumped-radial.mjs`。画面は `dynamic/radial.html`（円筒と球の熱伝導実験）。数値コアの詳細は `docs/dynamic/RADIAL_CONDUCTION.md`。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"中実の円筒・球の内部で、温度が半径方向にだけ変化しながら時間とともに伝わっていく現象を計算する。温度が半径方向に分布する「分布モデル」と、内部が一様温度とみなす「集中熱容量近似」の2つのモデルがあり、近似の適用条件を満たす場合だけ後者を明示的に選べる。円筒は長さ方向に一様で端面は断熱という仮定のもとで、半径方向1Dとして扱う。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"金属球の焼入れ・冷却で、中心部が表面にどれだけ遅れて冷えるか。"},{"x":"球状の食品・薬品の加熱や冷却で、中心が目標温度に達する時間の見積り。"},{"x":"円柱状のシャフトや丸棒が、表面の温度変化に対して内部まで応答する時間の見通し。"},{"x":"蓄熱用の球・円柱材料の充放熱の応答確認。"}]},{"t":"p","x":"いずれも対称性と一定物性の仮定が成り立つ範囲の学習・概算のためであり、実設計の保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"分布モデル（`docs/dynamic/RADIAL_CONDUCTION.md`）："},{"t":"p","x":"ρcp ∂T/∂t = k · r^(1−d) · ∂[r^(d−1) ∂T/∂r]/∂r + q‴　（円筒 d=2、球 d=3）"},{"t":"p","x":"中心では対称条件 ∂T/∂r = 0。実装は 1/r を直接計算せず、各殻の積分保存則で組み立てる。"},{"t":"p","x":"集中熱容量近似（一定 h の対流・発熱なしの場合）："},{"t":"p","x":"T = T∞ + (T0 − T∞) · exp(−hAt / (ρcpV))"}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["T","温度（内部計算は絶対温度、表示は ℃）","K"],["r, R","半径方向座標、物体の半径","m"],["L","円筒の長さ","m"],["A(r)","半径 r の伝熱面積（円筒 2πrL、球 4πr²）","m²"],["k, ρ, cp","熱伝導率、密度、比熱（一定物性）","W/(m·K), kg/m³, J/(kg·K)"],["q‴","一様な体積発熱密度","W/m³"],["h","熱伝達率（入力値。流れから予測しない）","W/(m²·K)"],["ε, σ","放射率、ステファン・ボルツマン定数 5.670374419×10⁻⁸ W/(m²·K⁴)","—"],["α = k/(ρcp)","熱拡散率","m²/s"],["Fo = αt/R²","フーリエ数","—"],["Lc = V/A","集中近似の代表長さ（球 R/3、円筒側面のみ R/2）","m"],["Bi","ビオ数。集中近似の判定は Bi = hLc/k、半径基準の表示は Bi = hR/k で、両者は別物（項目13）","—"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"一様な初期絶対温度を与える。分布モデルの温度値は各殻の平均の代表値であり、中心 r=0 の点温度ではない（項目9・13）。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"ul","items":[{"x":"中心（r=0）：面積ゼロの対称条件（熱流ゼロ）。架空セルや r=0 での除算は使わない。"},{"x":"外表面：温度固定、断熱、内向き熱流束、指定 h の対流、大きな黒い周囲への放射、対流＋放射の同時境界（共通表面温度を解く。矩形 FVM の説明書項目6と同じ仕組み）。表面までの半セルの勾配抵抗 Δr/(2kA) を含み、対流では 1/(hA) と直列にする。放射では表面温度を二分法で求める（`docs/dynamic/RADIAL_CONDUCTION.md`）。"},{"x":"円筒の端面：断熱（モデルの定義そのもの）。"}]}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"殻（同心の層）ごとの保存型有限体積法。殻体積は円筒 πL(r₊²−r₋²)、球 4π(r₊³−r₋³)/3、内部面の熱量は Gᵢ(Tᵢ₊₁−Tᵢ)（Gᵢ = kA(r面)/Δr）として両隣へ等量・逆符号で計上する。"},{"x":"時間積分は前進 Euler で、Δt ≤ 0.8 × min(Cᵢ/ΣGᵢ)。"},{"x":"集中近似は指数式そのものを評価し、PDE を粗い1セルで解く方法ではない。格子・内部刻みは使わない。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"形状（球／円筒）・半径・材料・初期温度・外表面の境界を選んで適用する。"},{"x":"殻の数と刻みで時間を進め、断面表示・断面グラフ・履歴で応答を確認する。"},{"x":"集中近似を使う場合は、先に Bi = h(V/A)/k ≤ 0.1 を満たすかを確認する（満たさなければ選択自体が拒否される）。"}]},{"t":"p","x":"手計算による検算の例（出典：`dynamic/radial.html` #manual「数値例と検算」、`docs/dynamic/RADIAL_CONDUCTION.md`）："},{"t":"ul","items":[{"x":"一様な断熱発熱なら全殻で ΔT = q‴t/(ρcp)。発熱なし・断熱なら温度は不変。"},{"x":"一定表面温度の発熱定常解は、球 T(r) = T面 + q‴(R²−r²)/(6k)、円筒 T(r) = T面 + q‴(R²−r²)/(4k)。"},{"x":"R = 0.01 m、k = 10 W/(m·K)、ρ = 1000 kg/m³、cp = 1000 J/(kg·K) なら α = 10⁻⁵ m²/s で、t = 1 s のフーリエ数は Fo = αt/R² = 0.1。"}]}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"画面の断面図は、半径方向1Dの計算値を円の断面へ配置した表示である。2D/3Dの温度場を解いた結果ではない（アプリ内 #manual「はじめに」に明記）。"},{"x":"断面グラフの線は殻中心の代表値と実際の外表面温度を結ぶ補助表示で、中心 r=0 の点温度は推測していない（`dynamic/radial.html` の断面表示の説明）。"},{"x":"測定値は「殻平均の代表値」であり、点温度の厳密値ではない。外表面温度は別に表示される。"},{"x":"集中近似の画面で内部が一様色・断面が水平なのは、近似の仮定そのものの表示である。内部の熱流を計算した矢印は描かれない。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"ul","items":[{"x":"収支誤差（ベンチマークでは概ね 10⁻¹² J 以下）と温度の離散化誤差は別の量であり、混同しない（`docs/dynamic/RADIAL_CONDUCTION.md`）。"},{"x":"検証の実測（出典：同文書のベンチマーク表。連続の固有関数級数を各殻体積で積分した独立参照との比較）：","sub":{"t":"ul","items":[{"x":"温度固定：体積重み付き殻平均 RMS は 16殻 0.044231 K → 32殻 0.011280 K → 64殻 0.002849 K（球、次数 1.97→1.99）、円筒は 0.037096 → 0.009277 → 0.002321 K（約2.00）。"},{"x":"対流：球 0.004126 → 0.001031 → 0.000258 K、円筒 0.010641 → 0.002648 → 0.000661 K（約2次）。時間だけを細分化した収束は約1次。"},{"x":"定常解への漸近では、球（表面等温）の測定減衰率 0.004848 /s が連続第1固有値 απ²/R² = 0.004935 /s と比 0.982 で一致（フェイリス側検証記録 `TRANSIENT_CLOSURE_VERIFICATION_20261107.md`、ブランチ `feiris/transient-closure-notes`）。"}]}},{"x":"集中近似の誤差はゼロではない。独立した連続 PDE の体積平均との標本比較では、初期温度差の最大約 2.12% が残った（初期差 50 K なら約 1.06 K の例。アプリ内 #manual「軽量な集中熱容量近似」）。分布モデルの格子誤差と、集中近似のモデル誤差を区別すること。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"半径対称（角度方向・軸方向の変化なし）。円筒の端面は断熱。"},{"x":"単一材料・一定物性。相変化は扱わない。"},{"x":"熱伝達率 h は入力値で、風速・浮力・流速場から計算しない。放射は灰色面と大きな黒い周囲（形態係数1）のモデル。"},{"x":"集中近似は内部一様温度を仮定し、一定 h の対流・発熱なし・一様初期温度の場合に限る。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"中空の円筒・球、複合（多層）材料、温度依存物性は扱わない（径方向の複合・中空は監査の残作業 #1／順序5として別途の実装課題に残る。範囲確定記録 `TRANSIENT_CONDUCTION_SCOPE_20261107.md` 参照）。"},{"x":"円筒の端面効果・軸方向変化は対象外として確定している（同記録）。"},{"x":"流体側を解く連成は扱わない（境界は規定温度に対する表面収支のみ）。"},{"x":"20℃の物性参考値を他の温度でも実物性として保証するものではない。無条件に工学設計へ使わない。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「表示された殻の温度が、その半径の点温度」** — 誤り。殻平均の代表値であり、特に中心の点温度は表示から推測できない。"},{"x":"**「Bi の定義は1つだけ」** — 誤り。集中近似の判定に使う Bi = h(V/A)/k と、半径基準の Bi = hR/k は別で、球では前者は後者の 1/3、円筒側面では 1/2 になる（アプリ内 #manual「数値例と検算」）。"},{"x":"**「集中近似で内部一様に描かれるのは計算結果」** — 誤り。一様性は近似の仮定であり、誤差は項目10のとおり残る。"},{"x":"**「円筒の長さを変えると半径方向の温度分布も変わる」** — 誤り（端面断熱の範囲）。長さは全熱量には影響するが、半径方向の変化は変えない（アプリ内 #manual「はじめに」）。"},{"x":"**「同じ半径の球と円筒は同じ速さで冷える」** — 誤り。外面積/体積は球が 3/R、円筒の側面が 2/R と異なり、学習実験でもこの違いを観察する。ただし表面温度固定では内部に分布があるため、この比をそのまま集中近似の時定数へ置き換えることもできない。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"アプリの教材：§5.4「温度応答線図」、§5.5「一項近似解」（アプリ内 #manual から `../index.html#reader/5.4`、`#reader/5.5` へリンク済み）。集中近似については §5.2「集中熱容量解」。"},{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、第5章（§5.2 集中熱容量、§5.4 温度応答線図、§5.5 一項近似）、Appendix A（物性値）。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第3.2節）に基づく。記載した ID はすべて問題バンク `data/questions.json` の実在 ID であり、アプリの演習（`../index.html#quiz`）でそのまま検索できる。"},{"t":"p","x":"主掲載は次の 3 件（全件）。本文が円柱・球の分布系を直接扱う問題はバンク内でもこの 3 件に限られ、専用問題は少ない。基礎（集中熱容量・Bi・Fo）は矩形の説明書の項目15と共通である。"},{"t":"ul","items":[{"x":"`supp-transient-gap-one-term-cylinder-shape-v1` — 長い円柱の半径方向対流冷却における固有関数と根条件の組合せ。"},{"x":"`supp-transient-gap-sphere-lumped-length-v1` — 球の集中近似で使う代表長さ L_c=R/3 と Bi。"},{"x":"`supp-transient-gap-chart-radius-definition-v1` — 球の温度応答線図における Bi=hR/k・Fo=αt/R² の半径の定義と、集中近似の L_c との混同の回避。"}]},{"t":"p","x":"相互参照：定常の円筒壁抵抗は本モデルの定常極限であり、`supp-chapter-ch2-cylinder-resistance`、`supp-chapter-ch2-cylinder-watts`、`supp-roadmap-summary-cylinder-area-v1` が関連する（主掲載は矩形の説明書の項目15「複合材料（多層・界面）」）。"}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（第5章、Appendix A の20℃物性値。アプリ内 #manual にも記載）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/RADIAL_CONDUCTION.md`（数値コアとベンチマーク表）、`scripts/dynamic-radial-reference.py` と `docs/dynamic/RADIAL_CONTINUOUS_REFERENCE_20261104.json`（Bessel／固有関数級数による独立連続参照、mpmath 50桁照合を含む）、`docs/dynamic/SURFACE_EXCHANGE.md`、フェイリス側検証記録 `TRANSIENT_CLOSURE_VERIFICATION_20261107.md`（ブランチ `feiris/transient-closure-notes`）。"}]}]}]},{"id":"transient-triangle","name":"三角形系 非定常熱伝導","source":"docs/dynamic/TRANSIENT_MANUAL_TRIANGLE_20261107.md","screen":null,"lead":[{"label":"対象モデル","x":"凸多角形の P1 有限要素による開発専用モデル群。コアは (1) 全周固定温度 `dynamic/dev/triangle-diffusion.mjs`、(2) 線形混合境界 `dynamic/dev/triangle-linear-transient.mjs`、(3) 同一面の対流＋放射 `dynamic/dev/triangle-surface-transient.mjs`。開発 GUI は `dynamic/dev/triangle-diffusion.html`、`dynamic/dev/triangle-linear.html` ほか（開発用 allowlist サーバーでのみ配信し、公開ビルドには含めない）。"},{"label":"注意","x":"このモデル群は `releaseApproved:false` の**開発専用**であり、一般公開用の解析機能としては有効化されていない。実機・支援技術での確認も未完了である。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"三角形・多角形の断面を持つ物体の内部で、温度が時間とともに伝わっていく現象を、2D断面のまま計算するモデルである。矩形 FVM（直交格子）では形を階段近似しなければならない凸多角形の輪郭を、輪郭に沿った三角形要素でそのまま表す点が特徴である。奥行き方向は一様で、前後の面からは熱交換しない。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"三角形・台形・多角形の断面を持つ部材（梁、成形品、放熱部材の根元など）が加熱・冷却されるときの内部温度の遅れ。"},{"x":"断面形状そのものが温度分布へどう影響するか（角部への熱の回り込みなど）の学習。"},{"x":"多角形断面の電子部品・筐体部品の温度応答の概算。"}]},{"t":"p","x":"開発専用モデルであり、実設計の保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"一定物性・等方性の場合の熱伝導方程式（教科書 §2.1）："},{"t":"p","x":"ρcp ∂T/∂t = ∇·(k∇T) + q‴"},{"t":"p","x":"離散化した各節点 i については、開発文書の形で"},{"t":"p","x":"C_i dθ_i/dt = P_i − Σ_j G_ij (θ_i − θ_j)"},{"t":"p","x":"と書ける。θ は基準温度からの温度差（コアにより θ = T − Tw または θ = T − Tref）、C_i は節点の lumped 熱容量、G_ij は要素から組み立てた節点間のコンダクタンス、P_i は体積発熱の配分である（`docs/dynamic/TRIANGLE_TRANSIENT_DEVELOPMENT.md`）。"}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["T, θ","絶対温度、基準温度からの温度差","K"],["C_i","節点 i の lumped 熱容量","J/K"],["G_ij","節点 i−j 間の伝導コンダクタンス","W/K"],["D","奥行き（断面に一様）","m"],["k, ρ, cp","熱伝導率、密度、比熱（一定物性のみ）","W/(m·K), kg/m³, J/(kg·K)"],["q‴（文書中 qvol）","一様な体積発熱密度","W/m³"],["h","熱伝達率（線形混合境界コア・表面コア。入力値）","W/(m²·K)"],["ε, σ","放射率、ステファン・ボルツマン定数 5.670374419×10⁻⁸ W/(m²·K⁴)","—"]]},{"t":"p","x":"重要な区別：このモデル群の温度は**節点値**であり、矩形 FVM のセル平均ではない。要素内部の温度は節点値の線形補間（P1 場）として定義される。"}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"初期温度は、スカラー（一様）で与える場合は内部節点の温度として解釈され、境界節点は境界条件の値を取る。配列で与える場合は全節点分が必要で、境界節点も条件値と一致しなければならない。不連続な初期条件は、境界近傍の要素内では線形の初期近似になる（均一な連続初期場をそのまま表したとは言えない。`docs/dynamic/TRIANGLE_TRANSIENT_DEVELOPMENT.md`）。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"p","x":"コアごとに扱える条件が異なる。"},{"t":"ul","items":[{"x":"全周固定温度コア（triangle-diffusion）：全境界が一様な固定温度 Tw のみ。"},{"x":"線形混合境界コア（triangle-linear-transient）：辺ごとに固定温度／断熱／外向き指定熱流束／Robin（対流。境界積分の row-lumping で扱い、h を計算する流体モデルではない）。"},{"x":"表面コア（triangle-surface-transient）：同一面の対流＋放射を実境界節点で扱う。h(T−T∞) + εσ(T⁴−Tr⁴)、大きな黒い周囲を指定し、流体温度と放射周囲温度は別入力。一般の形態係数ネットワークや参加媒体は含まない。"}]}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"空間：P1（線形）三角形要素による有限要素離散化。熱容量は節点へ lumped（集中）させる。対象は凸多角形（3〜12頂点）で、未知節点に負の伝導係数が接続しない形状だけを受理する。"},{"x":"時間：SSPRK2（2段の強安定性 Runge–Kutta）。刻みは dt ≤ 0.8 × min(C_i / 対角項) を上限とし、候補温度の符号と最大原理の範囲を監視する。"},{"x":"表面コアの放射は割線コンダクタンス G = εσ(A/2)(T+Tr)(T²+Tr²) で評価し（nodal-lumping：辺の面積 A を両端節点へ A/2 ずつ配分）、放射微分の上限を刻み制限に含める。"},{"x":"境界熱の数え方：保存則に使う境界熱は、固定節点の反力などからなる**離散反力**で数える。別に、要素の片側勾配 −k∇T を境界小辺で積分した量も返すが、両者は別の量であり区別して表示する（項目13）。"},{"x":"後処理として RT0 平衡回復流束（`dynamic/dev/triangle-flux-recovery.mjs` 等）があるが、温度場を解き直すものではなく、その物理精度は未検証である（scope に `physicalFluxAccuracyVerified:false` と明示）。"},{"x":"失敗時（上限温度超過、非有限値、無効な刻みなど）は温度・時計・積算値を変えず、元の状態を保持する（原子性）。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"凸輪郭（頂点）と分割数、材料・発熱・境界条件を設定して初期化する。"},{"x":"SSPRK2 で時間を進め、温度場（P1 補間）、顕熱、累積発熱、境界出熱（反力）と収支差を監視する。"},{"x":"分割を変えて結果を比較し、粗い格子での誤差の大きさを確認する。"}]},{"t":"p","x":"手計算による検算の例（出典：`docs/dynamic/TRIANGLE_TRANSIENT_DEVELOPMENT.md`）：単位正方形で中心だけが未知節点、中心 350 K／境界 300 K の場合、中心の容量は 10000 J/K、対角コンダクタンスは 1.8 W/K、離散反力は 90 W になる。一方、要素の片側勾配から積分した境界熱は 180 W であり、両者が一致しないこと自体が、粗い要素での「境界熱」の定義依存性を示す検算になっている。"}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"開発 GUI の温度場は、実際の節点温度を画素位置で P1 線形補間して描く。三角形ごとの単色塗りではなく、架空のセル平均でもない（`docs/dynamic/TRIANGLE_UI_DEVELOPMENT.md`）。"},{"x":"領域外には値を作らず、透明マスクと測定不可で示す。測定点は物理座標で選び、A/B 比較では同じ物理座標・倍率・温度凡例・物理時刻で並べる。"},{"x":"履歴は実際に保存された節点値の補間である。"},{"x":"片側勾配から描く熱流の表示は、保存的に回復した熱流束ではない。矢印があるからといって保存流束と読まない（項目13）。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"ul","items":[{"x":"精度は節点誤差だけでなく、要素内部まで含めた**全場誤差**で読む。検証では P1 場全体と連続場の L2 差を面積積分して評価している。"},{"x":"検証の実測（出典：`docs/dynamic/TRIANGLE_TRANSIENT_DEVELOPMENT.md`。回転した 0.4×0.2 m 矩形、k=15、ρ=1000、cp=1000、D=0.03 m、Tw=300 K、連続解は sin 積の固有モード）：","sub":{"t":"ul","items":[{"x":"全場 RMS は分割 n=2／4／8／16 で 4.70778 → 1.19817 → 0.29883 → 0.0744317 K、結合精細化の次数は 1.974／2.003／2.005。"},{"x":"全熱の相対差は −17.061% → −0.2963%、反力による境界熱の相対差は −24.560% → −0.5816%。粗い n=2 では収支差が約 5.46e-12 J と小さくても、全熱は連続解から 17% 違う。保存則の一致を精度の証拠と読まない。"},{"x":"固定格子の時間検証（行列指数による独立参照）：dt = 5／2.5／1.25 s で最大時間誤差 0.000987562／0.000233304／0.0000567218 K、次数 2.082／2.040。"}]}},{"x":"線形混合境界コアの全場 RMS（出典：`docs/dynamic/TRIANGLE_LINEAR_TRANSIENT.md`）：固定温度／断熱のケースで 1.011346 → 0.0163464 K（n=2→16、最終次数 約1.996）、対流／断熱のケースで 0.421204 → 0.00672906 K（約1.997）。"},{"x":"表面コアは固定格子で DOP853 参照と照合し、時間次数 2.00109（矩形）／2.00073（五角形）、最細の最大差 1.45838e-6 K／1.30309e-7 K（`docs/dynamic/TRIANGLE_SURFACE_TRANSIENT.md`）。これは固定格子の時間検証であり、一般の連続過渡場の空間精度とは呼ばない。"},{"x":"定常解への漸近では、正方形（左右等温・上下断熱）の測定減衰率 1.484e-4 /s が連続第1固有値 απ²/L² = 1.480e-4 /s と比 1.002 で一致（フェイリス側検証記録 `TRANSIENT_CLOSURE_VERIFICATION_20261107.md`、ブランチ `feiris/transient-closure-notes`）。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"凸多角形のみ。凹・穴・曲線輪郭は扱わない。"},{"x":"一定物性・単一材料。奥行き方向は一様で、前後面の熱交換はない。"},{"x":"表面コアの放射は、規定された大きな黒い周囲への放射のみ（囲いの形態係数ネットワークではない）。"},{"x":"熱伝達率 h は入力値であり、流れは解かない。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"変物性 k(T)／cp(T) と複合材料（多層・界面）は扱わない。これらは Phase 3 の対象外として確定している（範囲確定記録 `TRANSIENT_CONDUCTION_SCOPE_20261107.md`。変物性・複合材料は分野として矩形 FVM が担う）。"},{"x":"放射囲い連成、参加媒体、3D は扱わない。"},{"x":"RT0 回復流束は後処理であり、物理精度は未検証。"},{"x":"開発専用（`releaseApproved:false`）で公開されておらず、実機・支援技術での操作確認も未完了。一般公開用の解析機能として有効化しない（正本 §6.4）。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「節点の温度はセル平均温度」** — 誤り。節点値であり、要素内は線形補間で定義される。矩形 FVM のセル平均と読み替えると、境界近傍の解釈を誤る。"},{"x":"**「片側勾配を積分した境界熱が、保存される境界熱」** — 誤り。保存則に使うのは離散反力であり、片側勾配の積分は別の量である。項目8の手計算例では 90 W と 180 W のように大きく異なる。"},{"x":"**「エネルギー収支が合えば精度も高い」** — 誤り。粗い格子では収支差が 10⁻¹² J 級でも全熱が 17% ずれる（項目10）。保存性と精度は別に評価する。"},{"x":"**「時間積分が2次（SSPRK2）だから熱流束も2次精度」** — 誤り。時間次数と、勾配・熱流束の空間精度は別の話である。"},{"x":"**「RT0 回復流束は解き直した正確な熱流束場」** — 誤り。温度場を変えない後処理であり、物理精度は未検証と明示されている。"},{"x":"**「境界節点へ配分された発熱は壁面の熱流と同じ」** — 誤り。lumped 配分による境界反力への直接寄与は格子依存の離散化効果で、連続な一様初期場の瞬時壁熱とは異なる（`docs/dynamic/TRIANGLE_TRANSIENT_DEVELOPMENT.md`）。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、§5.7「定常多次元熱伝導」、§5.8「非定常多次元熱伝導」、§2.1（熱伝導方程式）。"},{"x":"アプリの教材では第5章の多次元熱伝導の節が対応する。開発専用モデルのため、公開画面からの直接リンクは設けていない。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第3.3節・第8節）に基づく。"},{"t":"p","x":"**現行の問題バンク（751問）に、本モデル（三角形要素の2次元非定常）に対応する問題はない。** バンク全体の棚卸しでも、三角形要素・自由形状の2次元非定常を扱う問題は存在しない。推測で埋めず、その事実をここに明記する。"},{"t":"p","x":"最も近いのは、矩形前提の2次元伝導を扱う次の問題である（いずれも主掲載は矩形の説明書の項目15であり、本モデルの関連問題として断定はしない）。"},{"t":"ul","items":[{"x":"`supp-transient-gap-product-center-v1` — 分離可能な矩形冷却の積解による中心温度。"},{"x":"`supp-transient-gap-multidim-flux-components-v1` — 2次元温度場における熱流ベクトルの成分。"},{"x":"`supp-transient-gap-multidim-mesh-check-v1` — 数値の2次元伝導結果に対する検証の進め方。"}]},{"t":"p","x":"なお本モデルは開発専用であり、公開画面からアプリの演習への導線はない。"}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（第5章、特に §5.7・§5.8）。"},{"x":"Patankar, S. V., *Numerical Heat Transfer and Fluid Flow*, Hemisphere, 1980（保存型の離散化と収支の考え方の一般参考。矩形 FVM の説明書にも記載）。"},{"x":"本リポジトリの開発・検証文書：`docs/dynamic/TRIANGLE_TRANSIENT_DEVELOPMENT.md`、`docs/dynamic/TRIANGLE_LINEAR_TRANSIENT.md`、`docs/dynamic/TRIANGLE_SURFACE_TRANSIENT.md`、`docs/dynamic/TRIANGLE_FLUX_RECOVERY.md`、`docs/dynamic/TRIANGLE_UI_DEVELOPMENT.md`、フェイリス側検証記録 `TRANSIENT_CLOSURE_VERIFICATION_20261107.md`（ブランチ `feiris/transient-closure-notes`）。"}]}]}]},{"id":"fin-straight-tip","name":"直線フィン（先端条件つき）","source":"docs/dynamic/FIN_MANUAL_STRAIGHT_TIP_20261107.md","screen":null,"lead":[{"label":"対象モデル","x":"開発専用モジュール `dynamic/dev/fin-convective-tip.mjs`（`createStraightFin`、法則識別子 `straight-fin-convective-tip-1d-v1`）。フェイリス側ブランチ `feiris/fin-convective-tip`（起点 `f9bdfef`、コミット `9f7f267`）の成果物で、統合ツリーの `dynamic/dev/` に開発画面（GUI）を含む。Worker はなく、数値コアとそのスナップショット、および開発画面が対象である。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"一定断面（厚さ×奥行きの矩形断面）の直線フィンについて、軸方向1Dの非定常伝導を計算する。基部は指定温度 Tb に固定され、側面は一様な h で周囲 T∞ と熱交換する。先端は、同じ h で対流する条件と断熱条件を切り替えられる。先端が実際には対流しているのに断熱で近似すると、短いフィンほど熱流量を過小評価する（項目10）。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"ヒートシンクの板フィン1本について、先端の放熱を無視してよいかどうかの判定。"},{"x":"空冷フィンの概算で、教科書の修正長さ法（項目13）を使ってよい条件かどうかの確認。"},{"x":"断熱先端の古典解（tanh 型）と対流先端の厳密解の差が、フィン長さでどう変わるかの学習。"}]},{"t":"p","x":"いずれも一定物性・指定 h・断面一様の仮定が成り立つ範囲の学習・概算のためであり、実設計の保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"ρcp ∂T/∂t = k ∂²T/∂x² − (hP/Ac)(T − T∞)　（P は周長、Ac は断面積、m² = hP/(kAc)）"},{"t":"p","x":"定常の解析解（θ = T − T∞、θb = Tb − T∞、H = h/(mk)）："},{"t":"p","x":"θ(x)/θb = [cosh(m(L−x)) + H sinh(m(L−x))] / [cosh(mL) + H sinh(mL)]"},{"t":"p","x":"対流先端では H = h/(mk)、断熱先端では H = 0 で古典解に帰着する（出典：`FIN_CONVECTIVE_TIP_DEVELOPMENT.md`）。"}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["T","温度（絶対温度で入力・出力）","K"],["x, L","基部からの軸方向座標、フィン長さ","m"],["thickness, depth","断面の厚さ、奥行き","m"],["Ac","断面積（thickness × depth）","m²"],["P = 2(thickness + depth)","周長","m"],["k, ρ, cp","熱伝導率、密度、比熱（一定物性）","W/(m·K), kg/m³, J/(kg·K)"],["h","熱伝達率（入力値。流れから予測しない）","W/(m²·K)"],["Tb, T∞","基部温度、周囲流体温度","K"],["m = √(hP/(kAc))","フィン定数","1/m"],["H = h/(mk)","先端対流の無次元パラメータ（断熱先端では 0）","—"],["Bi = h(Ac/P)/k","断面ビオ数（断面一様の開発範囲の検査に使う。既存学習モデル `steadyFinPrediction` の crossSectionBi と同じ定義）","—"],["A_s","対流に触れる全表面積（断熱先端では PL、対流先端では PL + Ac）","m²"],["η = 実損失/(h·A_s·θb)","フィン効率","—"],["ε = 実損失/(h·Ac·θb)","フィン有効度","—"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"一様な初期絶対温度（スカラー）か、セルごとの初期温度配列を与える。配列の長さはセル数と一致しなければならず、不一致は拒否される。温度値は各セルの代表値であり、点温度ではない（項目9・13）。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"ul","items":[{"x":"基部（x = 0）：指定温度 Tb に固定。"},{"x":"側面：一様な h で周囲 T∞ と熱交換。"},{"x":"先端（x = L）：`tipCondition` で切替可能。","sub":{"t":"ul","items":[{"x":"`convection`：先端面が同じ h で周囲と熱交換する（−k ∂T/∂x|_L = h (T(L) − T∞)）。"},{"x":"`insulated`：断熱（∂T/∂x|_L = 0）。"}]}}]}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"セル中心有限体積法。基部面は半セル抵抗（G0 = kAc/(dx/2)）、内部面は Gi = kAc/dx、側面損失はセルごとに Gs = hP·dx、先端損失は対流時のみ Gt = h·Ac を最終セルへ課す。"},{"x":"時間積分は前進 Euler で、安定刻み `safeDt` は全セルの流出率最大値の0.8倍を上限とし、超過する刻みは拒否する。"},{"x":"外部熱量の累積は補償和（Kahan）で積算し、各ステップで蓄熱変化との差が丸め誤差予算（128·EPSILON 基準）以内であることを検証する。失敗したステップ・復元は受理状態を変更しない（原子的拒否）。"},{"x":"入力検証：未知キーは「未対応の物理条件を暗黙に無視しません」として拒否する。非有限・範囲外も日本語エラーで拒否する。セル数は 4〜256。断面一様の開発範囲として断面 Bi = h(Ac/P)/k ≤ 0.1 を検査する。監視温度上限は既定 10000 K。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"形状（L・厚さ・奥行き）・材料・h・Tb・T∞・初期温度・先端条件・セル数を指定して生成する。"},{"x":"`safeDt` 以下の刻みで時間を進め、スナップショットの温度配列・基部流入・側面／先端損失・収支誤差で応答を確認する。"},{"x":"定常の検算は解析解（項目3・10）と比べる。"}]},{"t":"p","x":"手計算による検算の例（出典：`FIN_CONVECTIVE_TIP_DEVELOPMENT.md` の正準条件）：L = 0.1 m、厚さ・奥行き 0.01 m、k = 200、ρ = 2700、cp = 900、h = 25、Tb = 353.15 K、T∞ = 293.15 K では m = 7.071068 /m、H = 0.017678（対流先端）、定常 q = 5.2597314113 W（対流先端）／5.1663430295 W（断熱先端）。"}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"公開画面はないが、開発画面（公開ビルドには含まれない）にはグラフ表示がある。公開側で結果を読む場合はスナップショットの数値配列を使う。"},{"x":"`temperature` はセル中心位置 `positions` における代表値の配列である。`tipCellTemperatureK` は最終セルの代表値であり、先端面 x = L の温度ではない。解析的な先端面温度は参照記録に別途ある（正準条件で対流先端 340.239853 K、断熱先端 340.746691 K）。"},{"x":"η・ε は過渡中は瞬時損失ベースの診断量であり、定常到達時に古典値と一致する（項目13）。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"ul","items":[{"x":"検証の実測（出典：`FIN_CONVECTIVE_TIP_DEVELOPMENT.md`、参照は50桁 mpmath の解析解と行列指数による独立伝播。正準条件）：","sub":{"t":"ul","items":[{"x":"定常解析値：対流先端で q = 5.2597314113 W、η = 0.855240880、ε = 35.0648761。断熱先端で q = 5.1663430295 W、η = 0.861057172、ε = 34.4422869（断熱側は既に照合済みの閉形式値と生成器内で一致を確認）。"},{"x":"定常場の RMS 誤差（対セル平均、n=16/32/64）：対流先端 0.015835 / 0.003982 / 0.001007 K（空間次数 1.992 / 1.984）、断熱先端 0.015770 / 0.003944 / 0.000986 K（次数 2.000 / 2.000）。JS 定常解と独立ネットワークの離散定常解は全格子で RMS 1e-7 K 未満で一致する。"},{"x":"断熱帰着：n=64 の JS 定常で η = 0.8610408（照合済み値との差 1.6e-5）、q = 5.1662450 W（差 9.8e-5 W）。"},{"x":"過渡（n=16、t = 20 s）：行列指数参照との最大差は刻み safeDt/2 で 0.0213 K、safeDt/4 で 0.0106 K。時間次数は 0.9985 / 0.9990（前進 Euler の1次と一致）。"}]}},{"x":"先端対流の効果：短フィン条件（L = 0.02 m、厚さ 0.002 m、奥行き 0.05 m、他は正準と同じ）では、先端対流により定常熱流量が断熱先端比で +4.6336%（解析）／+4.6338%（JS 実測、n=32）増え、先端損失は 0.14583 W だった。正準条件でも +1.81% の増加がある。フィンが短いほど先端の寄与は相対的に大きい。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"一定断面・一定物性。断面内は一様温度（Bi ≤ 0.1 を開発範囲として検査）。"},{"x":"側面と先端で同じ h。基部温度は固定。"},{"x":"スナップショットの assumptions に明記：修正長さ近似ではない（`correctedLengthApproximation:false`）、放射なし、流体連成なし、2D伝導・基部熱拡がりなし。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"Worker 接続・公開可否は未実施。GUI とそのブラウザー確認（Chromium）は開発画面で実施済み。`releaseApproved:false`、公開 allowlist 外。"},{"x":"先端だけ別の h、軸方向に変化する h は未対応。変断面フィン、温度依存物性、放射、基部の2D熱拡がり・接触抵抗、複数フィン／フィン間流れは未対応で、入力は原子的に拒否されるか assumptions に明示している。風速→h 推定は別モジュール（`wind-heat-transfer.mjs`）の担当で、本モジュールには含まない。"},{"x":"開発範囲は断面 Bi ≤ 0.1、セル数 4〜256 で、範囲外は推定値を返さず拒否する。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「修正長さ法 Lc = L + Ac/P は厳密解」** — 誤り。断熱近似の一種であり、対流先端の厳密解との差は正準条件で相対誤差 0.00018%、短フィン条件でも 0.00018% と本条件範囲では非常に小さいが、近似であることに変わりはない。本モジュールは修正長さを使わず、先端面の対流を直接離散化している。なお L のままの断熱式では相対誤差 1.7755%（正準）／4.4284%（短フィン）になる。"},{"x":"**「先端温度の出力が先端面の温度」** — 誤り。最終セルの代表値であり、先端面の解析値は参照記録に別途ある（項目9）。"},{"x":"**「過渡中の η がそのまま定常のフィン効率」** — 誤り。過渡中は瞬時損失ベースの診断量であり、定常到達時に古典値と一致する。"},{"x":"**「対流先端では η の分母に先端面を入れてはいけない」** — 誤り。本モデルと既存学習モデルでは、対流先端の場合 A_s に先端面 Ac を含める定義で統一している（項目4）。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、§4.5「Fin design」（フィン方程式・効率・有効度・先端条件と修正長さの扱い）。"},{"x":"アプリの教材：フィン学習画面（`dynamic/fin-learning.html`、開発文書 `docs/dynamic/FIN_LEARNING.md`）が断熱先端の直線フィンで η・ε を扱う。本モデルは開発専用のため公開画面からの導線はない。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第4.1節）に基づく。記載した ID はすべて問題バンク `data/questions.json` の実在 ID であり、アプリの演習（`../index.html#quiz`）でそのまま検索できる。主掲載は次の 12 件（全件）。このうち `supp-deep-fin-base-heat-v1` 以下の deep 系 4 件は、本モデルの検証正準ケース（k=200、h=25、P=0.04、A_c=1.0×10⁻⁴、L=0.10、ΔT=60）と同一条件であり、対応が特に強い。"},{"t":"ul","items":[{"x":"`supp-chapter-ch4-fin-m` — 一定断面の直線フィンでフィン変数 m を求める。"},{"x":"`supp-chapter-ch4-fin-eta` — 先端断熱の直線フィンの効率 η=tanh(mL)/(mL)。"},{"x":"`supp-chapter-ch4-fin-concept` — フィンの長さだけを増やしたときの効率と総放熱量の変化。"},{"x":"`supp-section-4-5` — フィン効率が下がっても総放熱量が必ず下がるとは言えないこと（第4.5節の学習ノート）。"},{"x":"`supp-advanced-ch4-calc` — mL=2.0 の先端断熱フィンの効率。"},{"x":"`supp-applied-4-5-v1` — mL=1.5 の断熱先端フィンの効率。"},{"x":"`supp-deep-fin-base-heat-v1` — 断熱先端の一定断面フィンの基部放熱量。"},{"x":"`supp-deep-fin-effectiveness-v1` — 基部放熱量からフィン有効度 ε を求める。"},{"x":"`supp-deep-fin-tip-temperature-v1` — 一定断面・先端断熱フィンの先端温度。"},{"x":"`supp-deep-fin-convective-tip-v1` — 対流先端の境界条件そのものを扱う問題。"},{"x":"`supp-existing-fin-contact-loss-v1` — 基部に接触熱抵抗がある場合の影響。"},{"x":"`supp-existing-fin-lateral-uniformity-v1` — 一次元モデルで断面内の温度差を無視できるかの判断。"}]}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（§4.5、Appendix A の物性値）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/FIN_CONVECTIVE_TIP_DEVELOPMENT.md`（数値コア・仮定・検証実測）、`docs/dynamic/FIN_CONVECTIVE_TIP_REFERENCE_20261107.json` と生成器 `scripts/dynamic-fin-convective-tip-reference.py`（50桁解析解と行列指数参照）、`docs/dynamic/FIN_LEARNING.md` と `docs/dynamic/FIN_LEARNING_REFERENCE_20261105.json`（断熱先端の閉形式値の正）。"}]}]}]},{"id":"fin-annular","name":"環状フィン","source":"docs/dynamic/FIN_MANUAL_ANNULAR_20261107.md","screen":null,"lead":[{"label":"対象モデル","x":"開発専用モジュール `dynamic/dev/annular-fin.mjs`（`createAnnularFin`、法則識別子 `annular-fin-radial-1d-v1`）。フェイリス側ブランチ `feiris/annular-fin`（起点 `7968146`、コミット `ffe7c25`）の成果物で、統合ツリーの `dynamic/dev/` に開発画面（GUI）を含む。Worker はなく、数値コアとそのスナップショット、および開発画面が対象である。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"管（外半径 r1）の外周に取り付けた厚さ t 一様の円盤フィン1枚について、温度が半径方向にだけ変化しながら時間とともに伝わっていく現象を計算する。フィンの両側面は同一の指定 h で周囲 T∞ へ対流する。基部（管との接合面）は指定温度 Tb に固定される。先端の扱いは、対流する厳密な先端面と、修正半径による断熱近似の2方式から選べる。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"空冷式熱交換器やラジエータのフィン付き管で、1枚の円盤フィンがどれだけ放熱を受け持つかの学習・概算。"},{"x":"円形フィンを持つ発熱体の冷却で、フィン外縁まで温度がどれだけ下がるかの見通し。"},{"x":"修正半径近似（項目6）が実務でどの程度の誤差を持つかの確認。"}]},{"t":"p","x":"いずれも一定物性・指定 h・半径方向1Dの仮定が成り立つ範囲の学習・概算のためであり、実設計の保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"θ = T − T∞、m² = 2h/(kt) として、定常の支配方程式は Bessel 型"},{"t":"p","x":"(1/r) d/dr (r dθ/dr) − m²θ = 0"},{"t":"p","x":"であり、解は θ(r) = A I₀(mr) + B K₀(mr)（I₀・K₀ は変形 Bessel 関数）。非定常は"},{"t":"p","x":"ρcp ∂T/∂t = (k/r) ∂/∂r (r ∂T/∂r) − (2h/t)(T − T∞)"},{"t":"p","x":"を解く（出典：`ANNULAR_FIN_DEVELOPMENT.md`）。"}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["T","温度（絶対温度で入力・出力）","K"],["r1, r2","管外半径（フィン基部）、フィン外半径","m"],["r2c = r2 + t/2","修正半径（`corrected` 方式でのみ解く半径）","m"],["t","フィン厚さ（一様）","m"],["k, ρ, cp","熱伝導率、密度、比熱（一定物性）","W/(m·K), kg/m³, J/(kg·K)"],["h","熱伝達率（入力値。流れから予測しない）","W/(m²·K)"],["Tb, T∞","基部温度、周囲流体温度","K"],["m = √(2h/(kt))","フィン定数","1/m"],["Bi = h(t/2)/k","厚さ方向のビオ数（1D仮定の開発範囲の検査に使う）","—"],["Acb = 2π r1 t","基部断面積","m²"],["A_fin","対流に触れる全表面積（`convection` では両側面＋先端面、`corrected` では r2c までの両側面）","m²"],["η = Q_surface/(h A_fin θb)","フィン効率（表面損失ベース）","—"],["ε = Q_surface/(h Acb θb)","フィン有効度（表面損失ベース）。θb = Tb − T∞","—"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"一様な初期絶対温度（スカラー）か、セルごとの初期温度配列を与える。配列の長さはセル数と一致しなければならず、不一致は拒否される。温度値は各セルの代表値であり、点温度ではない（項目9・13）。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"ul","items":[{"x":"基部（r = r1）：指定温度 Tb に固定。"},{"x":"両側面：同一の指定 h で周囲 T∞ へ対流。"},{"x":"先端（r = r2）：2方式を選択できる。","sub":{"t":"ul","items":[{"x":"`convection`：先端面（面積 2π r2 t）自体が同じ h で対流する厳密な先端条件 −k dθ/dr = hθ（r = r2）。"},{"x":"`corrected`：修正半径 r2c = r2 + t/2 まで領域を延長し、先端を断熱とする Schmidt/Gardner の古典的近似。解く形状自体が実フィンより半径で t/2 大きい近似であり、その旨は assumptions と mesh に明記される。"}]}}]}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"環状セルの有限体積法。セル中心は環状セルの面積重心 rc = (2/3)(a² + ab + b²)/(a + b)。面コンダクタンスは重心間の対数抵抗 2πkt / ln(rc′/rc)（円筒伝導の厳密抵抗）で、基部は ln(rc₀/r1) を使う。側面対流は両面分を各セルに課す。"},{"x":"時間積分は前進 Euler で、安定刻みは最大流出率の0.8倍の逆数（`safeDt`）を上限とし、超過する刻みは拒否する。"},{"x":"累積外部熱（基部流入 − 表面損失）には補償和を使い、受理前に有限値・正温度・監視上限・熱収支予算（128·EPS 基準）を検査する。失敗したステップ・復元は受理状態を変更しない（原子的拒否）。"},{"x":"入力検証：未知キー・非有限・範囲外は日本語エラーで拒否する。セル数は 4〜256。厚さ方向一様の1D仮定の開発範囲として Bi = h(t/2)/k ≤ 0.1 を生成時に検査し、超える条件は拒否する。監視温度上限は既定 10000 K。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"形状（r1・r2・t）・材料・h・Tb・T∞・初期温度・先端条件・セル数を指定して生成する。"},{"x":"`safeDt` 以下の刻みで時間を進め、スナップショットの温度配列・基部熱流量・表面損失・収支誤差で応答を確認する。"},{"x":"定常の検算は Bessel 参照値（項目10）と比べる。"}]},{"t":"p","x":"手計算による検算の例（出典：`ANNULAR_FIN_DEVELOPMENT.md` の基準条件）：r1 = 0.01 m、r2 = 0.03 m、t = 0.002 m、k = 200 W/(m·K)、ρ = 2700 kg/m³、cp = 900 J/(kg·K)、h = 150 W/(m²·K)、Tb = 400 K、T∞ = 初期 300 K（仮想値であり実在材料の保証値ではない）では、m = 27.386 m⁻¹、断面 Bi = 7.5e-4、定常 η = 0.840173（`convection`）／0.839925（`corrected`）。"}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"公開画面はないが、開発画面（公開ビルドには含まれない）にはグラフ表示がある。公開側で結果を読む場合はスナップショットの数値配列を使う。"},{"x":"`temperature` はセル重心半径 `radii` における代表値の配列であり、その半径の点温度ではない。`outerCellTemperature` は最終セルの代表値で、先端面 r2 の表面温度への外挿値ではない。"},{"x":"η・ε は各スナップショットで表面損失から計算する診断量で、過渡初期（初期温度一様・基部だけ Tb）は 0 から始まって定常値へ近づく。時系列で読む場合は「定常効率そのものではない」ことに注意する（項目13）。"},{"x":"`energyError` は収支の検査量であり、温度の離散化誤差とは別の量である。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"ul","items":[{"x":"検証の実測（出典：`ANNULAR_FIN_DEVELOPMENT.md`、参照は50桁 mpmath の Bessel 解と行列指数による独立伝播）：","sub":{"t":"ul","items":[{"x":"定常 Bessel 参照値：`convection` で η = 0.840173、ε = 36.1274、q_base = 68.0986 W。`corrected` で η = 0.839925、ε = 36.1588、q_base = 68.1577 W。"},{"x":"定常温度場と Bessel セル平均の RMS 差は、`convection` で n=16/32/64 のとき 0.02319 / 0.005907 / 0.001528 K（観測次数 1.97 / 1.95）、`corrected` で 0.02471 / 0.006190 / 0.001548 K（次数 2.00 / 2.00）。"},{"x":"基部熱流量の格子収束は `corrected` で次数ほぼ正確に 2.00。`convection` では誤差は単調減少するが細格子側の見かけ次数が乱れる（誤差の符号の消し合い）ため、次数2を主張しない。"},{"x":"過渡（t = 2 s、n=16、dt = safeDt/2）の行列指数参照との最大差は `convection` 0.01705 K、`corrected` 0.01611 K。時間精細化の観測次数は 1.000（前進 Euler の1次と一致）。"},{"x":"エネルギー収支は試験範囲で |energyError| ≤ 1e-8 J。定常到達時は基部流入と表面損失が 1e-6 W 未満で一致する。"},{"x":"極限チェック：長さ消滅（r2 = 0.011、L = 0.001 m）で η = 0.998903（Bessel 0.998905）と 1 へ近づく。大半径では直線フィンの tanh(mLc)/(mLc)（Lc = L + t/2）へ近づき、η の差は r1 = 0.5 m で 0.01159、r1 = 2.0 m で 0.00310 と縮小する。"}]}},{"x":"環状フィンの η が同長さの直線フィンより小さいのは、外側ほど面積が増え温度の低い領域の重みが増すためであり、符号も含めて物理と整合する。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"半径方向1D（厚さ方向は一様）。スナップショットの assumptions に明記：一定物性、指定の一様 h、基部温度固定、放射なし。"},{"x":"管壁の熱抵抗・基部の熱拡がりは解かない。内部発熱なし。"},{"x":"`corrected` 方式では修正半径近似を使う（assumptions の `correctedRadiusApproximation`）。"},{"x":"η・ε は表面損失ベースで、既存の学習モデルと同じ定義である。h = 0 または θb = 0 では η・ε は定義できないため null を返す（数値の創作をしない）。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"Worker 接続・公開可否は未実施。GUI とそのブラウザー確認（Chromium）は開発画面で実施済み。`releaseApproved:false`、公開 allowlist 外。"},{"x":"フィン付き管としての管内流体・管壁抵抗との連成、複数フィンとフィン間流れ、基部の熱拡がり／2D伝導、温度依存物性、放射、実在材料での実測照合、外部専門家の承認は未実施。"},{"x":"先端条件は対流と修正半径の2方式のみ。実先端温度は最終セルの代表値であり、先端面への外挿値は提供しない。"},{"x":"開発範囲は Bi ≤ 0.1、セル数 4〜256 で、範囲外は推定値を返さず拒否する。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「修正半径で解いた結果は実フィンの厳密解」** — 誤り。解く形状自体が半径で t/2 大きい近似であり、基準条件では対流先端の厳密解に対して η で 2.5e-4、q で 0.06 W の差がある。この条件では近似として妥当な水準だが、近似であることに変わりはない。"},{"x":"**「過渡中の η がそのまま定常のフィン効率」** — 誤り。過渡中は基部流入と表面損失が蓄熱の分だけ異なり、η は表面損失ベースの瞬時診断量として定義される。初期には 0 から始まる。"},{"x":"**「基部熱流量と表面損失は常に等しい」** — 誤り。定常でのみ一致し、過渡中は差が蓄熱になる。"},{"x":"**「最終セルの温度が先端面の温度」** — 誤り。セル代表値であり、面への外挿値は提供していない。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、§4.5「Fin design」（フィン効率・環状フィンを含むフィン設計の節）。"},{"x":"アプリの教材：フィン学習画面（`dynamic/fin-learning.html`、開発文書 `docs/dynamic/FIN_LEARNING.md`）が η・ε の基礎と断熱先端の直線フィンを扱う。本モデルは開発専用のため公開画面からの導線はない。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第4.2節・第8節）に基づく。"},{"t":"p","x":"**現行の問題バンク（751問）に、本モデル（環状フィン）に対応する問題はない。** バンク全体を「環状」「円形フィン」で棚卸ししても該当は 0 件であり、環状フィンの効率・有効度を扱う問題は存在しない。推測で埋めず、その事実をここに明記する。"},{"t":"p","x":"最も近いのは、直線フィンの効率・有効度の基礎を扱う次の問題である（いずれも主掲載は直線フィンの説明書の項目15。環状フィンの大半径極限が直線フィンに帰着することの基礎になる）。"},{"t":"ul","items":[{"x":"`supp-chapter-ch4-fin-eta` — 先端断熱の直線フィンの効率 η=tanh(mL)/(mL)。"},{"x":"`supp-deep-fin-effectiveness-v1` — 基部放熱量からフィン有効度 ε を求める。"}]}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（§4.5、Appendix A の物性値）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/ANNULAR_FIN_DEVELOPMENT.md`（数値コア・仮定・検証実測）、`docs/dynamic/ANNULAR_FIN_REFERENCE_20261107.json` と生成器 `scripts/dynamic-annular-fin-reference.py`（50桁 Bessel 参照と行列指数参照）、`docs/dynamic/FIN_LEARNING.md`（η・ε の定義の正）。"}]}]}]},{"id":"fin-heat-sink","name":"ヒートシンク（規定 h モデル）","source":"docs/dynamic/FIN_MANUAL_HEAT_SINK_20261107.md","screen":null,"lead":[{"label":"対象モデル","x":"開発専用モジュール `dynamic/dev/heat-sink.mjs` と専用 UI/Worker（`dynamic/dev/heat-sink.html`、`heat-sink-ui.mjs`、`heat-sink-view.mjs`、`heat-sink-worker.mjs`）。数値コアは本線（起点 `c52f2a7`）の成果物。画面の操作範囲拡張はフェイリス側ブランチ `feiris/heat-sink-ui-expand`（コミット `00d7a3a`、本線 `c52f2a7` へリベース済み）で、カーネル・表示は無変更である。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"一様温度の基部に発熱 P [W] を与え、N 本の同一の矩形フィンと、フィンのない露出上面から、指定 h で対流放熱する系を計算する。基部は有限の熱容量を持ち、温度が時間とともに変化する。各フィンは長さ方向だけを計算し、同一条件の対称性から代表1本を解いて、全容量・全交換・全放熱には本数を掛ける。基部とフィンの接触部には接触熱抵抗を置ける。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"CPU やパワー半導体のヒートシンクで、発熱に対して基部温度がどこまで上がり、どれくらいの時間で落ち着くかの学習・概算。"},{"x":"フィン本数・接触抵抗・発熱量を変えたときの基部温度応答の比較（画面の A/B 比較）。"},{"x":"接触抵抗や露出上面の寄与が全体の放熱にどう効くかの確認。"}]},{"t":"p","x":"いずれも一様基部温度・代表フィン・指定 h の仮定が成り立つ範囲の学習・概算のためであり、任意の実ヒートシンクの性能保証ではない（項目12、画面内「理論・仮定・適用限界」にも明記）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"基部幅 W、奥行 D、厚さ b、フィン長 L、厚さ t とし、根元断面 Ac = tD、周長 Pf = 2(t + D)、露出上面 Ab = D(W − Nt)、基部体積 WDb とする（出典：`HEAT_SINK_DEVELOPMENT.md`）。"},{"t":"ul","items":[{"x":"Cb = ρcp WDb、Cf = ρcp Ac dx、G0 = Ac/[Rc″ + dx/(2k)]、Gi = kAc/dx、Gs = hPf dx、Gb = hAb（Rc″ は接触熱抵抗 [m² K/W] で、1本につき Rc″/Ac [K/W]）。"},{"x":"基部：Cb dTb/dt = P − Gb(Tb − Ta) − N G0(Tb − T1)。"},{"x":"各フィンセル：Cf dTj/dt = 隣接セル／基部からの流入 − Gs(Tj − Ta)。先端の外向き伝導は 0。"},{"x":"全体：dE/dt = P − Gb(Tb − Ta) − N Gs Σ(Tj − Ta)。基部からフィンへの交換熱は内部量で、全収支へ二重に加えない。"}]}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["Tb, Ta","基部温度（モデル内は一様）、周囲流体温度","K"],["P","基部への発熱","W"],["W, D, b","基部の幅、奥行、厚さ","m"],["L, t","フィンの長さ、厚さ（フィン断面は厚さ×基部奥行 D）","m"],["N","フィン本数（0〜64）","—"],["Ac = tD, Pf = 2(t + D)","フィン根元断面、周長","m², m"],["Ab = D(W − Nt)","露出した基部上面の面積","m²"],["gap","フィン間隔（均等配置の派生量：W = N·t + (N + 1)·gap）","m"],["k, ρ, cp","熱伝導率、密度、比熱（一定物性）","W/(m·K), kg/m³, J/(kg·K)"],["h","熱伝達率（入力値。風速から計算しない）","W/(m²·K)"],["Rc″","接触熱抵抗（面積あたり）","m² K/W"],["Cb, Cf","基部とフィンセルの熱容量","J/K"],["G0, Gi, Gs, Gb","基部―フィン間、フィン内部、フィン側面、基部上面のコンダクタンス","W/K"],["Bi = h(Ac/Pf)/k","フィン断面のビオ数（断面一様の開発範囲の検査に使う）","—"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"基部とフィンの初期温度を与える。カーネルは基部（`initialBase`）とフィン（`initialFin`）を別々に指定でき、画面では基部・フィン共通の初期温度として設定する。周囲温度 Ta は別に指定する。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"ul","items":[{"x":"フィン側面と露出した基部上面：指定 h で周囲 Ta へ対流。"},{"x":"フィン先端と基部の他面：断熱。"},{"x":"基部とフィンの接合：接触熱抵抗 Rc″ と最初の半セル伝導抵抗を直列に置く。"},{"x":"発熱 P は基部へ一様に与える。基部の温度分布そのものは解かない（項目11）。"}]}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"有限体積の面コンダクタンスと前進 Euler。安定刻みは基部／フィンの最大流出率の0.8倍の逆数を上限とする。"},{"x":"受理前に有限値・正温度・監視上限・熱収支・時計を検査し、累積外部熱には補償和、蓄熱は初期状態との差から別計算する。復元は law／条件署名／配列／時計／収支を検査し、失敗時は受理状態を変更しない。"},{"x":"断面 Bi = h(Ac/Pf)/k ≤ 0.1 を開発範囲として検査する。ただし基部の一様温度は別の仮定であり、フィンの Bi 検査が基部の熱拡がり抵抗を保証するわけではない。"},{"x":"N = 0 は露出上面全体で対流する有限容量基部に退化し、フィン温度配列は空になる。h = 0 の対流寄与は厳密に 0。"},{"x":"画面からの入力範囲（UI 側の検証、日本語理由つき）：フィン長さ 1〜500 mm、厚さ 0.1〜50 mm、基部幅・奥行 5〜1000 mm、基部厚さ 0.5〜100 mm、本数 0〜64、セル数 8／16／32／64／128（カーネルの受理範囲は本数 0〜64、1本の格子 4〜256）。本数×厚さが基部幅を超える形状は寸法入りの理由を表示して受理しない。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"画面で条件（本数・h・発熱・接触抵抗・形状・材料・周囲／初期温度・セル数）を設定し、「初期状態から計算」で適用する。"},{"x":"再生／1コマ進める／戻すで時間を操作し、基部温度の履歴・立体図の温度・診断（各部の熱流と全熱収支）で応答を確認する。「現在の条件をBへ固定」で A/B 比較ができる。"},{"x":"検算は独立参照との照合値（項目10）と比べる。"}]},{"t":"p","x":"検証に使われた相似則（出典：`HEAT_SINK_DEVELOPMENT.md`）：寸法 λ・h/λ・Rc″λ・入力 Pλ・時刻 λ² の相似変換で解が対応する。材料の選択肢は既定の仮想一定物性（k=200、ρ=2700、cp=900。実在合金の保証値とは呼ばない）と、`dynamic/presets.mjs` の MATERIALS（純銅 k=398／アルミニウム 6061-T6 k=167／純鉄 k=80、いずれも教科書付録A・Table A.1 の20℃参考値を一定とする教育近似）である。"}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"立体図は、計算した1Dセル温度を N 本のフィン形状へ配置した表示であり、3Dの温度場を解いた結果ではない（画面内にも明記）。回転・傾き・拡大は表示だけを変え、計算条件や時計を変えない。"},{"x":"測定位置（プローブ）の読み値は、フィン内の所属セルの平均温度である。基部温度はモデル内一様値として表示される。"},{"x":"履歴グラフは実際に計算した基部温度の履歴で、A は実線、B は破線。保存した温度場へ戻すことができる（履歴はメモリーだけに保持し、再読み込みで消える）。"},{"x":"診断の「基部からフィンへの熱」は内部交換であり、全収支へ二重に加えられていない。発熱と放熱の差が基部と全フィンの蓄熱になる。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"ul","items":[{"x":"検証の実測（出典：`HEAT_SINK_DEVELOPMENT.md`。独立参照は N 本の物理枝を別々に持つ容量／コンダクタンス行列による定常 solve と拡大行列指数で、JS の対称縮約・Euler を流用していない）：","sub":{"t":"ul","items":[{"x":"定常の容量加重 RMS 差は 8/16/32/64 セルで 0.00715376 / 0.00178865 / 0.000447177 / 0.000111795 K（連続解への空間次数 約2）。"},{"x":"各固定格子の過渡を独立行列指数へ照合し、最細の最大差は 0.000277984 K。16セル固定の刻み精細化では RMS 0.00561928 / 0.00280850 / 0.00140397 K（時間次数 約1）。"},{"x":"外部放熱の独立積分／全容量、断熱時の加熱、相似則、N=0、接触の SI 単位、原子的失敗／復元、無効域を確認済み。"}]}},{"x":"画面拡張後の確認（出典：同文書 2026-11-07 追補）：形状・材料（純銅）・周囲／初期温度 300 K を変えた条件で、実 Worker の基部／所属セル温度が同条件のカーネル計算と 6e-8 K 以内で一致。間隔 10 mm の編集で基部幅が 58 mm へ連動し、診断の均等間隔と一致。全入力を既定へ戻すと従来検証済みの既定結果（t = 5 s）に一致する。"},{"x":"基部温度は「一様という仮定のもとでの値」であり、実物の基部内の温度分布（熱源近くの局所的な高温）は表れない（項目11・13）。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"スナップショットの assumptions に明記：基部一様温度、同一フィン、フィン断面一様温度、指定の一様 h、先端断熱、基部の他面断熱。一方で、流体相互作用・基部熱拡がり・放射・3D伝導は解かない（各フラグ false）。"},{"x":"一定物性・指定 h のみで、風速から h を計算しない。フィン間の空気流れ・相互遮蔽・h の本数依存は解かない。"},{"x":"フィンの奥行は基部奥行と同一で、フィン断面は厚さ×基部奥行である。間隔は均等配置として基部幅から決まる派生量である。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"実ヒートシンクの h／流れの相互作用、基部の熱拡がり／3D伝導、放射、異なるフィン間の相互作用は未対応。"},{"x":"開発専用で `releaseApproved:false`、公開 allowlist 外。オフライン・実機・支援技術・公開 URL での動作は未検証（画面内にも明記）。外部専門家の承認はない。"},{"x":"数値上の正有限と、連続体モデルの物理的適用は別である。基部の一様温度とフィン断面の一様温度の妥当性は、実物の寸法・熱源位置・物性・Bi 数などから別途判断が必要である。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「立体図が立体的に解いた 3D 解析結果」** — 誤り。同じ1D解の繰返し表示であり、先端／根元／基部の未計算の3D分布は創作していない。"},{"x":"**「基部が一様温度になるのは計算結果」** — 誤り。モデルの仮定そのものであり、フィンの Bi 検査が基部の熱拡がりを保証するわけでもない。"},{"x":"**「N 本のフィンを1本ずつ全部解いている」** — 誤り。対称性で代表1本を解き、本数を掛けて全体量にしている。全フィンが同じ温度分布という仮定を含む。"},{"x":"**「h は風速から予測された値」** — 誤り。入力値であり、風速→h 推定は別モジュール（`wind-heat-transfer.mjs`）の担当で、本画面には接続していない。"},{"x":"**「基部からフィンへの熱を全収支に加えると放熱が二重に数えられる」** — そのとおり二重計上になるため、診断表示でも内部交換として分けてある（項目9）。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、§4.5「Fin design」。材料の物性値は Appendix A・Table A.1 の20℃参考値（教育近似としての扱いは項目8）。"},{"x":"アプリの教材：フィン学習画面（`dynamic/fin-learning.html`、開発文書 `docs/dynamic/FIN_LEARNING.md`）が単一フィンの η・ε を扱う。本モデルは開発専用のため公開画面からの導線はない。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第4.3節・第8節）に基づく。"},{"t":"p","x":"**現行の問題バンク（751問）に、本モデル（ヒートシンク）に直接対応する問題はない。** バンク全体を「ヒートシンク」で棚卸ししても該当は 0 件であり、複数のフィンと基部・接触部を一体で扱う問題は存在しない。推測で埋めず、その事実をここに明記する。"},{"t":"p","x":"最も近いのは基部の接触抵抗を扱う `supp-existing-fin-contact-loss-v1`（主掲載は直線フィンの説明書の項目15）であり、放熱の基礎は直線フィンの問題一式（同・項目15）である。ヒートシンク固有の問題として断定できるものはない。"}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（§4.5、Appendix A の20℃物性値）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/HEAT_SINK_DEVELOPMENT.md`（数値コア・仮定・検証実測・画面拡張の追補）、`docs/dynamic/HEAT_SINK_MATH_REFERENCE_20261105.json`（参照／出典／hash）、`docs/dynamic/HEAT_SINK_CHECKPOINT_20261106.json`（ブラウザー確認記録）、生成器 `scripts/dynamic-heat-sink-reference.py`。"}]}]}]},{"id":"fin-wind-h","name":"風速から熱伝達率を求める","source":"docs/dynamic/FIN_MANUAL_WIND_H_20261107.md","screen":null,"lead":[{"label":"対象モデル","x":"開発専用モジュール `dynamic/dev/wind-heat-transfer.mjs`（`estimateWindHeatTransfer`、法則識別子 `wind-heat-transfer-correlation-v1`）。フェイリス側ブランチ `feiris/fin-wind-h`（起点 `0fa3965`、コミット `adaa7ff`）の成果物で、統合ツリーの `dynamic/dev/` に開発画面（GUI）があり、推定 h のヒートシンク画面への受け渡しも接続済み。相関式の評価器とその返却レコード、および開発画面が対象である。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"流速（風速）だけが分かっているときに、平板や円柱の表面の対流熱伝達率 h を、教科書 *A Heat Transfer Textbook*, 6th ed. に印刷された相関式だけから推定する。正本 §7 の要求「風速から熱伝達率を推定する場合は、流れの条件と相関式の適用範囲を確認する」「任意の風速変更に対し、根拠なく熱伝達率を比例変更しない」に対応し、適用範囲外では推定値を返さず理由つきで拒否する。推定した h は、フィン／ヒートシンクの各モデルが受け取る「規定の一様 h」として渡す量である。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"ファンで冷やすフィンやヒートシンクについて、風速しか分からない段階で h の概算を得て、各フィンモデルの入力にする。"},{"x":"平板状の基板や円柱（管・ピンフィン）が流れの中でどれくらい冷えるかの学習・概算。"},{"x":"相関式ごとに適用範囲が違うこと、範囲外では推定できないことの確認。"}]},{"t":"p","x":"いずれも相関式の適用範囲内での学習・概算のためであり、範囲外の外挿や実設計の保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"支配方程式に相当するのは、教科書の以下の相関式群である（すべて教科書の式番号つき。物性は膜温度評価）。"},{"t":"p","x":"平板（等温・板全体の平均 Nu_L）："},{"t":"table","head":["レジーム","式","適用範囲（拒否条件）"],"rows":[["層流 `laminar`","Nu_L = 0.664 Re_L^{1/2} Pr^{1/3}（式 **6.68**）","Pr ≧ 0.6、Pe_L > 100（境界層近似）、Re_L ≦ 5×10⁵（全体が層流）"],["液体金属 `liquid-metal`","Nu_L = 1.13 Pe_L^{1/2}（式 **6.69**）","Pe_L > 100。液体のみ"],["観測遷移 `mixed-observed`（気体）","式 **6.120**（乱流部＋層流部＋遷移部の3領域平均）、勾配 c は式 **6.115**","気体のみ。遷移開始 Re_l ≦ 5×10⁵、Re_l < Re_u ≦ Re_L、Pr ≧ 0.6"],["急峻遷移 `mixed-abrupt`（気体）","式(6.120)の例題 **6.11** による縮約","0 ≦ Re_trans < Re_L、Pr ≧ 0.6。遷移域省略の近似である旨を警告に明示"],["急峻遷移 `mixed-abrupt`（液体）","乱流部を局所式 **6.113** から展開した形","同上。式(6.120)そのものではない導出形であり、識別子 `6.120-abrupt-liquid` と本書で区別する"]]},{"t":"p","x":"円柱横流れ（円周平均 Nu_D、Churchill–Bernstein 系の構成式選択）："},{"t":"table","head":["条件","式"],"rows":[["Pe_D ≦ 0.2","Nu_D = 1/(0.8237 − ln Pe_D^{1/2})（式 **7.67**、Nakai–Okazaki）"],["Re_D < 4000","式 **7.66**"],["40,000 < Re_D < 400,000","式 **7.68**（原典に4/5乗はなく、印刷どおりに実装）"],["その他","Churchill–Bernstein 全体式 **7.65**（既存の静的モデル `cylinder-crossflow.mjs` の実装を共有し、値の drift を構造的に防ぐ）"]]},{"t":"p","x":"h は h = Nu·k/L（円柱では L = D）で得る。フィン付き面は `fin-plate` を平板、`fin-pin` を円柱の代表形状として扱う。"}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["u∞","主流速度（風速）","m/s"],["L, D","代表長さ（平板の長さ、円柱の直径）","m"],["ρ, μ, cp, k","密度、粘度、比熱、熱伝導率（膜温度で評価した利用者供給値）","kg/m³, Pa·s, J/(kg·K), W/(m·K)"],["ν = μ/ρ, α = k/(ρcp)","動粘度、熱拡散率","m²/s"],["Ts, T∞","表面温度、主流温度","K"],["Tf = (Ts + T∞)/2","膜温度（物性評価温度）","K"],["Re, Pr, Pe = Re·Pr","Reynolds 数、Prandtl 数、Péclet 数","—"],["Nu","Nusselt 数（平板は平均 Nu_L、円柱は円周平均 Nu_D）","—"],["h","熱伝達率（推定の出力）","W/(m²·K)"],["c","観測遷移の勾配（式 6.115）","—"],["Re_trans, Re_l, Re_u","遷移 Reynolds 数、遷移開始／終了 Reynolds 数","—"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"本モデルは時間発展を解かないため、初期条件は存在しない。代わりに必要な入力は、形状（`flat-plate`／`cylinder`／`fin-plate`／`fin-pin`）、主流速度、代表長さ、膜温度で評価した物性（ρ・μ・cp・k）、表面温度と主流温度（膜温度の報告用）、平板ではレジームと遷移条件である。物性は既存の静的モデルと同じく利用者供給であり、流体データベースや温度補間による推定はしない。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"p","x":"境界条件に相当するのは相関式の前提である：平板は等温面、円柱は円周平均の扱い、物性は膜温度 Tf = (Ts + T∞)/2 で評価すること（教科書の指定、§6.5・§7.6）。フィン付き面は代表形状（平板／円柱）として扱い、フィン間干渉・バイパス流れ・フィン効率は含まないことが結果に警告として明示される。"}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"閉形式の評価であり、格子・時間積分はない。入力から Re・Pr・Pe を計算し、項目3の範囲選択で相関式を1つ選び、Nu と h を返す。"},{"x":"式(7.65) は既存の静的モデル `cylinder-crossflow.mjs` の `churchillBernsteinNu` をそのまま呼び出し、実装間の値の drift を構造的に防ぐ。式(7.65) が選ばれる範囲では既存モデルと値は完全一致する。"},{"x":"拒否条件（推定値を返さない）：Pr < 0.6 の層流、Pe ≦ 100 の平板、レジーム未指定での Re_L > 5×10⁵（外挿禁止）、遷移条件の欠落・逆転・Re_l > 5×10⁵、Re_D > 10⁷（教科書 Fig. 7.11 のデータ範囲と既存静的モデルの教育用制限に合わせた保守的上限）、円柱へのレジーム指定、未知キー、非有限・非正入力。"},{"x":"境界の扱い（テストで確認済み）：Pe_D = 0.2 ちょうどは式(7.67)、Re_D = 4000／400,000 ちょうどは式(7.65)。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"形状・速度・代表長さ・物性・温度を入力する（物性は膜温度で評価して用意する）。"},{"x":"モジュールが Re・Pr・Pe を計算し、レジーム／構成式を選んで Nu を評価する。範囲外なら理由を表示して推定しない。"},{"x":"h = Nu·k/L を返し、警告（遷移が始まり得る領域、圧縮性の確認、代表形状の扱いなど）を確認する。フィン／ヒートシンクへは `heatSinkHFromWind` アダプタで h を渡せる。"}]},{"t":"p","x":"手計算による検算の例（出典：`WIND_HEAT_TRANSFER_DEVELOPMENT.md` の例題6.5）：層流平板で Re_L = 384,615.38（教科書印刷値 384,600）、Nu_L = 366.156（印刷値 366.2）、h = 21.3835 W/(m²·K)（印刷値 21.4）、膜温度 65 ℃も一致する。"}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"公開画面はないが、開発画面（公開ビルドには含まれない）がある。結果は返却レコードで読む：`nusselt`、`h`、採用された相関の識別子 `correlation`、観測遷移の勾配 `transitionSlope`、`reynolds`／`prandtl`／`peclet`、`filmTemperatureK`、`warnings`。"},{"x":"`correlation` は「どの式で推定したか」を示す最重要の項目で、値だけを見て式を確認しないと、境界付近での式の切替わり（項目13）に気づけない。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"ul","items":[{"x":"検証の実測（出典：`WIND_HEAT_TRANSFER_DEVELOPMENT.md`。参照は mpmath 50桁の生成器で、モジュール値は50桁参照と相対差 10⁻¹² 以内で一致し、教科書の印刷値とは印刷丸めの範囲で一致する）：","sub":{"t":"ul","items":[{"x":"例題6.9（観測遷移）：c = 2.54536（印刷値 2.55。印刷値は c を丸めて使用）、Nu_L = 1434.03（印刷値 1433）、h = 18.9292（印刷値 18.92）。差は c の丸め由来と特定されている。"},{"x":"例題6.11（急峻遷移）：Re_trans = 4×10⁵ で Nu = 1759.87（印刷値 1760）、8.7×10⁵ で 1151.71（印刷値 1152）。"},{"x":"例題7.8（円柱、式(7.66) を順方向評価）：Nu_D = 10.6943（印刷値 10.69）、h = 2833.98（印刷値 2833）。"},{"x":"式(7.67) は Pe = 0.1 で Nu_D = 0.506331（印刷値なし、50桁参照と照合）。"},{"x":"式(7.68) と式(7.65) は Re = 10⁵ で 243.952 対 214.126 となり、教科書の「(7.65) は約20%過小評価」という記述と整合する。"}]}},{"x":"速度に対する非比例性：層流平板では流速4倍で h は2倍（√比例）であり、線形比例ではない。レジームが変われば比例関係自体が変わる。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"返却レコードの assumptions に明記：物性は膜温度評価、一定物性、等温面、滑らかな面、非圧縮流。一方で放射・浮力（混合対流）・フィン干渉は含まず、流体そのものは解いていない。"},{"x":"平板は等温・板全体の平均の相関であり、局所 h の相関ではない。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"公開可否は未実施。GUI とそのブラウザー確認（Chromium）は開発画面で実施済み。`releaseApproved:false`、公開 allowlist 外。"},{"x":"対象外として明示的に扱わないもの：平板の局所 h、一様熱流束平板、非加熱始端、粗さ壁、圧力勾配、管群、球・その他の形状、自然対流との混合対流、放射、物性の温度依存の自動評価。100 m/s 超では圧縮性の確認が必要という警告のみで、圧縮性そのものは解かない。"},{"x":"式(7.66) と式(7.65) の間には Re_D = 4000 の境界で構成式由来の段差（約5.5%、Pr に依らず実モジュールで実測）がある。教科書の構成そのまま であり、境界付近の値はどちらの式でも相関のばらつき内とみなすべきである。"},{"x":"液体の急峻遷移形は式(6.113) からの導出であり、教科書に印刷された完成形ではない（識別子と本書で区別済み）。Pe_D ≦ 0.2 の領域は既存静的モデルが拒否していた範囲を式(7.67) で拡張したもので、この拡張域に既存モデルの対応値は存在しない。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「風速を2倍にすれば h も2倍」** — 誤り。層流では √ 比例（流速4倍で h 2倍）、乱流側では 0.8 乗に近い比例で、レジームをまたげば関係自体が変わる。根拠のない比例変更はしない設計である。"},{"x":"**「式(7.68) と式(7.65) の値が違うのはどちらかのバグ」** — 誤り。教科書自身の構成式選択であり、該当帯域では (7.65) がデータを約20%過小評価すると教科書が述べている。"},{"x":"**「物性は主流温度や表面温度で評価すればよい」** — 誤り。教科書の指定は膜温度 Tf = (Ts + T∞)/2 である。"},{"x":"**「フィン面で推定した h にはフィン効率まで含まれている」** — 誤り。推定されるのは表面の対流熱伝達率そのもので、フィン効率・フィン間干渉・バイパス流れは含まない。フィン側の計算は各フィンモデルの担当である。"},{"x":"**「範囲外でも式をそのまま外挿すれば概算になる」** — 誤り。本モジュールは範囲外では推定値を返さず拒否する。相関式の範囲外の値は根拠を持たない。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、§6.5「Heat transfer coefficient for laminar, incompressible flow over a flat surface」、§6.9「Turbulent transition and overall heat transfer」、§7.6「Heat transfer during cross flow over cylinders」。他の形状の相関の探し方・評価法は §7.7。"},{"x":"アプリの教材：既存の静的モデル（平板の強制対流、円柱横流れ）が同じ相関群の学習用モデルであり、式(7.65) は実装を共有する。本モジュールは開発専用のため公開画面からの導線はない。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第4.4節）に基づく。記載した ID はすべて問題バンク `data/questions.json` の実在 ID であり、アプリの演習（`../index.html#quiz`）でそのまま検索できる。主掲載は次の 9 件（全件）で、「相関式を使って流れ条件から h を得る」問題に絞られている。"},{"t":"ul","items":[{"x":"`supp-geometry-correlation-crossflow-reynolds-v1` — 単独円柱への横流れの Re_D。"},{"x":"`supp-geometry-correlation-crossflow-area-v1` — 長い等温円柱の側面の伝熱面積。"},{"x":"`supp-geometry-correlation-crossflow-heat-v1` — 平均 Nu_D から円柱の伝熱量を求める。"},{"x":"`supp-geometry-correlation-crossflow-property-state-v1` — 相関が指定する膜温度での物性評価。"},{"x":"`supp-geometry-correlation-crossflow-local-average-v1` — 単独円柱の周平均熱伝達率の意味。"},{"x":"`supp-geometry-correlation-observed-h-v1` — 観測された対流熱と温度差から h を求める。"},{"x":"`supp-geometry-correlation-power-law-sensitivity-v1` — Nu∝Re^0.8 のときの主流速度の変化に対する h の感度。"},{"x":"`supp-geometry-correlation-single-point-selection-v1` — 一つの観測値に対する相関式の選定。"},{"x":"`supp-geometry-correlation-correlation-complete-conditions-v1` — 相関式の適用を確認する際に必要な情報の組合せ。"}]},{"t":"p","x":"相互参照：相関そのものの計算（平板の平均 Nu など）は平板境界層の説明書の項目15に主掲載されている（`supp-chapter-ch6-nuavg`、`supp-laminar-plate-average-h-v1`、`supp-section-6-9`）。"}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（§6.5、§6.9、§7.6、例題 6.5／6.9／6.11／7.8、Appendix A の物性値）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/WIND_HEAT_TRANSFER_DEVELOPMENT.md`（相関・式番号・適用範囲・拒否条件・照合値）、`docs/dynamic/WIND_HEAT_TRANSFER_REFERENCE_20261107.json` と生成器 `scripts/dynamic-wind-heat-transfer-reference.py`（mpmath 50桁参照）、既存の静的モデル `cylinder-crossflow.mjs`・`forced-convection-flat-plate.mjs`。"}]}]}]},{"id":"forced-flat-plate","name":"平板境界層（強制対流）","source":"docs/dynamic/FORCED_CONVECTION_MANUAL_FLAT_PLATE_20261107.md","screen":null,"lead":[{"label":"対象モデル","x":"開発専用モジュール2段構成——速度段階 `dynamic/dev/blasius-boundary-flow.mjs`（定常 Blasius 相似解から保存的な面流量を構成）と温度段階 `dynamic/dev/flat-plate-thermal.mjs`（その速度場の中の受動非定常温度）、専用画面 `dynamic/dev/flat-plate.html`（UI/view/Worker 分離）。本線 `codex/dynamic-heat-simulation` の成果物。`releaseApproved:false`、公開 allowlist 外。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"一様な流れ U の中に置かれた平板の上では、粘性のために壁近くの流れが遅くなり、境界層が下流へ向かって厚くなる（Blasius の層流境界層）。平板が流れと違う温度に保たれると、温度の境界層も発達する。このモデルは2段構成で、まず定常な Blasius 相似解から質量を保存する面流量を作り（速度段階）、その中で温度だけを非定常に解く（温度段階、受動温度）。圧力や運動量そのものは解かない。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"平板状の電子基板や太陽熱集熱板が風で冷える（または温まる）ときの、平均熱伝達率の見積もりの学習。"},{"x":"「先端で局所熱流束が特異的に大きく、全板平均 Nu の収束が遅い」ことの実感。"},{"x":"Pr 数が変わると温度境界層の厚さと壁勾配 g′(0) がどう変わるか（Pr = 0.71 と 1 の比較）。"}]},{"t":"p","x":"いずれも境界層近似の中の学習モデルであり、実在の物体まわりの流れの保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"零圧力勾配・一様外流・2D・定常層流境界層近似。"},{"t":"ul","items":[{"x":"Blasius 方程式：f‴ + f f″/2 = 0、η = y√(U/(νx))、ψ = √(νUx) f(η)。板で f = f′ = 0、遠方で f′ = 1。壁曲率 f″(0) = 0.3320573362… が壁せん断と熱伝達の基準になる。"},{"x":"温度の相似解：g″ + (Pr/2) f g′ = 0（等温板）。g′(0) が局所熱伝達を決め、平均 Nusselt 数は Nu_L = 2 g′(0) √Re_L（Re_L = 10⁴ の参照では Pr = 0.71 で g′(0) = 0.2941649050 → Nu_L = 58.83298100、Pr = 1 で g′(0) = f″(0) → Nu_L = 66.41146724。出典は項目10）。"},{"x":"温度段階の輸送方程式：∂T/∂t + u ∂T/∂x + v ∂T/∂y = α ∂²T/∂y²、α = k/(ρcp)。入口 T∞、板 Tw、上端遠方 T∞、右端と上端は移流流出。"},{"x":"軸方向（x 方向）熱伝導・浮力・粘性加熱・圧力仕事・物性変化は省略する。温度は速度へフィードバックしない。"}]}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["U","一様外流速度","m/s"],["L","板長","m"],["D（スパン）","奥行き（熱量換算幅。有限側壁ではない）","m"],["x, y","流れ方向、壁垂直方向の座標","m"],["η = y√(U/(νx))","Blasius 相似変数","—"],["f, f′, f″","相似流れ関数とその微分","—"],["g, g′(0)","温度相似関数と壁勾配","—"],["u, v","速度成分（ψ の差から作る面流量の平均）","m/s"],["ρ, ν, cp, k","密度、動粘度、比熱、熱伝導率（一定物性）","kg/m³, m²/s, J/(kg·K), W/(m·K)"],["α = k/(ρcp)","熱拡散率","m²/s"],["T∞, Tw","主流温度、板温","K"],["θ = T − T∞","主状態として保持する温度差","K"],["Re_L, Pr","Reynolds 数、Prandtl 数","—"],["Nu_x, Nu_L","局所／全板平均 Nusselt 数","—"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"温度段階は θ = 0（全域が主流温度）または指定した初期場から開始する。初期の半セル由来の Nu は格子依存値であり、先端の物理的な初期ピークではない（項目13）。速度場は定常で、時間の初期条件を持たない。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"ul","items":[{"x":"板（y = 0）：T = Tw（等温）。板の面速度 v = 0、滑りなしは相似解に含まれる。"},{"x":"入口（x = 0）：T = T∞。ただし先端 x = 0 は相似解の特異点であり、角の速度とせん断の点値は有限最大値に置き換えない。"},{"x":"上端：有限の計算高さ（外端 η = 10〜24）に T∞ を置き、上端からの移流流出も保持する（勝手にゼロにしない）。遠方 η → ∞ の近似との違いは項目12の限界である。"},{"x":"右端：移流流出。"}]}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"速度段階：製品は独自の RK4 射撃／二分法で相似 ODE を η ≦ 12・8192区間で解き、f／f′ に Hermite 補間、外側は傾き1へ接続する。面流量は格子頂点の ψ 差 × 奥行き D で構成し、内部流量の発散と入口・流出の一致を検査する。板のせん断は各 x 区間の解析平均として保持し、平均摩擦係数 4f″(0)/√Re_L を照合する。"},{"x":"温度段階：一様矩形有限体積、風上移流／中央 y 伝導、正性を保つ SSPRK2。主状態は θ で保持し、板入力・上端伝導入力・右端移流出力・上端移流出力・正味入力の5成分を Kahan 積算で別々に保持する。安全刻みは流出熱容量流量と伝導 G の和から算出する。"},{"x":"受理範囲（実コードと開発文書で確認）：速度段階は Re_L = 10⁴〜10⁵、H/L ≦ 0.2、外端 η = 10〜24。温度段階は Pr = 0.6〜2、温度差は T∞ の10%以内。未知の温度条件・範囲外は拒否し、失敗時は旧温度・時計・熱履歴を保持する。`releaseApproved:false`。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"形状（L、スパン D）、物性、U、T∞、Tw、格子（nx × ny）と表示区間を設定する（画面の空気参考条件：L = 100 mm、換算幅 10 mm、入口 300 K、U = 1.575〜15.75 m/s、板温差 ±30 K、格子 32×16〜512×256）。"},{"x":"速度段階が Blasius 解から面流量を作り、温度段階の Worker が SSPRK2 で θ を時間発展させる。"},{"x":"板区間の平均 q″、瞬間の板平均 Nu_L、4成分の熱と蓄熱が表示される。A/B は色・速度矢印・板熱矢印の基準と物理 y 縮尺を共通化して比べる。"}]},{"t":"p","x":"検算の例：相似参照では Re_L = 10⁴・Pr = 1 で Nu_L = 66.41146724（項目10）。画面の粗い格子の平均 Nu がこの値と数%ずれるのは欠陥ではなく、先端特異性の解像不足として記録されている（項目10・13）。"}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"画面は温度場、再構成した速さ、板の区間平均 q″ の矢印、瞬間の板平均 Nu、4成分の熱・蓄熱・流量・刻みを表示する。縦の拡大表示は実倍率を明記し、実寸比にも戻せる。U の異なる条件の計算高さを同じ高さに引き伸ばすことはしない。"},{"x":"測定は所属セルの平均と実セル中心を表示し、クリック／矢印キーで移動する。"},{"x":"温度差 0 では Nu は未定義として表示される。初期の有限な Nu は離散格子の値で、先端・瞬間の物理的最大値として読んではいけない。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"p","x":"検証の実測（出典：`FLAT_PLATE_BOUNDARY_FLOW.md`、`FLAT_PLATE_THERMAL.md`、`FLAT_PLATE_UI.md`。予算は実行前に事前登録された）："},{"t":"ul","items":[{"x":"速度段階：独立参照（SciPy solve_bvp、η = 16／24）で f″(0) = 0.3320573362151983、製品との差 7.49e-14 未満。別 DOP853＋Brent 射撃との補助比較も 2.11e-11 未満。全 face 流量差は流量尺度で最大 1.86e-14 未満、発散と全体流量の予算も成功。"},{"x":"温度段階の時間精度：独立参照（別 SciPy Blasius BVP の連続速度求積＋物理座標 FV 疎行列のアフィン行列指数）に対し、16×16・Pr = 0.71・t = 0.5 で最大温度差が刻み細分化により 0.00957256 → 0.00013928 K、最終次数 2.00099。全積算熱成分も同じ2次で近づく。"},{"x":"定常の空間精度と**未達の保持**：独立な温度相似 ODE からの実セル平均に対し、元の一様格子系列（32×16 → 256×128）では全板平均 Nu の差が Pr = 0.71 で +2.0467%、Pr = 1 で +2.5112% と、予算 <2% を**未達のまま保持**している。追加格子では Pr = 0.71 の 512×128 で 1.69515%（成功）、Pr = 1 は 512×128 で 2.06369%（未達）、y も増やした 512×256 で 1.44515%（成功）。局所熱流は先端を除けば良好（L2 で 0.24% 級）で、全指標の単調改善は主張されていない。"},{"x":"フェイリス側の独立検証（検証ノート §24、リポジトリ外）：Blasius 方程式と温度相似 ODE を独立に解き（solve_bvp、η 上限30）、f″(0) = 0.3320573362、g′(0) は Pr = 0.71 で 0.2941649050 → 平均 Nu_L = 58.83298100、Pr = 1 で 66.41146724 と、Codex の事前登録参照値と**全桁一致**した。したがって上記の未達は参照側の問題ではない。また別の離散化（相似速度場を与えるマーチング法）では全板 Nu が参照へ下から単調収束し（Pr = 1、256×128 で −6.00%）、2つの独立した離散化が参照を両側から挟む。Codex 側の正の偏りは、先端セルの半セル固定温度処理による局所熱流の過大評価と整合的と切り分けられている。"},{"x":"画面の既定（64×32・0.01 s）は独立物理アフィン指数に対し safeDt/4 で最大差 0.000462666 K。最細刻みの値を GUI 既定結果へ転用することはしない、と画面文書は明記している。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"境界層近似そのものが仮定である：零圧力勾配、層流、定物性、平板は無限に薄く側壁なし。速度段階の assumptions に明記：定常境界層近似、零圧力勾配、層流、一様外流、一定物性、有限の外端、先端の速度極限は特異、非定常運動量は解かない、全 Navier–Stokes は解かない。"},{"x":"温度は受動的で、速度へフィードバックしない。温度段階の assumptions に明記：規定の定常 Blasius 場、軸方向伝導・浮力・粘性加熱の省略、上端の移流を含む、有限の外端温度境界、一般 CFD の精度は検証していない。"},{"x":"小温度差という条件だけで浮力の無視が保証されるわけではない（開発文書の注意）。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"開発専用・未公開。実機・支援技術・専用オフライン・外部専門家の確認は未実施。画面のブラウザー確認は Chromium で実施済み（実 Worker・復元・A/B・モバイル明暗・DPR2。WebKit は検証環境で起動できず未実施）。"},{"x":"扱わないもの：圧力勾配のある流れ、遷移・乱流、粗さ、圧縮性、浮力・共役伝熱、物性変化、一般形状・3D、非定常運動量。"},{"x":"全板平均 Nu の <2% 予算は元の一様格子系列では未達のまま保持されている（項目10）。全入力範囲の科学的誤差保証はない。"},{"x":"本分野（強制対流）全体の残作業として、円柱まわりの過渡モデルとフィン間の流れのモデルは開発専用として存在するが公開画面はない。圧力・速度連成 CFD の強制対流形状への接続、流体入口発達（速度助走区間）、温度依存物性も未実施である（締め可能性監査の残作業 #1〜#5）。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「平均 Nu が参照と2%ずれるのは参照値が間違っている」** — 誤り。参照値は2つの独立解法（本線の SciPy BVP と検証ノート §24 の独立 BVP）で全桁一致しており、ずれは製品側の先端解像の問題と切り分けられている。未達は予算を緩めず保持されている。"},{"x":"**「先端の熱流束が有限値で表示されるはず」** — 先端 x = 0 の局所熱流は相似解で特異であり、有限最大値に置き換えることはしない。区間平均として積分した量が正しい読み方である。"},{"x":"**「Blasius 解を使っているから Navier–Stokes を解いている」** — 誤り。解いているのは境界層近似の相似 ODE と、その中での受動温度輸送であり、運動量の時間発展も圧力も解かない。"},{"x":"**「温度差が小さければ浮力は無視できる」** — 小温度差は必要条件側の目安にすぎず、それだけで浮力無視は保証されない。本モデルは浮力を解かない前提を明記して運用する。"},{"x":"**「格子を x 方向だけ細かくすれば平均 Nu はすぐに収束する」** — 先端特異性に支配されるため x のみの精細化では誤差はゆっくりしか減らない（独立検証での観測次数は約 0.3）。壁際 y 精細化や先端 x 集積が次の手段と記録されている。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、第6章（外部強制対流）：Blasius 解と摩擦係数（§6.2〜§6.3）、層流の熱伝達係数（§6.5、平均の式(6.68) Nu_L = 0.664 Re_L^{1/2} Pr^{1/3} は Pr ≧ 0.6 の近似形で、相似解の g′(0) がその一般形）、乱流・遷移は §6.9。"},{"x":"アプリの教材：既存の静的モデル `forced-convection-flat-plate.mjs`（同じ相関群の学習用モデル）。本モデルは開発専用のため公開画面からの導線はない。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第5.4節）に基づく。記載した ID はすべて問題バンク `data/questions.json` の実在 ID であり、アプリの演習（`../index.html#quiz`）でそのまま検索できる。主掲載は 41 件（層流・Blasius・局所と平均 28 件、乱流・遷移・類推 13 件）あり、基礎から応用の順に代表 12 件を示す。全件は対応表の第5.4節に記載されており、問題バンクの第6章補助（guideId `chapter6-flat-boundary`）からも辿れる。"},{"t":"ul","items":[{"x":"`supp-found-re-flat-v1` — 主流速度と長さから Re_L を求める。"},{"x":"`supp-found-pr-fluid-v1` — 動粘度と熱拡散率から Pr を求める。"},{"x":"`supp-chapter-ch6-nuavg` — 平均 Nu_L≈0.664 Re_L^(1/2) Pr^(1/3) の計算。"},{"x":"`supp-chapter-ch6-local` — 末端の局所熱伝達率と全長平均熱伝達率の関係。"},{"x":"`supp-laminar-plate-average-h-v1` — 平均 Nu_L から平均 h を求める。"},{"x":"`supp-laminar-blasius-boundary-v1` — Blasius 解が成り立つ条件。"},{"x":"`supp-laminar-thickness-definition-v1` — 速度境界層厚さ δ_99 の意味。"},{"x":"`supp-laminar-plate-unheated-start-v1` — 前半が非加熱の平板で相関式を使う際の注意。"},{"x":"`supp-section-6-6` — St を Nu・Re・Pr から求める式（第6.6節の学習ノート）。"},{"x":"`supp-turbulence-colburn-predict-h-v1` — Reynolds–Colburn 類推を仮定して h を予測する。"},{"x":"`supp-turbulence-transition-location-v1` — 遷移 Re_c から遷移位置 x_c を求める。"},{"x":"`supp-turbulent-local-powerlaw-v1` — 乱流境界層における局所 Nu。"}]}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（第6章、§6.5、式(6.68)）。"},{"x":"Blasius, H. (1908) — 相似解の原典（教科書第6章の参考文献経由）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/FLAT_PLATE_BOUNDARY_FLOW.md`、`docs/dynamic/BLASIUS_FLOW_REFERENCE_20261106_v1.json`、`docs/dynamic/FLAT_PLATE_THERMAL.md`、`docs/dynamic/FLAT_PLATE_THERMAL_WIP_20261106.md`（未達を含む事前登録と結果）、`docs/dynamic/FLAT_PLATE_THERMAL_SPATIAL_SUMMARY_20261107.json`、`docs/dynamic/FLAT_PLATE_TIME_REFERENCE_20261106_v1.json`、`docs/dynamic/FLAT_PLATE_UI.md`、`docs/dynamic/FLAT_PLATE_UI_CHECKPOINT_20261107.json`。"},{"x":"リポジトリ外の検証記録：フェイリス側検証ノート §24（Blasius 受動温度場の独立検証、参照値の全桁一致と両側収束の切り分け）—— `~/workspace/dev/heat-sim-benchmarks/verification-notes-20261106.md`。"}]}]}]},{"id":"forced-graetz-channel","name":"Graetz チャネル流れ","source":"docs/dynamic/FORCED_CONVECTION_MANUAL_GRAETZ_CHANNEL_20261107.md","screen":null,"lead":[{"label":"対象モデル","x":"開発専用モジュール `dynamic/dev/graetz-channel.mjs` と専用画面 `dynamic/dev/graetz.html`。フェイリス側ブランチ `feiris/graetz-channel`（起点＝本線 `d81d658`、スライス1＋第3境界条件まで。リモートの `feiris/graetz-channel-2` はスライス1のみ）の成果物で、その後、統合ツリーへ開発専用モジュールとして統合済み（統合ウェーブ1）。`releaseApproved:false`、公開 allowlist 外で、公開ビルドには含まれない。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"2枚の平行な板の間に、すでに放物線状に発達した層流（Poiseuille 流）が流れている。入口では流体は一様な温度だが、壁が加熱または一定温度に保たれているため、流れ方向に進むにつれて温度分布が発達していく（熱的入口発達、Graetz 型の問題）。このモデルは**定常**の温度場を、時間発展ではなく流れ方向へのマーチングで直接解く。壁条件は3種から選べる：(a) 両壁一定壁温、(b) 両壁一定熱流束、(c) 片壁（下壁）一定熱流束・他壁（上壁）断熱。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"プレート式熱交換器や薄い流路（コールドプレート、マイクロチャネル）の入口付近で、熱伝達率が下流ほど下がって発達値に近づく様子の学習。"},{"x":"「壁温一定」と「熱流束一定」と「片側だけ加熱」では発達した Nusselt 数がどう違うか（7.541／8.235／5.385）の確認。"},{"x":"入口直後で局所熱伝達率が非常に大きくなる（Lévêque 漸近）理由の理解。"}]},{"t":"p","x":"いずれも指定された発達速度場の中の受動温度の学習モデルであり、実際の流路設計の保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"全高さ H、長さ L の平行平板間。速度は発達した Poiseuille 流を**与え**（解かない）、温度だけを定常エネルギー方程式で解く。"},{"t":"ul","items":[{"x":"速度分布（原書式 **7.62**）：u/u_av = (3/2)[1 − 4(y/b)²]（b＝板間隔＝H）。モジュール内では u = 6U z(1−z)、z = y/H と置く。"},{"x":"エネルギー方程式（軸方向熱伝導を省略）：u(y) ∂T/∂x = α ∂²T/∂y²、α = k/(ρcp)。"},{"x":"入口条件：x = 0 で T = T_in（一様）。"},{"x":"壁条件（3種）：(a) 両壁 T = Tw、(b) 両壁 q″＝一定（流体へ正）、(c) 下壁 q″＝一定・上壁断熱（∂T/∂y = 0）。"},{"x":"水力直径 Dh = 2H。バルク温度の定義は原書 §7.2 式(7.3)〜(7.5)。軸方向の発達の進み具合は、Graetz 数（式(7.26)）に関連する無次元軸距離 x* = x/(Dh·Re_Dh·Pr) で整理する。"},{"x":"既知の駆動圧力勾配 dp/dx = −12ρνU/H²、壁せん断の大きさ 6ρνU/H は診断として示すが、圧力場を解いた表示はしない。"}]}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["H, L","板間隔（全高さ）、流路長さ","m"],["depth","奥行き（熱量換算のスパン。有限側壁ではない）","m"],["U","平均流速（バルク速度）","m/s"],["u(y)","発達速度分布（放物線）","m/s"],["ρ, ν, cp, k","密度、動粘度、比熱、熱伝導率（一定物性、利用者供給）","kg/m³, m²/s, J/(kg·K), W/(m·K)"],["α = k/(ρcp)","熱拡散率","m²/s"],["T_in, Tw","入口温度、壁温（条件(a)）","K"],["q″","壁熱流束（条件(b)(c)、流体へ正）","W/m²"],["Tb(x)","バルク（混合平均）温度","K"],["Dh = 2H","水力直径","m"],["Re_Dh, Pr, Pe_Dh = Re·Pr","Reynolds 数、Prandtl 数、Péclet 数","—"],["x* = x/(Dh·Re_Dh·Pr)","無次元軸距離（熱的発達のものさし）","—"],["Nu_Dh, Nu_x","平均／局所 Nusselt 数（Dh 基準）","—"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"定常モデルなので時間の初期条件はない。代わりの「入口条件」が一様温度 T_in であり、流れは入口から発達済み（速度の入口発達は扱わない）と置く。過渡応答は解かない。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"p","x":"項目3の3種がすべてである。対称性：条件(a)(b) は上下対称、条件(c) は非対称（加熱壁と断熱壁で温度が異なる）。局所 Nu の定義は条件で異なる：(a)(b) は両壁共通の壁−バルク温度差、(c) は原書式(7.63) 第3ケースの定義に合わせ**加熱壁の熱流束と加熱壁−バルク温度差**で定義する（両壁平均は使わない）。q″ = 0 または Tw = T_in では局所 Nu は全区間未定義（null）とし、0除算の値を表示しない。断熱壁の温度は、発達分布で壁面の T_yy = 0 となる性質から隣接セル平均を壁面値として報告する（半セル再構成はしない）。"}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"流れ方向：有限体積の風上セル収支（流出は自セルのセル平均温度）。x 格子は等間隔、または入口側を細分する幾何格子（増加率 1〜1.25）。"},{"x":"横断方向：陰的3重対角（Thomas 法）。速度は放物線の解析セル平均を用いる。"},{"x":"バルク温度は行の熱容量流量 ρcp·ū_j·dy による重み付き平均（行平均同士の積による断面近似のため、厳密積分との差 O(dy²) を残すことを開発文書に明記）。"},{"x":"一定熱流束では壁温をセル平均に q″dy/(2k) を加えて再構成し、一定壁温では壁熱流束を半セル差分 k(Tw − T)/(dy/2) から求める。断熱壁は上端セルの上面に拡散結合を持たせない形で課す。"},{"x":"収支：壁からの総熱移動率と流体の顕熱増加（出口バルク−入口）を毎回照合し、残差（絶対・相対）を結果に記録する。実測では照合した全ケースで相対残差 1e-9 未満（概ね 1e-12 台）。"},{"x":"受理範囲（実コードで確認）：Re_Dh ≦ 2300、Pe_Dh ≧ 100。未知キー・非有限値・範囲外は日本語エラーで拒否し、結果を返さない（純関数で部分状態は残らない）。計算途中で非有限・非正・監視上限超過の温度が出た場合も受理しない。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"形状（H、L、奥行き）、物性、U、T_in と壁条件（種類と Tw または q″）、格子（nx、ny、幾何格子の増加率）を入力する。"},{"x":"ソルバーが入口から下流へ1列ずつマーチングし、各列で横断方向の陰的系を解く。"},{"x":"各 x 位置のバルク温度・壁温・局所 Nu と、出口での収支残差が返る。画面では温度場と分布、測定点の読み値を確認する。"}]},{"t":"p","x":"検算の例（出典：`GRAETZ_CHANNEL.md`）：一定熱流束で十分長い流路（L = 30 m、x* ≈ 3.3）では、出口局所 Nu = 8.2352940 となり、厳密値 140/17 = 8.2352941…、原書式(7.63) の 8.235 と一致する。壁−バルク温度差は 4.5995672 K で、quartic 解の (q″H/k)(17/70) = 4.5995671 K と一致する。"}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"画面（`graetz.html`、開発専用）は温度場の分布、x 方向のバルク温度・壁温・局所 Nu の変化、測定点の値を表示する。表示値と直接ソルバー計算の一致は Chromium のブラウザー試験で確認されている。"},{"x":"入口直後（x* が小さい領域）の局所 Nu は非常に大きく、格子依存のセル平均量である。有限の物理的な「初期最大値」として読んではいけない（項目13）。"},{"x":"条件(c) では上下の壁温が非対称に表示されるのが正常であり、断熱壁の出力熱流束は全区間厳密に 0 である。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"p","x":"検証の実測（出典：`GRAETZ_CHANNEL.md`。連続参照と解析限界による裏付け）："},{"t":"ul","items":[{"x":"連続スペクトル参照との照合（一定熱流束、Python の cosine-Galerkin スペクトル解。JS の有限体積作用素を流用していない）：格子 16×8 → 128×64 で出口 Nu の相対差が 1.6487% → 0.4484% → 0.1335% → 0.04435% と単調減少。全場に単一の収束次数は主張しない（x 風上と y 拡散の寄与混在、入口角の特異性）。"},{"x":"発達限界：一定熱流束 Nu = 8.2352940（厳密 140/17）、一定壁温の局所 Nu は x* = 0.202 で 7.54049（原書式(7.63)／Table 7.4 の 7.541 との差 5.1e-4）。片壁熱流束・他壁断熱では出口 Nu が 70/13 = 5.384615… へ下から単調に近づく（ny = 128 で差 −1.8e-9）。加熱壁−バルク差 (13/35)(q″H/k)、両壁温度差 (1/2)(q″H/k)、バルク−断熱壁差 (9/70)(q″H/k) の解析関係も実測で一致し、冷却（q″ < 0）でも同じ発達 Nu になる。"},{"x":"入口漸近（Lévêque）：局所 Nu は Nu_Dh,x = C·(12·Gz_x)^{1/3} に従う。定数は相似 ODE の定義から独立に計算されており、一定壁温で C = 1.23255058（θ′(0) = 0.53836605）、一定熱流束で C = 1.49039964（φ(0) = 1.53611717）。ソルバーの帯域平均は漸近値より +0.68%／+0.63%（x* ∈ [1e-4, 5e-4)）で、上から近づく。同じ定数を円管に適用すると原書式(7.28) の Lévêque 枝の係数 1.077 が再現されることも確認されている（形状が違うため平板の値には使わない）。"},{"x":"フェイリス側の独立参照（検証ノート §22、実装受領前の事前計算。リポジトリ外記録）：独立マーチング解法で、一定壁温（Tw = 350 K）の出口バルク温度 348.42075 K・Nu 7.5407、一定熱流束（q″ = 1000 W/m²）の出口バルク温度 637.82068 K（エネルギー収支 637.82015 K と差 0.0005 K）・Tw − Tb = 91.9917 K・Nu 8.2353 を得ており、実装の結果と一致する。第3境界条件についても独立検算（同 §25）で両壁温度差 9.469697 K が解析値と全桁一致している。"},{"x":"過渡ソルバー `heated-channel`（本線）の定常到達点との一致（最大差 約 1.1e-10／2.3e-10 K）は、同一離散系の別解法どうしの整合性であり、連続解への裏付けはスペクトル参照と解析限界が担う、と区別されている。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"速度は発達した Poiseuille 流を規定し、温度へはフィードバックしない（受動温度）。定物性。"},{"x":"軸方向熱伝導を省略する（Pe_Dh ≧ 100 の入力域で運用）。奥行きは一様な 2D 場の熱量換算スパンであり、有限の側壁を持つ矩形管ではない。"},{"x":"結果オブジェクトの前提明記どおり、圧力場は解かず、既知の駆動圧力勾配を表示するに留める。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"統合ツリーへ統合済み・開発専用（公開未承認）。`releaseApproved:false`、公開 allowlist 外。ブラウザー確認は Chromium のみ（WebKit はこの環境で起動できず未実施）。実機・支援技術・オフライン・外部専門家の確認は未実施。"},{"x":"扱わないもの：速度入口発達、非定常運動量、粘性加熱、浮力、物性の温度依存、側壁・一般形状・3D、乱流、過渡応答。"},{"x":"Re_Dh ≦ 2300 は層流の目安として設定した上限であり、精度保証の境界ではない。Pe 基準による軸方向伝導の省略は入力域の限定であり、省略誤差の上界を証明したものではない。"},{"x":"本線の締め可能性監査の時点では、本モデルは「別ブランチの定常 Graetz 実装（未統合・件数に算入しない）」と位置づけられていた。その後、統合ウェーブ1で開発専用モジュールとして統合ツリーへ統合された（公開は未承認のまま）。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「入口の局所 Nu が大きいのは入口効果で物理的に正しい最大値」** — 入口直後の値は一様入口と壁条件が角で適合しないことによる格子依存のセル平均量で、x = 0 の特異点そのものは評価しない。物理として読めるのは Lévêque 漸近への近づき方である。"},{"x":"**「発達 Nu は壁条件によらず同じ」** — 誤り。平行平板では一定壁温 7.541、両壁一定熱流束 8.235、片壁熱流束・他壁断熱 5.385（加熱壁基準）と、条件ごとに異なる（原書式(7.63)）。"},{"x":"**「片壁条件の Nu は両壁の平均で定義する」** — 誤り。本モデルは原書の定義に合わせ、加熱壁の熱流束と加熱壁−バルク温度差で定義する。定義を変えれば数値は変わる。"},{"x":"**「定常解は過渡ソルバーを長時間回したものと同じはず」** — 離散系が同じなら定常到達点は一致する（実測 約 1e-10 K）が、それは同一 PDE・同一離散化の範囲の話であり、連続解の正しさの証明はスペクトル参照と解析限界が担う。"},{"x":"**「奥行きを変えれば側壁のある矩形管になる」** — 誤り。奥行きは熱量換算のスパンで、側壁は存在しない。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、§7.2（バルク温度、式(7.3)〜(7.5)）、§7.4（一定壁温の指数減衰、式(7.57) の考え方）、§7.5（非円形ダクト：速度分布 式(7.62)、発達 Nu 式(7.63)、Table 7.4。ただし Table 7.4 の一定熱流束の値は周方向一様な壁温を仮定した値である点に §7.5 が注意している）、Graetz 数 式(7.26)。"},{"x":"アプリの教材：本線の学習用流路モデル（`dynamic/channel-learning.mjs`、文書 `docs/dynamic/CHANNEL_LEARNING.md`）と、同じ Poiseuille 流・両壁一定熱流束の過渡版である `dynamic/dev/heated-channel.mjs`（文書 `HEATED_CHANNEL_DEVELOPMENT.md`）が関連する。本モデルは開発専用のため公開画面からの導線はない。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第5.1節・第8節）に基づく。"},{"t":"p","x":"**現行の問題バンク（751問）に、本モデル（平行平板チャネルの熱発達・Graetz 問題）に直接対応する問題はない。** 「Graetz／グレツ」を名指しする問題は 0 件であり、平行平板チャネルの熱発達・バルク温度の指数減衰そのものを扱う問題はバンクに無い。推測で埋めず、その事実をここに明記する。"},{"t":"p","x":"最も近いのは、非円形ダクトの発達した流れの Nu と境界条件を扱う次の問題である。"},{"t":"ul","items":[{"x":"`supp-geometry-correlation-square-h-v1` — 正方形ダクトの発達層流の Nu_Dh。"},{"x":"`supp-geometry-correlation-duct-thermal-boundary-v1` — ダクトの周方向の熱的境界条件と Nu。"},{"x":"`supp-geometry-correlation-duct-dh-not-sufficient-v1` — 水力直径 D_h だけでは Nu が決まらないこと。"}]},{"t":"p","x":"入口・助走区間の考え方については、円管・一定壁温の説明書の項目15に主掲載された助走区間の 4 件も近い。"}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（§7.2、§7.4、§7.5、式(7.26)、式(7.62)、式(7.63)、Table 7.4）。"},{"x":"本リポジトリ（フェイリス側ブランチ）の検証記録：`docs/dynamic/GRAETZ_CHANNEL.md`（支配式・数値法・検証実測・限界）、連続スペクトル参照 `docs/dynamic/GRAETZ_CONTINUOUS_REFERENCE_20261106.md`／`.json`、Lévêque 参照 `docs/dynamic/GRAETZ_LEVEQUE_REFERENCE_20261107.json` と生成器 `scripts/dynamic-graetz-leveque-reference.py`。"},{"x":"リポジトリ外の検証記録：フェイリス側検証ノート §22（独立参照値）、§25（第3境界条件の独立検算）—— `~/workspace/dev/heat-sim-benchmarks/verification-notes-20261106.md`。"}]}]}]},{"id":"forced-pipe-heat-flux","name":"円管・一定熱流束（入口域）","source":"docs/dynamic/FORCED_CONVECTION_MANUAL_PIPE_HEAT_FLUX_20261107.md","screen":null,"lead":[{"label":"対象モデル","x":"開発専用モジュール `dynamic/dev/heated-pipe.mjs` と専用画面 `dynamic/dev/heated-pipe.html`（UI/view/Worker 分離）。本線 `codex/dynamic-heat-simulation` の成果物。`releaseApproved:false`、公開 allowlist 外。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"円管の中を、すでに放物線状に発達した層流（Hagen–Poiseuille 流）が流れている。管壁からは一定の熱流束 q″ が与えられ（加熱または冷却）、流体は流れ方向に進みながら一様に温まっていく。十分下流では温度分布の形が固定され（熱的に発達し）、壁温とバルク温度の差が一定値に落ち着いて、その比から Nusselt 数 4.364（= 48/11）が得られる。このモデルは入口から発達までの**非定常**の温度発展を、軸対称の環状セルで解く。熱流束は課すが壁温は結果として計算され、両方を同時に課すことはしない。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"電気ヒーターで管壁からほぼ一定の熱流束が入る管内加熱で、壁温がバルク温度よりどれだけ高くなるかの学習。"},{"x":"「一定熱流束では発達 Nu が 4.364、一定壁温では 3.657」と条件で値が違う理由の理解。"},{"x":"加熱と冷却（q″ の符号反転）で温度場が対称に振る舞うことの確認。"}]},{"t":"p","x":"いずれも指定された発達速度場の中の受動温度の学習モデルであり、実際の配管設計の保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"軸対称の円管（半径 R、長さ L）。速度は発達した Hagen–Poiseuille 流 u(r) = 2Ub(1 − (r/R)²) を**与え**（解かない）、温度だけをエネルギー方程式で解く。"},{"t":"ul","items":[{"x":"エネルギー方程式（軸方向流体伝導を省略）：∂T/∂t + u(r) ∂T/∂x = α (1/r) ∂/∂r (r ∂T/∂r)、α = k/(ρcp)。"},{"x":"入口条件：x = 0 で T = T_in（一様）。壁条件：r = R で −k ∂T/∂r = q″（一定、流体へ正が加熱）。"},{"x":"バルク温度 Tb(x) の定義は教科書 §7.2 式(7.3)〜(7.5)。発達領域では壁−バルク温度差が一定となり、Nu_D = q″D/(k(Tw − Tb)) → 48/11 = 4.3636…（教科書 式(7.23) の印刷値 4.364）。"},{"x":"発達した温度分布は quartic（4次）型の解析形を持ち、これが独立検証の連続参照に使われている（項目10）。"},{"x":"注意：教科書 §7.5 は、Table 7.4 の一定熱流束の値が「周方向に一様な壁温」を仮定した値であることに注意を促している。本モデルの q″ は周方向一様な熱流束であり、条件の取り違えに注意する（項目13）。"}]}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["R, D = 2R, L","管半径、直径、管長","m"],["Ub","平均（バルク）流速","m/s"],["u(r)","発達速度分布（放物線）","m/s"],["ρ, ν, cp, k","密度、動粘度、比熱、熱伝導率（一定物性）","kg/m³, m²/s, J/(kg·K), W/(m·K)"],["α = k/(ρcp)","熱拡散率","m²/s"],["T_in","入口温度","K"],["q″","壁熱流束（一定、符号つき）","W/m²"],["Tw(x, t)","壁温（計算結果）","K"],["Tb(x, t)","バルク温度","K"],["θ = T − T_ref","保持する温度オフセット（主状態）","K"],["Re_D, Pr, Pe_D = Re·Pr","Reynolds 数、Prandtl 数、Péclet 数","—"],["Nu_D","壁−バルク基準の Nusselt 数（瞬間値／発達値）","—"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"管内は一様温度（入口温度が既定）から開始する。初期の瞬間 Nu（= 4·nr の形で現れる値）は半セル処理による格子依存値であり、物理的な初期最大値ではない（項目13）。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"ul","items":[{"x":"壁：r = R で熱流束 q″ を課す。壁温はセル平均から半セル伝導で再構成して表示する（結果量）。"},{"x":"対称軸：r = 0 は断熱壁ではなく軸対称の中心で、軸の熱流は面積 0 のためゼロになる。画面でも対称軸と外周壁を区別する。"},{"x":"入口：T = T_in（一様）。出口：移流流出。"},{"x":"壁熱は全円周 2πRL で積算し、質量流量は ρUbπR² を使う（矩形モデルの奥行き換算に置き換えない）。"},{"x":"一定壁温モデル（別モデル）の snapshot との混用は拒否する。"}]}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"空間：円管の環帯有限体積（環帯の体積平均が状態）。軸方向は風上、半径方向は中央差分。"},{"x":"時間：SSPRK2。主状態は θ で保持し、微小な熱を絶対温度の丸めで捨てない。"},{"x":"収支：壁／入口／出口／正味の4成分の熱、全環帯の蓄熱を保持し、完全復元／取消が可能。壁熱と蓄熱の照合が受理条件に含まれる。"},{"x":"精度についての正直な区別：軸方向の風上と入口の平均積の誤差を含むため、**全場が2次精度とは主張しない**（時間積分の次数 2 とは別の話。項目10）。"},{"x":"受理範囲（開発文書と事前登録に基づく）：Re_D ≦ 1000、Pe_D ≧ 100、L/D ≧ 5、固定物性・小温度差。`releaseApproved:false`。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"形状（R、L）、物性、Ub、T_in、q″（符号つき）、格子と1コマの物理時間を設定する。"},{"x":"Worker が自動刻み（画面の空気参照では事前に選ばれた safeDt/8）で時間発展させ、温度場・壁温・バルク温度・瞬間 Nu と4成分の熱が表示される。"},{"x":"A/B 比較では2条件を共通の色尺度で比べられ、巻き戻しは同じ場を再現する。無効入力の後は受理済みの条件と時刻が保持される。"}]},{"t":"p","x":"検算の例：十分下流の定常的な断面では壁−バルク温度差が一定になり、Nu_D は 48/11 = 4.3636… に近づく（項目10の最細格子実測 4.36447122）。"}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"画面は r ≧ 0 の半径断面を表示するが、これは全円周の環帯平均を塗ったもの。表示は実寸からの半径方向拡大を明記している。測定位置は、選択位置／環帯の面積重心／壁を区別して表示される。"},{"x":"壁熱の符号は加熱・冷却で反転し、実熱積算（J）と瞬間率（W）は別々に表示される。"},{"x":"瞬間 Nu は過渡の比であり、q″ = 0 や壁−バルク差 0 では未定義になる。定常相関として読んではいけない（項目13）。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"p","x":"検証の実測（出典：`HEATED_PIPE.md` と各参照 JSON。予算は実行前に事前登録された）："},{"t":"ul","items":[{"x":"時間精度：独立な環帯行列指数（別の物理環帯 C/G・放物線流量の原始関数で構成）に対し、全温度最大差 7.71628e-6 K、全4成分の熱差 1.40220e-5 J、時間次数 2.01776。"},{"x":"空間精度：独自の quartic 連続場の環帯体積平均と、別の定常疎行列による参照に対し、4格子で RMS が 0.0137647 → 0.00659505 → 0.00321097 → 0.00158372 K と縮小（最終次数 1.01969。軸方向風上の1次寄与を反映する）。最細格子の Nu は 4.36447122 で、厳密値 48/11 との差は 0.0191321%。"},{"x":"実空気寸法の独立指数参照では、既定 32×16・0.01 s・safeDt/8 で最大差 6.41234e-6 K、全熱差 1.69375e-10 J、時間次数 2.00442。ただしこれは固定 300 K 物性の計算であり、空気物性モデル自体の独立測定ではない、と開発文書は区別している。"},{"x":"実 Worker の全場・全4熱が時間参照と照合され、完全復元、破損した熱や未知物理の拒否後の状態保持、取消後の再計算、加熱・冷却の対称が Chromium／WebKit の双方で確認されている。"},{"x":"なお上記の定常比較は「独立な定常ソルバーで解いた場」との比較であり、製品を一様初期条件から時間発展させて定常に到達させた試験ではない、と開発文書は明記している。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"速度は発達した Hagen–Poiseuille 流を規定し、温度へはフィードバックしない（受動温度）。定物性・小温度差。"},{"x":"結果オブジェクトの assumptions に明記：軸対称温度、環帯体積平均が状態、バルクは環帯平均の積、壁温は半セル再構成、軸方向流体伝導・粘性加熱・浮力は省略、入口運動量は解かない、一般 CFD ではない。"},{"x":"圧力勾配と壁せん断は既知の解析量として表示するもので、圧力場を解いてはいない。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"開発専用・未公開。実機・支援技術・開発専用オフライン・外部専門家の確認は未実施。画面のブラウザー確認は Chromium で実施済み（WebKit は検証環境で起動できず未実施）。"},{"x":"扱わないもの：軸方向流体伝導、速度入口発達・非定常運動量、粘性加熱、浮力、乱流、一般形状・3D、温度依存物性。"},{"x":"全場の空間精度は1次寄与を含む（項目7・10）ため、細格子での値だけを見て高次精度と誤解してはいけない。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「一定熱流束の発達 Nu は 3.657」** — 誤り。3.657 は一定壁温の値（式(7.22)）。一定熱流束では 48/11 = 4.364（式(7.23)）であり、平行平板の 140/17 = 8.235 とも幾何が違う。"},{"x":"**「Table 7.4 の一定熱流束の値をそのまま使える」** — 教科書 §7.5 の注意どおり、Table 7.4 の一定熱流束の値は周方向一様な壁温を仮定した条件の値であり、本モデルの「周方向一様な熱流束」とは条件が異なる。値の出所の条件を確認すること。"},{"x":"**「時間次数が2だから場全体も2次精度」** — 誤り。時間積分は2次だが、空間は軸方向風上などの1次寄与を含み、実測の空間次数は約 1.02 である。"},{"x":"**「初期の Nu が大きいのは入口効果の物理的最大値」** — 初期値（4·nr の形）は半セル処理の格子依存値で、物理的な最大値ではない。"},{"x":"**「瞬間 Nu を定常相関として設計に使える」** — 誤り。瞬間 Nu は過渡の比であり、q″ = 0 や壁−バルク差 0 では未定義になる。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、§7.2（バルク温度、式(7.3)〜(7.5)）、§7.4（発達値 式(7.23) の Nu = 4.364）、§7.5（Table 7.4 と一定熱流束の値に関する注意）。"},{"x":"アプリの教材：一定壁温の対モデル（`FORCED_CONVECTION_MANUAL_PIPE_WALL_TEMPERATURE_20261107.md`）、平行平板版（`FORCED_CONVECTION_MANUAL_GRAETZ_CHANNEL_20261107.md`）。開発専用のため公開画面からの導線はない。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第5.3節）に基づく。記載した ID はすべて問題バンク `data/questions.json` の実在 ID であり、アプリの演習（`../index.html#quiz`）でそのまま検索できる。主掲載は次の 3 件（全件）。ここでの本モデルの呼称は一定熱流束（constant heat flux）を指し、第9章の沸騰の限界熱流束とは別である。発達 Nu_D=4.364（問題内では 4.36）と熱流束一定でのバルク温度の線形変化を扱う専用問題はこの 3 件に限られ、専用問題は少ない。"},{"t":"ul","items":[{"x":"`supp-advanced-ch7-calc` — 一様な壁面熱流束の発達円管層流で、Nu_D=4.36 から h を求める。"},{"x":"`supp-batch2-constant-flux-pipe-h-v1` — 壁熱流束一定の発達層流の h の計算。"},{"x":"`supp-internal-flow-surface-flux-boundary-v1` — 一様な壁熱流束を与えた流路におけるバルク温度の線形変化。"}]},{"t":"p","x":"相互参照：`supp-section-7-2`（一定壁温と一定熱流束で Nu が違う理由）と `supp-internal-flow-thermal-developed-v1`（熱的に発達した条件でのバルク温度）は円管・一定壁温の説明書の項目15に主掲載されている。"}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（§7.2、§7.4、§7.5、式(7.23)、Table 7.4）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/HEATED_PIPE.md`、`docs/dynamic/HEATED_PIPE_WIP_20261107.md`（事前登録）、`docs/dynamic/HEATED_PIPE_TIME_REFERENCE_20261107_v1.json`、`docs/dynamic/HEATED_PIPE_SPATIAL_REFERENCE_20261107_v1.json`、`docs/dynamic/HEATED_PIPE_AIR_TIME_REFERENCE_20261107_v1.json`、`docs/dynamic/HEATED_PIPE_UI_CHECKPOINT_20261107.json`、`docs/dynamic/HEATED_PIPE_WORKER_CHECKPOINT_20261107.json`。"}]}]}]},{"id":"forced-pipe-wall-temperature","name":"円管・一定壁温（入口域）","source":"docs/dynamic/FORCED_CONVECTION_MANUAL_PIPE_WALL_TEMPERATURE_20261107.md","screen":null,"lead":[{"label":"対象モデル","x":"開発専用モジュール `dynamic/dev/pipe-wall-temperature.mjs`（生成関数 `createWallTemperaturePipe`）と専用画面 `dynamic/dev/pipe-wall-temperature.html`（UI/view/Worker 分離）。本線 `codex/dynamic-heat-simulation` の成果物。`releaseApproved:false`、公開 allowlist 外。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"円管の中を、すでに放物線状に発達した層流（Hagen–Poiseuille 流）が流れている。管壁は一定温度 Tw に保たれ、入口から一様温度の流体が入る。流体は壁から熱を受け（または壁へ熱を失い）、下流へ進むにつれてバルク温度が壁温へ指数関数的に近づいていく（教科書 §7.4 の Graetz 型の熱的入口発達）。このモデルはその**非定常**の温度発展を、軸対称の環状セルで解く。壁温は課すが壁の熱流束は結果として計算され、両方を同時に課すことはしない。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"恒温槽や蒸気ジャケットで壁温がほぼ一定に保たれる管内加熱・冷却で、出口温度が壁温へどこまで近づくかの学習。"},{"x":"「十分に長い管では発達 Nusselt 数が 3.657 になる」ことと、「入口付近では局所 Nu がそれより大きい」ことの区別。"},{"x":"式(7.57) の指数減衰（バルク温度の壁温への接近）を、入口効果を含む数値解と比べる教材。"}]},{"t":"p","x":"いずれも指定された発達速度場の中の受動温度の学習モデルであり、実際の配管設計の保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"軸対称の円管（半径 R、長さ L）。速度は発達した Hagen–Poiseuille 流 u(r) = 2Ub(1 − (r/R)²) を**与え**（解かない）、温度だけをエネルギー方程式で解く。"},{"t":"ul","items":[{"x":"エネルギー方程式（軸方向流体伝導を省略）：∂T/∂t + u(r) ∂T/∂x = α (1/r) ∂/∂r (r ∂T/∂r)、α = k/(ρcp)。"},{"x":"入口条件：x = 0 で T = T_in（一様）。初期条件：管内一様温度（項目5）。"},{"x":"壁条件：r = R で T = Tw（一定）。壁熱流束は壁の伝導 G = k·2πR·dx/(dr/2) を介して各段で計算する結果量である。"},{"x":"バルク温度 Tb(x) の定義は教科書 §7.2 式(7.3)〜(7.5)。十分発達した領域では Nu_D → λ₁/2 = 3.65679…（教科書 式(7.22) の印刷値 3.657）。λ₁ = 7.3135869155… は Graetz 固有問題 (zf′)′ + λz(1 − z²)f = 0 の第1固有値である。"},{"x":"バルク温度の指数減衰 式(**7.57**) については項目10・13で注意するとおり、h 一定を前提とする関係式であり、発達値 3.657 をそのまま代入すると入口効果の分だけ厳密解とずれる。本モデルは (7.57)＋3.657 で計算してはいない。"}]}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["R, D = 2R, L","管半径、直径、管長","m"],["Ub","平均（バルク）流速","m/s"],["u(r)","発達速度分布（放物線）","m/s"],["ρ, ν, cp, k","密度、動粘度、比熱、熱伝導率（一定物性）","kg/m³, m²/s, J/(kg·K), W/(m·K)"],["α = k/(ρcp)","熱拡散率","m²/s"],["T_in, Tw","入口温度、壁温","K"],["Tb(x, t)","バルク温度","K"],["θ = T − T_ref","保持する温度オフセット（主状態）","K"],["q″_w(x, t)","壁熱流束（計算結果、符号つき）","W/m²"],["Re_D, Pr, Pe_D = Re·Pr","Reynolds 数、Prandtl 数、Péclet 数","—"],["Nu_D","壁−バルク基準の Nusselt 数（瞬間値／発達値）","—"],["λ₁","Graetz 第1固有値 7.3135869155…","—"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"管内は一様温度（画面の実空気条件では入口温度と同値が既定）から開始する。初期の瞬間 Nu（= 4·nr の形で現れる値）は半セル処理による格子依存値であり、物理的な初期最大値ではない（項目13）。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"ul","items":[{"x":"壁：r = R で T = Tw を課す。壁熱は半セル伝導で計算し、壁の G を安定刻みの上限にも含める。"},{"x":"対称軸：r = 0 は断熱壁ではなく軸対称の中心であり、軸の熱流は面積 0 のため自動的にゼロになる。画面でも対称軸と外周壁を区別して表示する。"},{"x":"入口：T = T_in（一様）。出口：移流流出。"},{"x":"一定熱流束モデル（別モデル）の snapshot や同時 q 入力は拒否する（壁温と熱流束を同時に課さない）。"}]}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"空間：円管の環帯有限体積（環帯の体積平均が状態）。軸方向は風上、半径方向は中央差分。"},{"x":"時間：SSPRK2（正性を保つ2段 Runge–Kutta）。主状態は θ（基準温度からのオフセット）で保持し、絶対温度の丸めで微小な熱を捨てない。"},{"x":"収支：壁／入口／出口／正味の4成分の熱、全環帯の蓄熱、収支の丸め予算を保持し、完全復元／取消（巻き戻し）が可能。質量流量は ρUbπR² の解析値と照合される。"},{"x":"受理範囲（実コードで確認）：Re_D ≦ 1000、Pe_D ≧ 100、L/D ≧ 5。この範囲外、未知キー、別モデルの snapshot は日本語の理由つきで拒否し、受理済み状態を保持する。`releaseApproved:false`。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"形状（R、L）、物性、Ub、T_in、Tw、格子（nx × nr）と1コマの物理時間を設定する（画面の実空気プリセット：300 K 参考空気、L = 50 mm／R = 5 mm、Ub 0.24〜1.5 m/s、Tw と入口／初期 280〜330 K、格子 32×16／64×32／128×64）。"},{"x":"Worker が自動刻み（事前登録では safeDt/16）で時間発展させ、温度場・壁熱流束・バルク温度・瞬間 Nu が表示される。"},{"x":"A/B 比較では2条件を共通の色尺度で比べられ、巻き戻しは bit 単位で同じ場を再現する。"}]},{"t":"p","x":"検算の考え方：定常に近づいた出口バルク温度は、Graetz 級数解（項目10）で独立に検算できる。安易に式(7.57) へ発達 Nu 3.657 を代入した値とは一致しないのが正しく、その理由は項目10・13にある。"}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"画面は r ≧ 0 の半径断面を表示するが、これは全円周の環帯平均を塗ったもので、管を切り開いた半分の実像ではない。測定位置は、選択位置／環帯の面積重心／点としての壁温を区別して表示される。"},{"x":"壁熱の矢印は各断面の実計算結果の符号だけを示す（加熱と冷却で向きが反転する）。"},{"x":"瞬間 Nu は過渡の比であり、Tw = Tb では未定義、q = 0 かつ Tw ≠ Tb では比 0 を保持する。定常相関の値として読んではいけない。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"p","x":"検証の実測（出典：`PIPE_WALL_TEMPERATURE.md` と各チェックポイント。予算は実行前に事前登録された）："},{"t":"ul","items":[{"x":"時間精度：独立な環帯行列指数（別の物理環帯 C/G・放物線流量の原始関数・壁面 Dirichlet G で構成）に対し、元の刻み safeDt×1〜1/16 では全熱差 9.93e-4 J が予算 1e-4 J を**未達**だった記録が、閾値を緩めずそのまま保存されている。事前に追加された 1/32・1/64・1/128 では熱差が 2.46e-4 → 6.14e-5 → 1.53e-5 J、最細温度差 1.94e-7 K、時間次数 2.00380 で達成した（v1 の未達は書き換えられていない）。"},{"x":"発達限界の独立照合：80桁べき級数から λ₁ = 7.31358691552658…、Nu_D = λ₁/2 = 3.65679345776329… を求め、別 IVP と Gauss 積分で照合（場差 8.13e-15、Nu 差 2.5e-14）。定常場の4格子系列は RMS 0.0122028 → 0.00149266 K と縮小し（最終次数 0.99418、入口の風上1次を反映）、最細格子の Nu は 3.65620038 で固有値解との差 0.0162186%。"},{"x":"式(7.57) との関係：(7.57) は h 一定を前提とするため、発達値 3.657 を代入すると出口バルク温度は 302.783 K となり、級数解とは入口効果の分だけずれる（画面条件 L/D = 5、x* = 0.0223 では熱的に発達途上で、出口局所 Nu は約 4.09）。正しい長さ平均 Nu（級数解で約 5.64、Hausen 相関でも約 5.60 と裏付けられる）を使えば (7.57) は級数解・本モデルと一致する。画面の理論欄は 3.6568 を「十分熱的発達の検算値」と明示し、瞬間 Nu を定常相関として使うなと警告しており、製品側に不整合はない。"},{"x":"フェイリス側の独立検証（本線外の作業記録）：自前の50桁 Graetz 級数で λ₁ = 7.3135869155265847、Nu∞ = 3.6567934578 が画面の理論欄と一致。定常出口バルク温度は級数解 303.9534 K に対し、数値核が格子 32/64/128 で 303.9406／303.9454／303.9490 K と単調に収束（最細で差 −0.0043 K、駆動温度差 10 K の 0.043%）。画面表示値と数値核の直接計算も表示桁まで一致し（t = 0.01 s で 300.0121896 K 対 300.01218959 K）、質量流量は解析値と全桁一致、収支差は 1.7e-18 J だった。"},{"x":"画面の既定条件（Tw 310／Tin 300／Ub 0.5、0.01 s）は別の行列指数参照に対し全場最大差 2.64e-5 K、時間次数 2.00685。"},{"x":"なお上記の定常比較は「独立な定常ソルバーで解いた場」との比較であり、製品を一様初期条件から定常まで時間発展させた試験ではない、と開発文書は区別している。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"速度は発達した Hagen–Poiseuille 流を規定し、温度へはフィードバックしない（受動温度）。定物性。結果オブジェクトの assumptions に明記：軸対称温度、環帯体積平均が状態、バルクは環帯平均の積、壁熱は半セル伝導、軸方向流体伝導・粘性加熱・浮力は省略、入口運動量は解かない、一般 CFD ではない。"},{"x":"圧力勾配と壁せん断は既知の解析量として表示するもので、圧力場を解いてはいない。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"開発専用・未公開。実機・支援技術・専用オフライン・外部専門家の確認は未実施。画面のブラウザー確認は Chromium で実施済み（実 Worker・A/B・巻き戻し再現・モバイル明暗・DPR2。WebKit は検証環境で起動できず未実施）。"},{"x":"扱わないもの：非定常運動量、速度入口発達、軸方向流体伝導、粘性加熱、浮力、温度依存物性、乱流、非円形・周方向非一様・3D。"},{"x":"受理範囲は Re_D ≦ 1000、Pe_D ≧ 100、L/D ≧ 5 の受動温度の限定であり、この範囲外の精度は主張しない。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「式(7.57) に Nu = 3.657 を入れれば出口温度が出る」** — 誤り。(7.57) は h（したがって Nu）が一定という前提の式で、入口発達の途中では局所 Nu は 3.657 より大きい。発達値をそのまま入れると入口効果の分だけ出口バルク温度がずれる（項目10の実測：302.783 K 対 級数解 303.9534 K）。長さ平均の Nu を使えば (7.57) は正しく使える。"},{"x":"**「3.657 は 3.66 と書いても同じ」** — 検算値としては 3.6567934578… が固有値 λ₁/2 であり、平板の 7.541 や円管一定熱流束の 48/11（= 4.364）と取り違えてはいけない。"},{"x":"**「瞬間 Nu が表示されているから定常の熱伝達率が分かる」** — 誤り。瞬間 Nu は過渡の比で、Tw = Tb では未定義になる。定常相関として使うものではない。"},{"x":"**「初期の Nu が大きいのは入口効果の物理的最大値」** — 初期値（4·nr の形）は半セル処理の格子依存値で、物理的な最大値ではない。"},{"x":"**「壁温を課せば壁熱流束も同時に指定できる」** — 誤り。壁温を課した系では熱流束は結果である。同時指定の入力は拒否される。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、§7.2（バルク温度、式(7.3)〜(7.5)）、§7.4（一定壁温の Graetz 解と式(7.57)、発達値 式(7.22) の Nu = 3.657）、§7.5（Table 7.4 の読み方と注意）。"},{"x":"アプリの教材：一定熱流束の対モデル（本書の姉妹モデル `FORCED_CONVECTION_MANUAL_PIPE_HEAT_FLUX_20261107.md`）、平行平板版（`FORCED_CONVECTION_MANUAL_GRAETZ_CHANNEL_20261107.md`）。開発専用のため公開画面からの導線はない。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第5.2節）に基づく。記載した ID はすべて問題バンク `data/questions.json` の実在 ID であり、アプリの演習（`../index.html#quiz`）でそのまま検索できる。主掲載は次の 14 件（全件）で、一定壁温の発達 Nu_D=3.657（問題内では 3.66 と表記）、バルク温度の指数応答（式(7.57) 型）、NTU の扱いを本文で確認したものである。"},{"t":"ul","items":[{"x":"`supp-chapter-ch7-nu-boundary` — 一定壁温・十分発達した円管層流の代表的な Nu_D。"},{"x":"`supp-chapter-ch7-h` — Nu_D=3.66 から h を求める。"},{"x":"`supp-section-7-2` — 一定壁温と一定熱流束で Nu が違う理由（第7.2節の学習ノート）。"},{"x":"`supp-section-7-4` — 管内で流体温度が上がったとき Q を求めるのに必要な流体情報（第7.4節の学習ノート）。"},{"x":"`supp-applied-7-2-v1` — 一定壁温の円管層流で h を求める。"},{"x":"`supp-batch2-pipe-h-wall-temperature-v1` — 一定壁温・発達層流の h の計算。"},{"x":"`supp-batch2-local-wall-flux-v1` — 局所 h と局所壁面温度から局所壁面熱流束を求める。"},{"x":"`supp-internal-flow-thermal-developed-v1` — 熱的に十分発達した加熱管におけるバルク温度の説明。"},{"x":"`supp-internal-flow-surface-ntu-v1` — 一定壁温の一流体加熱における NTU。"},{"x":"`supp-internal-flow-surface-outlet-v1` — NTU から出口温度を求める指数応答。"},{"x":"`supp-internal-flow-surface-energy-rate-v1` — 入口・出口温度から熱移動率を求める。"},{"x":"`supp-internal-flow-surface-inlet-overestimate-v1` — 入口温度差だけを使って熱移動率を見積もる過大評価。"},{"x":"`supp-internal-flow-surface-variable-h-integral-v1` — h=h(x) の場合に指数応答で使う NTU。"},{"x":"`supp-internal-flow-surface-capacity-model-v1` — ε=1−exp(−NTU) という有効度式の適用。"}]},{"t":"h","x":"入口・助走区間（一定壁温／一定熱流束／Graetz 共通、主掲載 4 件）"},{"t":"ul","items":[{"x":"`supp-batch2-hydraulic-entry-length-v1` — 層流水力学的助走長の見積もり。"},{"x":"`supp-batch2-thermal-entry-length-v1` — 層流熱的助走長の見積もり。"},{"x":"`supp-batch2-pipe-entry-judgment-v1` — 助走区間内かどうかと、発達した Nu を使えるかの判断。"},{"x":"`supp-internal-flow-entrance-state-v1` — 助走長の目安から管内の発達状態を判断する。"}]}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（§7.2、§7.4、式(7.22)、式(7.57)）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/PIPE_WALL_TEMPERATURE.md`、`docs/dynamic/PIPE_WALL_TEMPERATURE_WIP_20261107.md`（事前登録予算）、`docs/dynamic/PIPE_WALL_TEMPERATURE_SPATIAL_REFERENCE_20261107_v1.json`、`docs/dynamic/PIPE_WALL_TEMPERATURE_TIME_REFERENCE_20261107_v1.json`（未達のまま保存）／`_v2.json`、`docs/dynamic/PIPE_WALL_TEMPERATURE_AIR_TIME_REFERENCE_20261107_v2.json`、`docs/dynamic/PIPE_WALL_TEMPERATURE_NUMERICAL_CHECKPOINT_20261107.json`、`docs/dynamic/PIPE_WALL_TEMPERATURE_UI_CHECKPOINT_20261107.json`。"},{"x":"本線外の検証記録：フェイリス側の円管 CWT 画面の独立検証（表示値と数値核の一致、自前 Graetz 級数による発達値・出口バルク温度の照合）——熱伝達チャットの作業記録（2026-11-07）。"}]}]}]},{"id":"natural-cavity","name":"閉キャビティ自然対流","source":"docs/dynamic/NATURAL_CONVECTION_MANUAL_CAVITY_20261107.md","screen":null,"lead":[{"label":"対象モデル","x":"`dynamic/dev/cavity.mjs` の `createCavity`（モデル識別子 `rectangular-cavity-v1`）。画面は `dynamic/dev/cavity.html`（自然対流の開発検証）、断面熱流束の診断は `dynamic/dev/cavity-heat-flux.mjs`、圧力投影は同ファイル内の `projectFaces`、運動量差分は `dynamic/dev/mac-momentum.mjs`、Poisson 前処理は `dynamic/dev/poisson-multigrid.mjs`。"},{"label":"対象範囲","x":"本書は浮力（`gravityBeta` ≠ 0）を有効にした自然対流の使い方に限る。同じ数値コアには移動壁（蓋駆動）用の入力もあるが、それは別モデル・別画面であり本書の対象外である。また製造解検証モード（検証用の外力・発熱を注入する専用経路）は、通常の物理計算ではないため項目7・10で言及するに留める。"},{"label":"状態","x":"開発専用・公開承認前（`releaseApproved:false`、公開ビルドに含めない）。画面自身にもその旨が明記されている。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"左右の壁に温度差をつけた、密閉された矩形（画面では正方形）の中の流体に生じる自然対流を計算する。温かい左壁に沿って流体が上昇し、冷たい右壁に沿って下降して、内部に1つの大きな循環ができる。駆動力は重力と温度による密度変化（浮力）だけであり、ファンやポンプのような外部の流れはない。画面の条件（温度差最大10 K、10 mm角の空気）では流れは層流で、熱の移動は伝導に流れの寄与が加わった比較的弱い対流である。時間を進めると過渡を経て、やがて定常な循環と温度分布に落ち着く様子を観察できる。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"二重ガラスの間の空気層で、ガラス間の熱の伝わり方が空気の循環でどう変わるか。"},{"x":"建物の壁の中の空気層や、断熱材のない中空壁の内部で起きる熱移動の考え方。"},{"x":"ファンのない電子機器の筐体の中で、部品の熱が空気の循環でどう逃げるか。"},{"x":"保温・保冷容器の内部で、温度の偏りが時間とともにどう均されるか。"},{"x":"室内で窓際の冷気が下降し、暖房側の空気が上昇する局所循環の定性的な理解。"}]},{"t":"p","x":"いずれも閉じた空間内の浮力駆動流れという共通性に基づく学習・概算のためであり、寸法・温度差・流体が異なる実物への数値の直接適用はしない（項目11・12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"非圧縮・層流・Boussinesq 近似のもとで、以下の式を解く（実装の構成は `docs/dynamic/CFD_DEVELOPMENT.md`、本書の記述は `dynamic/dev/cavity.mjs` の更新則に基づく）。"},{"t":"p","x":"連続の式："},{"t":"p","x":"∂u/∂x + ∂v/∂y = 0"},{"t":"p","x":"運動量（保存型で離散化する）："},{"t":"p","x":"∂u/∂t + ∂(uu)/∂x + ∂(uv)/∂y = −(1/ρ) ∂p/∂x + ν∇²u∂v/∂t + ∂(uv)/∂x + ∂(vv)/∂y = −(1/ρ) ∂p/∂y + ν∇²v + gβ(T − T_ref)"},{"t":"p","x":"エネルギー（顕熱のみ）："},{"t":"p","x":"∂T/∂t + u ∂T/∂x + v ∂T/∂y = α∇²T、ただし k = ρc_p α"},{"t":"ul","items":[{"x":"浮力は Boussinesq 近似として、密度変化を鉛直運動量の項 gβ(T − T_ref) にだけ入れる。実装では積 gβ を1つの入力 `gravityBeta` として与える。"},{"x":"エネルギー式は顕熱と境界からの熱量だけを扱い、粘性散逸や圧縮の仕事を熱源へ戻す完全な全エネルギー方程式ではない（`docs/dynamic/CFD_DEVELOPMENT.md` に明記）。"},{"x":"圧力 p は平均ゼロのゲージ圧（相対値）であり、絶対圧ではない（項目9・13）。"}]}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["x, y","水平・鉛直座標（原点は左下）","m"],["u, v","x・y 方向の速度（MAC 配置ではセルの面に置く）","m/s"],["T","温度（内部計算は絶対温度、画面の色表示は ℃）","K"],["T_ref","浮力の基準温度（画面では300 K）","K"],["p","ゲージ圧（平均ゼロに正規化した相対値）","Pa"],["ρ, c_p","密度、定圧比熱（一定物性）","kg/m³, J/(kg·K)"],["ν, α","動粘度、熱拡散率","m²/s"],["k = ρc_pα","熱伝導率（独立には与えず ρc_pα で決まる）","W/(m·K)"],["β","体積膨張係数","1/K"],["g","重力加速度（画面では向きの符号を含め変更可）","m/s²"],["gβ","浮力の係数（実装入力 `gravityBeta`）","m/(s²·K)"],["H, L","キャビティの高さ、幅（画面では両者とも10 mm）","m"],["ΔT","左右壁の温度差 T_left − T_right","K"],["Ra = gβΔT·H³/(να)","レイリー数（基準長さは高さ H）","—"],["Pr = ν/α","プラントル数","—"],["Nu₀","左壁の伝導熱流束の高さ平均を kΔT/H で割った値（「高温壁平均Nu」）","—"],["Nu₁/₂","鉛直中央面 x = L/2 の全熱流束（伝導＋移流）の高さ平均を kΔT/H で割った値","—"],["体積平均Nu","全鉛直断面の全熱流束Nuを x 方向に台形平均した値","—"],["Ec = U²/(c_pΔT)","エックルト数（画面ではセル中心最大速度からの参考表示のみ）","—"]]},{"t":"p","x":"Nu の3定義は測定する場所と量が異なる別々の量であり、同一視しない。定義の正確な対応は `dynamic/dev/cavity-heat-flux.mjs` の定義メタデータと、項目10の照合経緯に基づく。なおソルバーの `snapshot` が返す `nusselt` は Nu₀ であり、定義メタデータ（quantity: 'Nu_0', location: 'hot-wall x=0'）が併記される。"}]},{"n":5,"title":"初期条件","blocks":[{"t":"ul","items":[{"x":"画面：一様な初期温度300 K、速度ゼロ。左右の壁温は時刻0で段差状に設定される（左壁 300＋ΔT/2 K、右壁 300−ΔT/2 K）。"},{"x":"このため計算開始直後の壁面 Nu は大きな値を取りうるが、これは壁温の段差と半セル近似に依存する離散化上の見かけであり、物理的な有限の最大値として扱わない。格子を変えて比較するときは、同じ正の物理時刻で比べる（画面「理論・物性・適用範囲」に明記。例：16格子では初期値16）。"},{"x":"ベンチマーク設定（項目8）でも初期場は一様温度・静止で、壁温を時刻0に与える同型の設定である。"}]}]},{"n":6,"title":"境界条件","blocks":[{"t":"ul","items":[{"x":"左壁・右壁：温度固定（Dirichlet）。壁からの熱流束は、壁と隣接セル中心の間の半セルの伝導抵抗で評価する（2k(T_wall − T_cell)/dx）。"},{"x":"上壁・下壁：断熱（熱流束ゼロ）。"},{"x":"全ての壁：静止・滑りなし。法線速度はゼロ、接線速度は壁のゴースト値で no-slip を与える。"},{"x":"浮力の向きは画面の重力入力で反転できる（−9.81〜＋9.81 m/s²。正の浮力設定では温かい空気への浮力が上向き）。"},{"x":"本モデルに存在しない境界条件：熱流束指定、対流境界、開境界（入口・出口）。加熱・冷却の位置も変更できない（項目12）。"}]}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"空間配置：MAC（マーカー・アンド・セル）配置の保存型有限体積法。速度はセル面、温度と圧力はセル中心に置く。"},{"x":"運動量：保存型の2次中心差分（既定 `conservative2`）で拡散と移流を評価し、前進 Euler で予測する。実験用の高次差分（`polynomial4`）は本画面では選べない。"},{"x":"圧力投影：予測速度の発散を右辺として Neumann 型 Poisson 方程式を解き、速度を発散ゼロへ投影する。反復は前処理付き共役勾配法（前処理は Jacobi または多重格子）で、圧力は平均ゼロに保つ。反復の既定は計算核が許容値（相対）1e-10・上限2000回、開発画面が許容値1e-11・上限4000回と異なる。収束しない場合は元の状態を変更せず停止する。"},{"x":"連続性の検査：投影後の発散最大値が速度尺度に対する許容（1e-8×尺度）を超えると、更新前の状態のまま停止し、その旨を表示する。"},{"x":"温度：面を通る熱流束（伝導＋移流）を隣接セルへ等量・逆符号で計上する保存型で更新する。移流の面温度は風上（既定）または中心差分（中心差分ではセル Pe 数が2を超えると例外で拒否）。熱量の基準温度は273.15 K。"},{"x":"時間刻み：拡散と CFL の制限から決まる安定刻み `safeDt` 以下だけを受け付ける。画面では1コマの物理時間と刻み上限を指定し、内部で刻みを刻む。"},{"x":"格子：各方向4〜96（ソルバー API）。画面では正方形の 12／16／24／32／64 のみ。"},{"x":"失敗時の原子性：不正な入力・収束失敗・範囲超過は例外として返され、受理済みの状態は変更されない。"},{"x":"製造解検証モード：既知の連続場（ψ・p・T）から SymPy で独立に導出した外力・発熱を注入し、離散化の実装そのものを照合する専用経路。通常の自然対流計算では使わず、浮力や移動壁との併用は拒否される（項目10）。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"p","x":"画面での手順："},{"t":"ol","items":[{"x":"条件Aで左右壁の温度差、鉛直浮力の向き、格子数を設定し、「初期状態から計算」を押す。"},{"x":"再生／1コマ進める／1コマ戻す／時刻0へ戻すで時間を操作し、履歴スライダで保存したコマへ戻る。"},{"x":"表示量（温度／速度の大きさ／ゲージ圧）を切り替え、速度の矢印と瞬間流線を重ねる。計算場をクリックまたは矢印キーで測定点を動かす。"},{"x":"「現在の条件をBへ固定して比較」で条件Bを固定し、色スケール共通のまま並べて比べる。"},{"x":"詳細パネルで断面熱流束の3定義、運動エネルギーと圧力補正、計算条件・収支・収束を確認する。"}]},{"t":"p","x":"手計算で確認できる検算："},{"t":"ul","items":[{"x":"Ra の再計算（ベンチマーク設定、`scripts/dynamic-cfd-fine-grid.mjs` と同一）：1 m角、ρ = c_p = 1、α = 1、ν = 0.71、gβ = 710、ΔT = 1 K とすると Ra = gβΔT·H³/(να) = 710×1×1/(0.71×1) = 1000。"},{"x":"画面条件の上限：10 mm角・300 K の空気（項目11の物性）・ΔT = 10 K で Ra ≈ 931 となり、ソルバーの上限1000の内側にある（締め可能性監査の記録値）。"},{"x":"純伝導の極限：流れが止まれば3定義とも Nu = 1 に戻る。対流の寄与は「伝導限界からの超過」として読む（項目10のアスペクト比ケースの解釈も同じ考え方である）。"}]}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"色表示：温度 [℃]、速度の大きさ [m/s]、圧力（平均0のゲージ）[Pa] の3種を切り替える。A/B 比較では色の範囲は両条件で共通である。"},{"x":"速度の矢印：MAC 位置から補間した速度の方向と大きさ。間引いて描かれる。"},{"x":"瞬間流線：その時刻の速度場を凍結して追跡した線である。**流線は粒子の移動軌跡ではない**（画面にも明記）。粒子の軌跡表示は実装されていない。"},{"x":"測定点の読み値：温度と圧力は指定点が属するセルの中心値、速度は MAC 位置からの補間値である。点の厳密値ではない。"},{"x":"Nu の履歴グラフ：瞬間の左壁平均 Nu（Nu₀）の履歴である。定常相関の値ではなく、過渡中は変動し、初期には項目5の見かけの大きな値を取る。"},{"x":"詳細パネルの熱流束表示：Nu₀／Nu₁/₂／体積平均Nu は瞬間値であり、過渡中は互いに一致しない。一致するのは定常に限る（項目10）。"},{"x":"運動エネルギーの表示：MAC 速度から積分した離散運動エネルギーと、圧力補正で減る量の診断である。顕熱の収支とは別の量であり、混同しない（画面「運動エネルギーと圧力補正」）。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"p","x":"検証は「どの量を、どの条件で、どの参照と比べたか」を分けて読む。本モデルの検証の中心は、Ra = 1000・Pr = 0.71・正方形キャビティの定常ベンチマークである。"},{"t":"h","x":"標準ベンチマークとの照合（de Vahl Davis 1983）"},{"t":"p","x":"論文 Table V は3つの異なる Nu を併記する：全体平均 Nu = 1.118、中央面平均 Nu₁/₂ = 1.118、高温壁平均 Nu₀ = 1.117（論文自身の推定精度は約0.1%）。本ソルバーの格子系列（保存場の Python 再集計、`docs/dynamic/CFD_FINE_NATURAL_SUMMARY_20261106.json`）："},{"t":"table","head":["格子","Nu₀","局所Nu最大","u_max（位置 y）","v_max（位置 x）"],"rows":[["16","1.126319","1.541528","3.638743（0.84375）","3.719344（0.15625）"],["32","1.119943","1.515194","3.646848（0.828125）","3.707512（0.171875）"],["48（中心移流）","1.118749","—","—","—"],["64","1.118329","1.508583","3.649077（0.8203125）","3.700381（0.1796875）"]]},{"t":"ul","items":[{"x":"64格子の Nu₀ = 1.118329 は、対応する定義の論文値 Nu₀ = 1.117 との差が +0.00133 で、照合の予算0.002の内側にある。"},{"x":"格子系列の観測次数は約1.98、Richardson 外挿は Nu₀ ≈ 1.11778（`docs/dynamic/CFD_DEVELOPMENT.md`）。"},{"x":"最大速度（α/L で尺度した無次元値）：論文は u_max = 3.649（y = 0.813）、v_max = 3.697（x = 0.178）。64格子は u_max = 3.649077、v_max = 3.700381 で、値・位置とも近い。局所Nu最大は論文 1.505 に対して 1.508583。"},{"x":"定常では3定義がほぼ一致する（N64 での定義間の広がりは 1.06e-10）。これは閉キャビティの定常では全断面の全熱流束が一様になる保存則の帰結であり、定義が同一という意味ではない。"},{"x":"論文側には中面プロファイルの全点表が存在しないため、温度・速度の全分布の論文照合は最大値と位置で代表させる（プロファイル同士の照合は下記の独立ソルバーとの間で行った）。"}]},{"t":"h","x":"Nu の定義をめぐる照合の経緯（記録に基づく）"},{"t":"p","x":"当初、ソルバーの出力 Nu と論文値の差の解釈で混乱があった。論文 Table V には 1.118 と 1.117 という近い値が異なる定義で併記されており、ソルバーの `snapshot` が計算しているのは高温壁の伝導流束の平均、すなわち **Nu₀** である。壁の Nu₀（32格子の記録値 1.1199427644252182）を、論文が代表値として推奨する中央面 Nu₁/₂ の 1.118（全体平均も同じ 1.118）と直接比べると、差の一部は定義の違いであり、誤差そのものではない。一次資料の直接読取り（原論文スキャン、Allen & Reis の OCCAM Preprint 13/34 Table 7、Barakos & Mitsoulis (1994) Table III との相互確認）によって定義の対応が確定し、現在は `snapshot` に定義メタデータが併記され、照合は常に対応する定義同士で行う。確定した対応と旧記録の扱いは `docs/dynamic/DE_VAHL_DEFINITIONS_20261106.md` に記録されている。この経緯のため、本書でも文献の Nu を引用するときは必ず定義を併記する。"},{"t":"h","x":"その他の検証"},{"t":"ul","items":[{"x":"製造解検証：SymPy で独立に導出した外力・発熱との差は最大 2.84e-14、全場の誤差は約2次で減少する（`docs/dynamic/MANUFACTURED_VERIFICATION.md`）。ただし粗い格子では圧力の相対誤差が大きく、Poisson 残差や発散が小さいことから連続圧力の精度は主張しない（同文書に明記）。"},{"x":"保存量：発散は最大で1e-11級（48格子で最大 1.53113e-11）、全断面の正味質量流量は記録格子（16／32／64）で最大 1.21e-15 kg/s と丸め誤差級、顕熱収支の誤差は48格子で 7.09531e-13 J（`docs/dynamic/CFD_FINE_NATURAL_SUMMARY_20261106.json`、`docs/dynamic/CFD_DEVELOPMENT.md`）。"},{"x":"ブラウザー操作確認：実 Worker と Node 核の数値一致、64格子、取消・再開・巻き戻し、A/B 比較、浮力反転、測定点のキーボード操作、幅390／412／1280、明暗、localStorage 不変更、pageerror = 0 を Chromium／WebKit で確認済み（`tests/dynamic-cavity-browser.mjs`、チェックポイント記録）。ただし公開URL・オフライン・実機での確認は未実施である。"}]},{"t":"h","x":"フェイリス側の独立検証（リポジトリ外の記録）"},{"t":"p","x":"以下は本リポジトリの外にあるフェイリス検証ラインの記録であり、所在を明示して引用する。"},{"t":"ul","items":[{"x":"独立ソルバー再計算（`~/workspace/dev/heat-sim-benchmarks/natural-convection-independent-solver-20261107.md`）：定式化の異なる渦度–流れ関数（ω–ψ）ソルバー（定常 Newton 解法）で同じベンチマークを再計算し、M = 128 で Nu₀ = 1.117778、Nu₁/₂ = 1.117773、体積平均Nu = 1.117778 を得た。両ソルバーの Richardson 外挿は 1.117776 と 1.117783 で差 7e-6 と一致する。最大速度は u_max = 3.649416（y = 0.8125）、v_max = 3.697205（x = 0.1796875）。中面プロファイルの照合では温度の RMS 差 1.8e-4 級、速度は本ソルバーの32格子実走場に対して RMS 0.017〜0.019 であった。本ソルバーの32格子記録は実走で 1e-12 級に再現することも確認された。"},{"x":"Pr・アスペクト比ケース（`~/workspace/dev/heat-sim-benchmarks/natural-convection-cases-20261107.md`）：API 経由で Pr = 0.1／0.71／1／7（Ra = 1000、正方形）と、アスペクト比 AR = 2／0.5（Pr = 0.71）の計12ケースを定常まで実測した。Richardson 外挿の Nu₀ は Pr ≥ 0.71 で ≈1.1178 に揃い、Pr = 0.1 では約0.16%低い。AR = 2 では Nu（H基準）は伝導限界0.5に対して +21.4%、AR = 0.5 では伝導限界2.0に対して +0.44%で、幅基準の Ra（AR = 2 で8000、AR = 0.5 で125）で単調に説明できる。全ケースで定常時に3定義が7桁目まで一致し、発散最大 3.3e-11 以下、相対エネルギー誤差 1.3e-14 以下であった。Pr ≠ 0.71 向けの外部ベンチマーク表は用いていない（一般的な多 Pr ベンチマークは Ra ≥ 10⁴ で、本モデルの受理範囲外）。"}]},{"t":"h","x":"解釈上の限定"},{"t":"ul","items":[{"x":"検証が外部参照と照合できているのは、Ra = 1000・Pr ≈ 0.71・正方形の定常量が中心である。過渡過程そのものの外部参照照合と、圧力場のベンチマーク照合は未実施である。"},{"x":"Pr の複数値と非正方形は API 経由のケース測定と独立検証があるが、画面（UI）では変更できない。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"2次元、非圧縮、層流。奥行きは評価用の長さ（既定1 m）であり、奥行き方向の端面はモデル化しない。"},{"x":"Boussinesq 近似：密度変化は浮力項のみ。|β(T − T_ref)| ≤ 0.1 を保守的な監視範囲として生成時と各ステップで強制し、超える条件は拒否する。これは精度の普遍的な保証ではない（`docs/dynamic/CFD_DEVELOPMENT.md`）。"},{"x":"一定物性（温度依存なし）。画面の物性は300 K の空気の参照値：ρ = 1.177 kg/m³、c_p = 1006 J/(kg·K)、k = 0.0264 W/(m·K)、ν = 1.575×10⁻⁵ m²/s、β = 1/300 K⁻¹（理想気体の近似）。出典は教科書付録 A.6（書籍755／PDF769）（画面「理論・物性・適用範囲」）。このとき α = k/(ρc_p) ≈ 2.23×10⁻⁵ m²/s、Pr ≈ 0.71。"},{"x":"エネルギーは顕熱のみ。放射との連成、相変化は含まない。"},{"x":"圧力は相対値（ゲージ）であり、絶対圧の水準は決まらない。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"Ra > 1000 は仕様として例外で拒否する。したがって de Vahl Davis の Ra = 10⁴〜10⁶ のケースは照合できず、高 Ra の流れ（多セル化・乱流への遷移を含む）は対象外である。"},{"x":"開放領域の鉛直加熱壁に沿う外部自然対流（温度境界層型）の動的モデルはない。本モデルで扱えるのは閉キャビティの熱壁の内面だけである。静的な相関の学習モデル `natural-convection-vertical.mjs` は別物であり、本モデルの検証には数えない。"},{"x":"発熱体の周囲の自然対流は解けない。ソルバーは障害物・自由形状を明示的に拒否する。内部熱源は製造解検証専用で、浮力とは併用できない。"},{"x":"境界条件は等温壁と断熱のみ。熱流束・対流境界、加熱／冷却位置の変更はできない。画面では流体（空気）・形状（10 mm角の正方形）・物性は固定で、アスペクト比も変えられない（API では矩形と Pr の変更を受け付けるが、画面の機能ではない）。"},{"x":"温度境界層の定量表示、熱流束の場表示、粒子軌跡の表示はない。"},{"x":"3次元、乱流、固体との共役伝熱、圧縮性、開境界は未対応である。"},{"x":"開発専用・公開承認前であり、公開URL・オフライン・実機での動作は未検証である（`docs/dynamic/CAVITY_UI_CHECKPOINT_20261105.json` に mainPublished:false、offlineVerified:false、realDeviceVerified:false の記録）。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「Nusselt 数は1つだけ」** — 誤り。本モデルには測定場所の異なる3定義（Nu₀／Nu₁/₂／体積平均Nu）があり、論文 Table V にも 1.117 と 1.118 が定義別に併記されている。壁の Nu₀ を論文の代表値 1.118 と比べて誤差と判断するのは定義の取り違えである（項目10の経緯）。"},{"x":"**「流線は粒子の軌跡」** — 誤り。瞬間流線はその時刻の速度場に接する線であり、粒子がたどる経路ではない。"},{"x":"**「圧力の色が絶対圧を表す」** — 誤り。平均ゼロのゲージ圧（相対値）である。また Poisson 残差や発散が小さいことは、連続圧力の精度の保証ではない。"},{"x":"**「計算開始直後の Nu の大きなピークが物理現象」** — 誤り。壁温の段差と半セル近似による離散化上の見かけであり、格子数に依存する（項目5）。"},{"x":"**「過渡中に3定義が食い違うのは異常」** — 誤り。断面ごとに熱の流れ方が異なる過渡では当然食い違う。一致するのは定常だけであり、その一致は保存性の確認になる。"},{"x":"**「64格子でベンチマークと合ったから一般の CFD として正確」** — 誤り。検証は限定された条件（Ra = 1000・Pr ≈ 0.71・正方形・定常量）に対するもので、一般 CFD の精度承認ではない（画面とチェックポイントにも明記）。"},{"x":"**「温度差を大きくすれば高い Ra の様子が見られる」** — 誤り。Ra > 1000 は拒否され、Boussinesq の監視範囲 |βΔT| ≤ 0.1 もある。乱流や高 Ra の対流は本モデルでは扱えない。"},{"x":"**「運動エネルギーと熱の収支は同じ収支」** — 誤り。運動エネルギーは圧力投影の整合性を調べる診断であり、顕熱の収支とは別である（項目9）。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed. 第8章「Natural convection in single-phase fluids and during film condensation」。浮力駆動流れの基礎は §8.2（自然対流の性質）、Ra の定義と鉛直等温面の層流自然対流は §8.3、没入物体まわり等の他の状況は §8.4。物性値は付録 A.6。"},{"x":"正直な明記：閉キャビティ内の自然対流を専ら扱う独立の節は本書にはない。本モデルの照合基準は教科書の相関ではなく、de Vahl Davis (1983) の数値ベンチマークである（項目16）。"},{"x":"アプリ内：画面の「理論・物性・適用範囲」が物性と適用範囲の正である。用語パネルや学習コースへの接続は未完了である（`docs/dynamic/CFD_DEVELOPMENT_UI.md` の未完了項目）。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第6.1節）に基づく。記載した ID はすべて問題バンク `data/questions.json` の実在 ID であり、アプリの演習（`../index.html#quiz`）でそのまま検索できる。"},{"t":"p","x":"**現行の問題バンク（751問）に、本モデル（密閉キャビティ内部の自然対流）に直接対応する問題はない。** 「キャビティ」「閉空間」「密閉（容器）」で棚卸ししても該当は 0 件であり、バンクの自然対流問題は外部自然対流と膜状凝縮が中心である。"},{"t":"p","x":"対応表では、次の 12 件が本節に主掲載されている。これらは本モデルの前提（Ra の定義と尺度、Boussinesq 近似）そのものに対応する基礎問題であり、いずれも外部自然対流の文脈で書かれているため、キャビティ固有の問題として断定はしない。"},{"t":"ul","items":[{"x":"`supp-chapter-ch8-ra` — Ra=gβ|ΔT|L³/(να) の計算。"},{"x":"`supp-chapter-ch8-length` — 代表長さを2倍にしたときの Ra の変化（Ra∝L³）。"},{"x":"`supp-chapter-ch8-gr-pr` — Gr と Pr から Ra=Gr・Pr を求める。"},{"x":"`supp-section-8-2` — Gr が温度差のほかに依存する長さの因子（第8.2節の学習ノート）。"},{"x":"`supp-section-8-3` — L を2倍にしたときの Ra の比例変化（第8.3節の学習ノート）。"},{"x":"`supp-advanced-ch8-calc` — L と ΔT をともに2倍にしたときの Ra の変化。"},{"x":"`supp-applied-8-3-v1` — 物性値を与えた自然対流の Ra の計算。"},{"x":"`supp-natural-rayleigh-v1` — 一定物性の仮想流体での Ra の計算。"},{"x":"`supp-buoyancy-film-rayleigh-from-gr-v1` — Gr_L と Pr から Ra_L を求める。"},{"x":"`supp-buoyancy-film-vertical-ra-v1` — 垂直面の自然対流における Ra_L。"},{"x":"`supp-buoyancy-film-boussinesq-check-v1` — 密度変化を浮力だけに残す Boussinesq 近似の適用判断。"},{"x":"`supp-buoyancy-film-zero-gravity-limit-v1` — g→0 の極限における浮力自然対流モデルの解釈。"}]},{"t":"p","x":"なお本画面（開発専用画面）からアプリの演習への導線はない。"}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"de Vahl Davis, G. (1983). \"Natural convection of air in a square cavity: A bench mark numerical solution.\" International Journal for Numerical Methods in Fluids, 3, 249–264.（Table V の定義別 Nu と最大速度、\"WHICH NUSSELT NUMBER?\" pp. 262–263 の代表値の議論。項目10の照合の一次資料）"},{"x":"de Vahl Davis, G. & Jones, I. P. (1983). ベンチマーク比較 exercise の取りまとめ（フェイリス側ベンチマークパック `benchmarks-cfd.md` の記録による）。"},{"x":"Allen, T. & Reis, A. H. OCCAM Preprint 13/34, Table 7、および Barakos, G. & Mitsoulis, E. (1994), Table III。定義照合の相互確認先（`docs/dynamic/DE_VAHL_DEFINITIONS_20261106.md`）。"},{"x":"Lienhard, J. H. IV & Lienhard, J. H. V. A Heat Transfer Textbook, 6th ed., Phlogiston Press. 第8章、付録 A.6（300 K の空気の物性）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/CFD_DEVELOPMENT.md`（数値法と検証方針）、`docs/dynamic/CFD_FINE_NATURAL_SUMMARY_20261106.json`（格子系列の再集計）、`docs/dynamic/MANUFACTURED_VERIFICATION.md`（製造解検証）、`docs/dynamic/DE_VAHL_DEFINITIONS_20261106.md`（Nu 定義の確定）、`docs/dynamic/CAVITY_UI_CHECKPOINT_20261105.json`（ブラウザー確認の範囲と未検証項目）。"},{"x":"リポジトリ外の検証記録（フェイリス検証ライン）：`~/workspace/dev/heat-sim-benchmarks/natural-convection-independent-solver-20261107.md`、`~/workspace/dev/heat-sim-benchmarks/natural-convection-cases-20261107.md`、`~/workspace/dev/heat-sim-benchmarks/benchmarks-cfd.md`。"}]}]}]},{"id":"radiation-network","name":"複数面の放射ネットワーク","source":"docs/dynamic/RADIATION_MANUAL_NETWORK_20261107.md","screen":{"href":"radiation.html","label":"複数面の動的放射の画面"},"lead":[{"label":"対象モデル","x":"数値核 `dynamic/radiation-network.mjs` と学習モデル `dynamic/radiation-learning.mjs`。画面は `dynamic/radiation.html`（複数面の動的放射実験）。数値核の詳細は `docs/dynamic/RADIATION_NETWORK.md`、学習モデルの詳細は `docs/dynamic/RADIATION_LEARNING.md`。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"閉じた囲い（閉鎖系）の中にある 2〜12 個の面が、放射だけで熱をやり取りしながら温度を変えていく現象を計算する。各面は温度が一様（等温）で、面同士の見え方は形態係数 F の行列で与える。形態係数は入力であり、このモデルは形状から F を計算しない（形状から F を計算するモデルは「長い凸ダクト放射」の説明書を参照）。画面には、同じ数値核を使う学習コース（等面積2面の予想実験）も含まれる。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"炉の内壁同士が放射で熱を移し合い、壁温が均されていく様子の見積り。"},{"x":"宇宙機のパネルや電子機器の筐体内部で、部品面同士が放射交換する学習・概算。"},{"x":"建物の室内で、壁・床・天井の面同士が放射で影響し合う感覚の確認。"},{"x":"2つの面の間で、熱容量の違いが最終温度をどう決めるか（項目13）の確認。"}]},{"t":"p","x":"いずれも等温・拡散灰色・閉鎖系の仮定が成り立つ範囲の学習・概算のためであり、実設計の保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"教科書第10章（§10.3 黒体間の交換、§10.4 灰色体間の熱伝達）の放射収支を、面ごとにそのまま連立させる（出典：`docs/dynamic/RADIATION_NETWORK.md`、アプリ内 #manual「法則・単位・計算」）。"},{"t":"ul","items":[{"x":"照射量：Gᵢ = Σⱼ Fᵢⱼ Jⱼ"},{"x":"射度：Jᵢ = εᵢσTᵢ⁴ + (1−εᵢ)Gᵢ（自己放出と反射の和）"},{"x":"正味出力：Qᵢ = Aᵢ Σⱼ Fᵢⱼ (Jᵢ − Jⱼ) = Aᵢ (Jᵢ − Gᵢ)（正は面からの正味流出）"},{"x":"温度発展：Cᵢ dTᵢ/dt = Pᵢ − Qᵢ"}]},{"t":"p","x":"閉鎖系では相反関係 AᵢFᵢⱼ = AⱼFⱼᵢ により面間の交換が相殺し、全 Q の和は 0 になる。"}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["Tᵢ","面 i の絶対温度（入力・表示の ℃ は 273.15 を加えて換算）","K"],["εᵢ","放射率（0〜1）","—"],["Aᵢ","面積","m²"],["Cᵢ","熱容量（一定）","J/K"],["Pᵢ","一定の外部入力（正は加熱、負は冷却）","W"],["Fᵢⱼ","形態係数：面 i から出た拡散放射が面 j へ届く割合（0〜1）","—"],["Jᵢ, Gᵢ","射度、照射量","W/m²"],["Qᵢ","正味放射出力（外向き正）","W"],["σ","ステファン・ボルツマン定数 5.670374419×10⁻⁸","W/(m²·K⁴)"],["T_max","監視上限温度（既定 2000 K）。物性が有効な温度という意味ではない","K"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"面ごとに正の絶対温度を与え、監視上限 T_max を超える初期温度は受理されない。外部入力 Pᵢ は時間に対して一定である。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"p","x":"このモデル自体が閉鎖系の収支であり、外部との境界は「閉じている」ことそのものである。各行の総和 ΣⱼFᵢⱼ = 1（開口なし）を要求し、開口・外部への放射漏れは扱わない。外部とのエネルギーの出入りは外部入力 Pᵢ（W、一定）のみ。対流・伝導との連成はこのモデルにはない（単一面の連成は「表面交換」の説明書、一般連成は未実装。項目12）。"}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"射度の線形連立方程式は、同温度近傍の桁落ちを避けるため、共通の黒体射出能 σT₁⁴ からの偏差の形で解く。T⁴ の差は (a−b)(a+b)(a²+b²) と因数分解して評価する。解法は行スケーリングつき部分ピボット選択の消去法で、残差が許容範囲（右辺ノルム比 1e-10）を超えれば受理しない（出典：`dynamic/radiation-network.mjs`）。"},{"x":"時間積分は Heun 法（2次）。刻みの上限は safeDt = 0.2 × minᵢ [Cᵢ / (4σAᵢT_max³)] で、予測・修正の両状態が正の絶対温度と監視上限を満たすことを確認してから状態を確定する（失敗時は状態を変更しない原子性）。"},{"x":"入力検証：F は 0〜1、各行の総和 1 との差 1e-12 以内、相反関係 AᵢFᵢⱼ = AⱼFⱼᵢ の相対差 1e-12 以内を要求し、違反は拒否する。閉じた完全反射面だけの独立部分系は射度が定まらないため、初期化時点で拒否する。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"プリセット（内面を外面が完全に包む2面／等面積の2面（端部を無視）／等面積の3面閉鎖系）または面数 2〜12 の再構成から始め、面ごとの温度・ε・A・C・P と F 行列を入力する。"},{"x":"「条件を適用して最初から」で初期化し、再生／1コマ／巻き戻し（最大500コマの履歴）で応答を確認する。比較は最大2条件（A/B）。"}]},{"t":"p","x":"手計算による検算の例（出典：アプリ内 #manual「手計算・検算」、`docs/dynamic/RADIATION_BENCHMARKS_20261104.json`）："},{"t":"ul","items":[{"x":"等面積 1 m²、ε₁=0.8、ε₂=0.6、T₁=600 K、T₂=300 K なら、2面抵抗式 Q₁ = σ(600⁴−300⁴)/(1/0.8+1/0.6−1) ≈ 3594.5243 W、Q₂ = −Q₁。ベンチマーク記録の瞬間交換は 3594.5243056095646 W で、フェイリス側のスポットチェック（2026-11-07、先端 `c52f2a7`）でも数値核から 3594.524305609565 W を再現し、差は約 4.55e-13 W で記録と一致した。"},{"x":"C₁=C₂=100 J/K なら初期の dT₁/dt ≈ −35.945243 K/s（瞬間の傾き。直線外挿はしない。項目13）。"},{"x":"学習コースの専用条件（等面積1 m²、ε=0.8/0.6、C₁=200/C₂=400 J/K、初期 200℃/20℃、P=0）では、20秒後の独立参照値は面1 = 126.8639445166℃、面2 = 56.5680277417℃、その時点の正味出力は約 ±407.819 W（出典：`docs/dynamic/RADIATION_LEARNING.md`、独立参照は SciPy DOP853）。"}]}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"画面の図は接続の模式配置である。線の本数・面の位置・円の大きさは、エネルギー量・距離・面積を表さない（アプリ内 #manual と図の注記に明記）。数値は表の J・G・Q を正とする。"},{"x":"矢印は面間の AᵢFᵢⱼ(Jᵢ−Jⱼ) の符号と W の注記で読む。4面以上では注目面につながる矢印だけを表示する。"},{"x":"温度履歴グラフは実験Aが実線、比較Bが破線。時間バーや「戻る」操作は保存した前進解の再生であり、逆向きの放射計算ではない。"},{"x":"Q が正ならその面から正味流出、負なら正味流入。診断には射度残差、放射出力の総和、外部入力と顕熱の収支が表示される。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"ul","items":[{"x":"外部入力 0 の閉鎖系では全体の顕熱 ΣCᵢ(Tᵢ−273.15) が保存し、最終温度は容量平均 ΣCᵢTᵢ(0)/ΣCᵢ に近づく。収支誤差（フェイリス側スポットチェックでは50コマ進行後も 7.3e-12 J）と温度の離散化誤差は別の量であり、混同しない。"},{"x":"検証の実測（出典：`docs/dynamic/RADIATION_NETWORK.md`、`docs/dynamic/RADIATION_BENCHMARKS_20261104.json`）：別実装の2面抵抗式 RK4 解との比較で、時間誤差の観測次数は約 2.00（内部刻み 0.04/0.02/0.01 s で温度誤差 約 0.00066374/0.00016540/0.00004129 K）。これは滑らかな2面例での次数であり、任意の行列・物性の万能精度を証明しない。"},{"x":"正本 §10.4 の検証リスト9項目（絶対温度の扱い、放射率の範囲、形態係数、相反関係、総和則、正味放射交換、エネルギー保存、温度差ゼロ条件、複数面の放射収支）は、実装済みモデルの範囲で全て実施済みである（出典：締め可能性監査 §5）。放射関連テストはフェイリス側検証記録 `radiation-closure-verification-20261107.md` 項目10で再計測され全件成功し、本パッケージでも先端 `c52f2a7` の全 Node スイート（1501件＝1496成功／0失敗／5スキップ）で回帰がないことを確認した。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"各面は不透明・拡散灰色・等温。放射率・熱容量・外部入力は一定。"},{"x":"媒質は非参加（放射を吸収・散乱しない）。閉鎖系で開口はない。"},{"x":"形態係数は与えられるものであり、幾何から計算しない。プリセットと面数変更で作る F は理想閉鎖系の数学的な例である。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"入力 F が総和則・相反関係を満たしても、任意の実形状が存在する証明にはならない。実形状への適用は別途照合が必要（アプリ内 #manual「仮定・形態係数」にも明記）。"},{"x":"鏡面反射、波長依存性（非灰色）、気体放射（教科書 §10.5）は対象外で未実装。"},{"x":"面の位置関係から F を作る仕組みはこの画面にはない（幾何計算は長い凸ダクトのみ。監査の残作業 #2）。"},{"x":"伝導・対流との双方向の一般連成は未実装（監査の残作業 #4）。単一面の連成は表面交換モデルが担う。"},{"x":"内部温度分布は解かない。等温近似は内部熱抵抗が十分小さい場合などに限る。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「放射で近づく温度は単純平均になる」** — 誤り。外部入力 0 の閉鎖系の最終温度は熱容量で重み付けした容量平均である。学習コースの例（200℃・200 J/K と 20℃・400 J/K）では単純平均 110℃ ではなく 80℃ へ近づく。"},{"x":"**「低温の面は放射を出していない」** — 誤り。低温面も自己放出しており、矢印と Q は正味の交換を示す。"},{"x":"**「矢印の向きは温度の高低だけで決まる」** — 誤り。射度 J には反射が含まれるため、各線の向きは温度だけでは決まらない。"},{"x":"**「模式図の面を動かせば F が求まる」** — 誤り。図は接続の模式配置であり、F は入力値である。"},{"x":"**「初期の温度変化の傾きで長時間を外挿できる」** — 誤り。傾きは瞬間の値で、T⁴ の非線形により変化する。"},{"x":"**「完全反射面（ε=0）は温度が変わらない面として自由に置ける」** — 誤り。ε=0 の面自体は放射で温度を変えないが、閉じた完全反射面だけの部分系は射度が定まらず拒否される。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、第10章（§10.1 放射交換の問題設定、§10.3 黒体間の放射交換、§10.4 灰色体間の熱伝達）。"},{"x":"アプリ内：画面の #manual「使い方と理論」から、既存の静的モデル「2面放射の詳しい式」と用語集へリンク済み。用語パネルは定義・式・単位・関連語を表示する（`docs/dynamic/RADIATION_NETWORK.md`）。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第7.1節）に基づく。記載した ID はすべて問題バンク `data/questions.json` の実在 ID であり、アプリの演習（`../index.html#quiz`）でそのまま検索できる。主掲載は次の 21 件（全件）で、形態係数（相反則・総和則・自己形態係数）、射度 J、表面抵抗・空間抵抗の節点モデルを扱う。"},{"t":"ul","items":[{"x":"`supp-chapter-ch10-reciprocity` — 相反則 A₁F₁₂=A₂F₂₁ から F₂₁ を求める。"},{"x":"`supp-chapter-ch10-enclosure` — 閉じた囲いで総和則から未知の形態係数を求める。"},{"x":"`supp-chapter-ch10-concept` — 閉じた凹面の自己形態係数 F_ii の性質。"},{"x":"`supp-section-10-3` — 面積の違う二面の間で常に成り立つ関係（第10.3節の学習ノート）。"},{"x":"`supp-section-10-4` — 射度 J と照射量 G から面の正味放射流束を求める（第10.4節の学習ノート）。"},{"x":"`supp-applied-10-3-v1` — 相反則から F₂₁ を求める計算。"},{"x":"`supp-applied-10-4-v1` — J=εE_b+(1−ε)G の計算。"},{"x":"`supp-batch2-view-reciprocity-v1` — 相反則による形態係数の計算。"},{"x":"`supp-batch2-blackbody-two-surfaces-v1` — 二つの黒体面の間の正味放射交換。"},{"x":"`supp-batch2-reverse-f12-v1` — 相反則を逆向きに解いて F₁₂ を求める。"},{"x":"`supp-batch2-closed-view-sum-v1` — 閉じた三面囲いの総和則。"},{"x":"`supp-batch2-convex-self-factor-v1` — 凸面の自己形態係数が0であること。"},{"x":"`supp-batch2-grey-surface-limit-v1` — 灰色面に黒体間の交換式をそのまま使えないこと。"},{"x":"`supp-deep-rad-radiosity-v1` — 照射量を受ける灰色面の射度 J。"},{"x":"`supp-deep-rad-totalpower-v1` — 大きな黒体囲いに囲まれた灰色面の全放射熱流。"},{"x":"`supp-gray-parallel-flux-v1` — 互いだけを見込む大きな平行灰色面の間の放射流束。"},{"x":"`supp-gray-two-surface-resistance-v1` — 二面だけの閉じた拡散灰色囲いの節点モデル（最も直接の対応）。"},{"x":"`supp-gray-one-shield-v1` — 平行面の間に置いた放射遮蔽板の効果。"},{"x":"`supp-gray-resistance-driving-potential-v1` — 射度を使う放射抵抗ネットワークで表面抵抗の両端に対応する量。"},{"x":"`supp-gray-open-plates-environment-v1` — 室内に置いた有限な二枚の板に対する、二面だけの閉囲いの式の限界。"},{"x":"`supp-radiation-net-incoming-sign-v1` — q″=J−G と定義したときの正味流束の符号。"}]}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（第10章、Appendix A）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/RADIATION_NETWORK.md`、`docs/dynamic/RADIATION_BENCHMARKS_20261104.json`（独立 RK4 照合）、`scripts/dynamic-radiation-benchmarks.mjs`、`docs/dynamic/RADIATION_LEARNING.md` と `docs/dynamic/RADIATION_LEARNING_REFERENCE_20261105.json`（SciPy DOP853 独立 ODE）、フェイリス側検証記録 `radiation-closure-verification-20261107.md`（熱放射分野 締め検証記録、項目10の先端再計測）。"}]}]}]},{"id":"radiation-long-duct","name":"長ダクト放射（自由頂点）","source":"docs/dynamic/RADIATION_MANUAL_LONG_DUCT_20261107.md","screen":null,"lead":[{"label":"対象モデル","x":"数値核 `dynamic/dev/long-duct-radiation.mjs`（`createLongDuctViewFactors`／`createLongDuctRadiation`）。本線の開発専用画面は `dynamic/dev/long-duct.html`、自由頂点編集 UI は統合ツリーの `dynamic/dev/long-duct-ui.mjs` に実装済み（開発画面のみ）。数値核の詳細は `docs/dynamic/LONG_DUCT_RADIATION_DEVELOPMENT.md`、本線画面は `docs/dynamic/LONG_DUCT_UI_DEVELOPMENT.md`、頂点編集は同ブランチの `docs/dynamic/LONG_DUCT_VERTEX_UI_20261107.md`。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"軸方向に無限に長い凸多角形ダクトの断面で、壁同士が放射だけで熱をやり取りする現象を計算する。放射ネットワークモデルとの違いは、形態係数 F を入力ではなく実際の断面形状（3〜12頂点の輪郭）から幾何計算する点である。各壁は等温で、軸方向 1 m あたりの熱容量を持ち、温度が時間発展する。熱の出入りは断面内の放射のみで、端面は存在しない。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"長い炉内流路やダクトの断面で、壁面同士の放射交換を見積もる学習・概算。"},{"x":"正方形・矩形・正多角形など、形態係数の既知値がある断面での形態係数の学習と検算。"},{"x":"断面形状を変えたとき（例：矩形のアスペクト比）に、対向壁の見え方がどう変わるかの確認。"}]},{"t":"p","x":"いずれも無限長・厳密凸・等温壁の仮定が成り立つ範囲に限る（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"ul","items":[{"x":"形態係数：2次元閉鎖系の交差弦法による。共有の交換長 Gᵢⱼ = LᵢFᵢⱼ = LⱼFⱼᵢ [m] を、交差する弦と交差しない弦の長さの差から一度だけ求める：LᵢFᵢⱼ =（交差弦の和 − 非交差弦の和）/ 2。平面壁の自己形態係数は 0（出典：`docs/dynamic/LONG_DUCT_RADIATION_DEVELOPMENT.md`、教科書 §10.3 の交差弦法の条件は Problem 10.14／§10.3 を参照）。"},{"x":"放射収支と温度発展：放射ネットワークと同じ式を使う。Gᵢ = ΣⱼFᵢⱼJⱼ、Jᵢ = εᵢσTᵢ⁴ + (1−εᵢ)Gᵢ、Qᵢ = AᵢΣⱼFᵢⱼ(Jᵢ−Jⱼ)、Cᵢ dTᵢ/dt = Pᵢ − Qᵢ。ここで Aᵢ = Lᵢ × span、Cᵢ = C′ᵢ × span、Pᵢ = P′ᵢ × span と換算する。"}]}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["(x, y)","断面の頂点座標（3〜12頂点、厳密凸）","m"],["Lᵢ","壁 i の辺長","m"],["span","軸方向の熱量換算長。端面を追加する物理的な長さではない","m"],["Aᵢ = Lᵢ × span","壁 i の面積","m²"],["C′ᵢ","軸方向 1 m あたりの熱容量（断面辺長さあたりではない）","J/(m·K)"],["P′ᵢ","軸方向 1 m あたりの外部入力","W/m"],["Qᵢ / span","軸方向 1 m あたりの正味放射出力","W/m"],["Fᵢⱼ, Gᵢⱼ = LᵢFᵢⱼ","形態係数、相反交換長","—, m"],["εᵢ, Tᵢ, σ","放射率、絶対温度、ステファン・ボルツマン定数 5.670374419×10⁻⁸ W/(m²·K⁴)","—, K, W/(m²·K⁴)"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"壁ごとに初期絶対温度を与える。復元（巻き戻し）では、時刻 0 の温度は初期値と一致することが核側で要求され、一致しない復元データは拒否される。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"p","x":"断面は閉じた輪郭であり、各辺が 1 つの壁（等温面）になる。軸方向の端面はモデルに存在しない（無限長）。開口、障害物、外部への漏れは扱わない。壁以外の境界条件（対流・伝導との連成）はこのモデルにはない。"}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"形態係数：座標を原点移動と長さスケールで正規化し、弦長の差は平方差の因数分解で評価して桁落ちを避ける。隣接壁では三角形の Lᵢ+Lⱼ−対角線 を有理化し、小さい曲がり角は sin²/(1+cos) を使う（出典：`docs/dynamic/LONG_DUCT_RADIATION_DEVELOPMENT.md`、`dynamic/dev/long-duct-radiation.mjs`）。"},{"x":"受理条件：総和則と面積相反則の残差 1e-12 以内を要求する。F を切り取ったり行和で正規化したりして誤差を隠すことはしない。非有限・ゼロ辺・重複・一直線・凹・自己交差・弦長差から正の形態係数を解像できない形状は拒否する。同じ閉終点の除去だけが自動で行われ、その旨が記録される。"},{"x":"温度発展：放射ネットワーク核（`createRadiationNetwork`）の Heun 法と刻み上限をそのまま使う。無効な刻み・非有限な出力・復元失敗時は旧状態へ戻す（原子性）。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"断面を選ぶ。本線画面ではプリセット（正三角形／矩形／正六角形）と全幅・全高さの指定のみ。フェイリス側ブランチの画面では頂点のドラッグ・数値入力・追加・削除（3〜12個）による自由編集が可能で、編集のたびに核の検証を通し、不正な形状は理由を表示して受理しない。"},{"x":"壁1と他壁の初期温度・放射率、全壁共通の面積あたり熱容量を指定して初期化し、再生／巻き戻し／A・B比較で応答を確認する。"}]},{"t":"p","x":"形態係数の検算値（出典：`docs/dynamic/LONG_DUCT_RADIATION_REFERENCE_20261106.json` の照合形状と解析値。フェイリス側スポットチェック 2026-11-07、先端 `c52f2a7` で全て再現）："},{"t":"ul","items":[{"x":"正方形 1×1：対向壁 F = √2−1 = 0.41421356…、隣接壁 F = 1−1/√2 = 0.29289321…"},{"x":"矩形 2×1：長壁の対向 F = (√5−1)/2 = 0.61803398…、短壁の対向 F = √5−2 = 0.23606797…"},{"x":"正五角形：隣接 F = (3−√5)/4 = 0.19098300…、第二隣接 F = (√5−1)/4 = 0.30901699…"},{"x":"正三角形：全ペア F = 0.5"}]},{"t":"p","x":"例題 10.9 の扱い（出典：`docs/dynamic/EXAMPLE_10_9_DISPOSITION_20261106.md`）：教科書の印刷値 Q = 46.53 W/m は、教科書自身の丸めた節点式の算術と一致しない（丸めない条件での式評価は 46.62819046 W/m）。本モデルの瞬間値は式評価に一致する。印刷値を式のオラクルにしないこと（項目13）。"}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"本線画面の図は実際の断面頂点を縦横同じ px/m で配置する（放射ネットワーク画面の模式配置とは異なる）。各辺に解いた実壁温度・番号・℃ を表示する。"},{"x":"矢印は選択壁との正味交換 Qᵢⱼ の符号から方向を決める模式表現であり、光線の軌跡や本数ではない。反射を含むため温度差だけから方向は決まらない。"},{"x":"描画上の省略：丸め差水準の矢印（128 EPS × 選択壁の最大 |Qᵢⱼ| 以下）は図だけ省略し、省略数と閾値を診断に表示する。元の熱流の数値は変更されず、微小な非ゼロ値は指数表記で残る（出典：`docs/dynamic/LONG_DUCT_UI_DEVELOPMENT.md`）。"},{"x":"画面の線幅は壁厚ではない。全 F 行列、総和／相反残差、顕熱／外部入力／収支差、射度残差が数値で表示される。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"ul","items":[{"x":"検証の実測（出典：`docs/dynamic/LONG_DUCT_RADIATION_DEVELOPMENT.md`）：5形状（正方形、1×2.4 矩形、正三角形、正五角形／八角形）を 80桁 mpmath の弦式へ照合し、独立な放射角度核の線積分とも最大差 約 2.44e-15 で一致。等しい ε=0.8 の正三角形の冷却を1変数 ODE（DOP853）へ縮約して照合し、時間誤差の観測次数は 約 2.01/2.00。"},{"x":"総和／相反の残差表示は形状の解像度の指標であり、残差が小さいこと自体は一般形状の誤差証明ではない（受理条件は項目7）。"},{"x":"span を変えても温度応答は同じで、容量・入力・蓄熱だけが比例する。W/m の値は span=1 m 換算の値として読む。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"軸方向に無限長で、断面形状は一様。端面の効果はない。"},{"x":"断面は厳密な凸多角形（3〜12辺）。全壁が見通せるため遮蔽の判定を省略できる範囲である。"},{"x":"各壁は等温・灰色・拡散・不透明。内部の媒質は非参加。"},{"x":"壁内伝導・壁の厚み方向の温度分布は解かない（集中熱容量近似）。"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"凹形状・障害物による遮蔽、有限長・端面、一般 3D は対象外（監査の残作業 #1）。"},{"x":"自由頂点編集は統合ツリーの開発画面に実装済み（公開ビルドには含まれない）。"},{"x":"開発専用であり、公開ビルドには含まれない。開発画面のオフライン確認と公開候補への登録判断は未完了（監査の残作業 #7）。"},{"x":"気体の放射吸収（参加媒体）、自然対流との連成は解かない。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「span はダクトの実際の長さで、端面も計算される」** — 誤り。span は熱量換算のためだけの量で、有限長の端面は追加されない。"},{"x":"**「形態係数の行和が 1 にならない形状は自動で補正される」** — 誤り。正規化も切り取りもしない。解像できない形状は拒否される。"},{"x":"**「例題 10.9 の印刷値と合わないのはソルバーの誤り」** — 誤り。印刷値側に算術の不一致があり、式評価（46.62819046 W/m）が照合の基準である（項目8）。"},{"x":"**「壁の温度が一様に描かれるのは計算結果」** — 誤り。一様性は集中熱容量の仮定そのものである。"},{"x":"**「矢印は光線の経路」** — 誤り。射度差による正味交換の模式表現である。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、第10章（§10.3 黒体間の放射交換と交差弦法、Table 10.2 配置1、例題 10.9、§10.4 灰色体間の熱伝達）。"},{"x":"開発専用モデルのため、公開画面からの導線はない。関連する検証資料は項目16の開発文書群である。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第7.2節・第8節）に基づく。"},{"t":"ul","items":[{"x":"教科書側では Problem 10.14／§10.3 が交差弦法の条件の参照として開発文書に記録されている。"},{"x":"**現行の問題バンク（751問）に、本モデル（長ダクトの形態係数）に直接対応する問題はない。** ダクトの放射文脈や交差弦（crossed-string）法を扱う問題は 0 件である。推測で埋めず、その事実をここに明記する。"}]},{"t":"p","x":"最も近いのは、形態係数の基礎を扱う次の問題である（いずれも主掲載は放射ネットワークの説明書の項目15）。"},{"t":"ul","items":[{"x":"`supp-chapter-ch10-reciprocity` — 相反則 A₁F₁₂=A₂F₂₁。"},{"x":"`supp-chapter-ch10-enclosure` — 閉じた囲いの総和則。"},{"x":"`supp-batch2-closed-view-sum-v1` — 閉じた三面囲いの総和則。"},{"x":"`supp-batch2-convex-self-factor-v1` — 凸面の自己形態係数が0であること。"}]}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（第10章）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/LONG_DUCT_RADIATION_DEVELOPMENT.md`、`scripts/dynamic-long-duct-reference.py` と `docs/dynamic/LONG_DUCT_RADIATION_REFERENCE_20261106.json`（80桁 mpmath 弦式と独立角度核積分）、`docs/dynamic/EXAMPLE_10_9_DISPOSITION_20261106.md`（例題 10.9 の印刷値と式評価の切り分け）、`docs/dynamic/LONG_DUCT_UI_DEVELOPMENT.md`、`docs/dynamic/LONG_DUCT_VERTEX_UI_20261107.md`（フェイリス側ブランチ `feiris/longduct-vertex-ui`）。"}]}]}]},{"id":"radiation-surface-exchange","name":"表面の対流＋放射 交換","source":"docs/dynamic/RADIATION_MANUAL_SURFACE_EXCHANGE_20261107.md","screen":{"href":null,"label":"この画面と径方向画面の境界条件"},"lead":[{"label":"対象モデル","x":"共有カーネル `dynamic/surface-exchange.mjs`（`surfaceExchange`）。接続先は矩形 FVM `dynamic/thermal.mjs` と径方向モデル `dynamic/radial.mjs` で、画面は伝導画面 `dynamic/index.html` と径方向画面 `dynamic/radial.html` の境界条件「対流＋放射」。基盤の詳細は `docs/dynamic/SURFACE_EXCHANGE.md`。"},{"label":"読み分け","x":"項目1〜2・9〜10・13 は初心者向け、それ以外は専門寄りの記述を含む。"}],"items":[{"n":1,"title":"現象の概要","blocks":[{"t":"p","x":"固体の 1 つの表面が、流体への対流と大きな黒い周囲への放射を同時に行う境界を計算する。対流と放射は別々の表面温度で評価して足すのではなく、共通の表面温度 Ts を 1 つ解いて両方を同時に満たす。流体温度 T∞ と放射周囲温度 Tr は別の値として与えるため、対流では加熱されながら放射では冷える、という同時発生も起こる。流体側や囲いの形態係数は解かない。"}]},{"n":2,"title":"現実世界での使用例","blocks":[{"t":"ul","items":[{"x":"空気中で冷える板・球・円柱の表面温度と放熱量の見積り（対流だけ／放射だけでは足りない温度域の確認）。"},{"x":"電子機器の筐体や配管の表面が、自然対流と放射のどちらで主に冷えるかの内訳確認。"},{"x":"高温面で放射の寄与（Ts⁴）が対流に匹敵する条件の学習。"}]},{"t":"p","x":"いずれも周囲が「大きな黒い囲い」とみなせる範囲の学習・概算のためであり、実設計の保証には使わない（項目12）。"}]},{"n":3,"title":"支配方程式","blocks":[{"t":"p","x":"表面には熱容量も熱源も置かず、表面収支が各瞬間に釣り合う（出典：`docs/dynamic/SURFACE_EXCHANGE.md`）。"},{"t":"p","x":"G (Tc − Ts) = hA (Ts − T∞) + εσA (Ts⁴ − Tr⁴)"},{"t":"ul","items":[{"x":"左辺はセル中心温度 Tc から表面までの半セル伝導（コンダクタンス G。矩形 FVM では G = 2kA/dist、径方向では半セルの勾配抵抗 Δr/(2kA) を含む形）。"},{"x":"物体への流入は G (Ts − Tc)。対流と放射をセル温度へ別々に掛けて単純加算しない。"},{"x":"宿主側の支配方程式は各宿主のもの（熱伝導方程式は教科書 §2.1、過渡応答は第5章）。放射収支の考え方は教科書 §10.4（灰色体間の熱伝達）に基づく。"}]}]},{"n":4,"title":"記号と単位","blocks":[{"t":"table","head":["記号","意味","単位"],"rows":[["Tc","表面に接するセルの中心温度（絶対温度）","K"],["Ts","共通表面温度（解く量）","K"],["G","セル中心から表面までの伝導コンダクタンス","W/K"],["A","表面積","m²"],["h","熱伝達率（入力値。流れから予測しない）","W/(m²·K)"],["ε","放射率（0〜1）","—"],["T∞","流体温度（絶対温度）","K"],["Tr","大きな黒い放射周囲の温度（絶対温度。T∞ とは独立）","K"],["σ","ステファン・ボルツマン定数 5.670374419×10⁻⁸","W/(m²·K⁴)"]]}]},{"n":5,"title":"初期条件","blocks":[{"t":"p","x":"カーネル自体は状態を持たない（Tc を与えるたびに Ts と各熱流を返す）。初期条件は宿主モデル側の初期温度場であり、初期化の時点でも面収支の診断が行われる（過大な h などは初期化時に拒否される。出典：`docs/dynamic/SURFACE_EXCHANGE.md`）。"}]},{"n":6,"title":"境界条件","blocks":[{"t":"p","x":"このモデル自体が宿主の境界条件（型 `convection-radiation`）である。"},{"t":"ul","items":[{"x":"流体温度と放射周囲温度は独立した入力（画面では流体は主たる境界温度、放射周囲は独立した ℃ 入力から K へ変換）。"},{"x":"特別な場合：h=0 は放射のみ、ε=0 は対流のみ、h=ε=0 は断熱に戻る。"},{"x":"拒否される組合せ（項目12）：自由輪郭の面、温度依存物性 k(T)/cp(T) との同時使用、フィン選択中の同時境界（分布対流へ放射を足す機能ではないため）。"}]}]},{"n":7,"title":"数値計算法","blocks":[{"t":"ul","items":[{"x":"未知量は絶対温度 Ts ではなく偏差 δ = Ts − Tc とする。G が非常に大きい場合、物理的な δ が絶対温度の ULP 以下でも、G×δ として熱流を保持できるためである（丸めて Ts=Tc になったことだけを根拠に熱流 0 と扱わない）。"},{"x":"解法は保護つき Newton 法（残差の微分は −G − hA − 4εσATs³ < 0 で単調）。Newton 更新が正の温度の括り区間を出れば二分法に戻す。4乗差は εσA (Ts−Tr)(Ts+Tr)(Ts²+Tr²) と因数分解して近接温度の桁落ちを避ける（出典：`dynamic/surface-exchange.mjs`、`docs/dynamic/SURFACE_EXCHANGE.md`）。"},{"x":"収束条件：残差が各熱流項の最大値に対する 64 機械イプシロン以内。収束しなければエラーとして状態を更新しない。"},{"x":"宿主の陽的積分では、境界勾配の上限 |dq_in/dTc| ≤ G を従来の半セル伝導 G による刻み上限へ算入する。対流と放射の面を二つとして数えない。"}]}]},{"n":8,"title":"計算過程","blocks":[{"t":"ol","items":[{"x":"宿主モデル（板または球／円筒）で境界に「対流＋放射」を選び、流体温度・放射周囲温度・h・ε を指定する。"},{"x":"各面の表面温度と対流／放射の内訳、合計の流入が診断に表示される（板は面ごとの集計と表面温度の最小／最大、球／円筒は外面の値）。"}]},{"t":"p","x":"検算の例："},{"t":"ul","items":[{"x":"カーネル単体（フェイリス側スポットチェック、2026-11-07、先端 `c52f2a7`）：Tc=500 K、G=100 W/K、A=1 m²、h=20 W/(m²·K)、T∞=300 K、ε=0.8、Tr=350 K に対して、JS カーネルは Ts = 455.99527258993413 K、流入 −4400.47 W（正味流出）、対流の外向き 3119.91 W、放射の外向き 1280.57 W を返し、独立な Python brentq 解と表面温度が全桁一致した。h=ε=0 では流入 0（断熱）に戻ることも確認した。"},{"x":"平板の定常（出典：`docs/dynamic/SURFACE_EXCHANGE.md`、`docs/dynamic/SURFACE_EXCHANGE_REFERENCE_20261105.json`）：左面 600 K、k=5 W/(m·K)、L=0.1 m、h=20、流体 300 K、放射周囲 350 K、ε=0.8 の定常表面温度は Ts = 487.4297292963 K。線形な連続定常解の体積平均との比較で、前進後の温度ドリフト < 1e-10 K、全表示熱流束の誤差 < 1e-8 W/m² を要求している。"}]}]},{"n":9,"title":"グラフの読み方","blocks":[{"t":"ul","items":[{"x":"画面表示は宿主側の温度場・断面表示に従う。本モデルの固有の読み取りは診断欄である：対流・放射の各寄与は外向き正、合計は物体への流入正と明記される。符号の向きを取り違えないこと。"},{"x":"瞬間出力 [W] と累積入力 [J] は別の量であり、混同しない。"},{"x":"表面温度 Ts はセル中心温度 Tc とは別に表示される（板では最小／最大、径方向では外面の値）。Ts と Tc の差が半セル伝導の効き具合を示す。"}]}]},{"n":10,"title":"結果の解釈","blocks":[{"t":"ul","items":[{"x":"検証の実測（出典：`docs/dynamic/SURFACE_EXCHANGE.md`）：独立参照（Python/SciPy、絶対表面温度への Brent 法）との照合で、発熱する球／円筒の定常体積積分温度との RMS は 8/16/32 殻で球 0.0104005/0.00260315/0.000650978 K、円筒 0.01171875/0.00292969/0.000732422 K（約2次）。時間積分だけの検査（1制御体積の ODE を DOP853 で別積分）では、JS の前進 Euler の温度誤差は刻み 2/1/0.5/0.25 s で 0.860805/0.428490/0.213771/0.106767 K（約1次）。保存則誤差と離散化誤差を混同しない。"},{"x":"変物性との組合せの切り分け（出典：フェイリス側検証記録 `radiation-closure-verification-20261107.md` 項目5）：連成カーネルは温度依存コンダクタンスでも独立根と表面温度で最大 5.7e-14 K まで一致し、変物性を入れた有限体積の定常解は Kirchhoff 変換の厳密解（Ts = 498.4157 K、q = 6087.01 W/m²）へ空間2次（観測次数 1.99）で収束した。物理・離散化の水準で組合せに不整合は見つかっていない。一方で変物性の効きは大きく、一定物性（300 K 評価）との比較で定常表面温度に +33.6 K、全熱流束に +28.6% の差があるため、一定物性で代替できる大きさではない。"}]}]},{"n":11,"title":"モデルの仮定","blocks":[{"t":"ul","items":[{"x":"表面は熱容量・熱源を持たず、収支は瞬時に釣り合う。"},{"x":"放射周囲は大きな黒い囲い（形態係数 1、温度 Tr 一様）。有限の囲いの形態係数は扱わない。"},{"x":"流体温度は規定値で、流体側は解かない。h は入力値。"},{"x":"表面は灰色・拡散。宿主は一定物性（同時境界を使う場合）。（2026-11-07 追記：変物性との組合せは同日受理へ移行した。下記 §12 の追記を参照。）"}]}]},{"n":12,"title":"モデルの限界","blocks":[{"t":"ul","items":[{"x":"温度依存物性 k(T)/cp(T) と同時境界の組合せは、検証待ちとして生成時点で拒否される（`dynamic/thermal.mjs` のガード。フェイリス側スポットチェックでも先端 `c52f2a7` で再確認：kTable のみ・cpTable のみ・両表とも拒否、放射のみ／対流のみとの組合せは受理）。受理に必要な残条件は、ガードを外した JS 本体での直接回帰テスト、刻み上限への放射接線勾配 4εσTs³ の影響の実測、物性表範囲と表面温度の関係の明示であり、フェイリス側検証記録に列挙されている。本書の項目10の検証は独立実装同士の比較であり、JS 実装の組合せ経路を直接実行した検証ではない。**（2026-11-07 追記：受理済み）** 上記の残条件4件は同日に全て充足し、組合せは thermal.mjs の矩形FVM（自由輪郭なし）に限り受理へ移行した。JS 本体の定常は Kirchhoff 厳密解と表面温度 2.7e-10 K 以内・熱流束相対差 2e-12 以内で一致し、刻み上限は放射接線が半セル伝導の最大 90.7 倍の条件でも dt=safeDt で安定だった。受理範囲は表面温度も物性表の範囲内にある条件に限り、範囲外では刻みが外挿拒否で停止する。直接検証の過程で snapshot 診断のコンダクタンス不整合が見つかり修正済み。詳細と実測値は SURFACE_EXCHANGE.md の「変物性との組合せの受理（2026-11-07）」と tests/dynamic-surface-exchange-variable.test.mjs を参照。"},{"x":"自由輪郭（階段輪郭）では表面積・法線の検証が未了のため拒否される。矩形の外周面と輪郭でない内縁面が対象である。"},{"x":"有限囲いとの放射交換（形態係数つき）は放射ネットワーク／長い凸ダクトの担当であり、本カーネルは周囲を黒体とみなす。"},{"x":"三角形表面系（`dynamic/dev/triangle-surface-transient.mjs`）にも対流＋放射の表面境界があるが、一定物性のみ・物性表の入力自体がない別モデルであり、本書の対象外とする。"}]}]},{"n":13,"title":"よくある誤解","blocks":[{"t":"ul","items":[{"x":"**「対流と放射は、セル温度で別々に計算して足せばよい」** — 誤り。両者は共通の表面温度 Ts を共有し、Ts は半セル伝導と釣り合うよう解かれる。単純加算とは結果が異なる。"},{"x":"**「流体温度と放射周囲温度は同じもの」** — 誤り。独立した入力であり、対流加熱と放射冷却が同時に起きる条件も作れる。"},{"x":"**「表面温度はセル温度と等しい」** — 誤り。Ts と Tc の間には半セルの伝導抵抗があり、診断では別々に表示される。"},{"x":"**「変物性と使えないのは物理的におかしいから」** — 誤り。拒否は検証待ちの措置であり、独立検証では物理・離散化の不整合は見つかっていない（項目10・12）。受理には JS 本体側の直接検証が残っている。（2026-11-07 追記：その直接検証を含む残条件は全て充足し、矩形FVMに限り受理済み。§12 の追記を参照。）"},{"x":"**「h が大きいほど表面温度は流体温度に近づくので、放射は無視できる」** — 誤り。放射の寄与は Ts⁴ で増え、h の大小とは独立に効く。内訳は診断で確認する。"}]}]},{"n":14,"title":"関連教材","blocks":[{"t":"ul","items":[{"x":"教科書：Lienhard & Lienhard『A Heat Transfer Textbook』6th ed.、§10.4（灰色体間の熱伝達）、§10.1（放射交換の問題設定）。宿主側は §2.1（熱伝導方程式）と第5章（過渡応答）。"},{"x":"アプリ内：伝導画面・径方向画面の #manual に、h/ε と各温度を区別する説明と「対流＋放射」境界の案内がある（出典：`docs/dynamic/SURFACE_EXCHANGE.md`）。"}]}]},{"n":15,"title":"関連問題","blocks":[{"t":"p","x":"対応付けは棚卸し記録 `docs/dynamic/MODEL_PROBLEM_MAP_20261107.md`（第7.3節）に基づく。記載した ID はすべて問題バンク `data/questions.json` の実在 ID であり、アプリの演習（`../index.html#quiz`）でそのまま検索できる。主掲載は次の 12 件（全件）で、灰色面と大きな黒体囲いの間の正味放射（本モデルの正準ケース）と、対流と放射を連成した表面収支を扱う。"},{"t":"ul","items":[{"x":"`supp-radiation-temperature` — 四乗の計算に入れる表面温度として絶対温度を使うこと。"},{"x":"`supp-radiation-numeric` — 大きな黒い周囲を見込む灰色面の正味放射。"},{"x":"`supp-audit-radiation-equal-temperatures` — 表面と周囲が同温度のとき正味交換が0になること。"},{"x":"`supp-audit-radiation-emissivity-scale` — 放射率を変えたときの正味放射の比例変化。"},{"x":"`supp-audit-radiation-same-delta-different-level` — 温度差が同じでも温度水準が違えば正味放射が変わること。"},{"x":"`supp-advanced-ch10-calc` — 広い黒体周囲へ向いた灰色拡散面の正味放射。"},{"x":"`supp-deep-rad-netflux-v1` — 大きな黒体囲いを完全に見込む灰色面の単位面積当たり正味放射流束。"},{"x":"`supp-found-three-mode-radiation-v1` — 小さな灰色面と十分大きな黒体囲いの間の放射交換。"},{"x":"`supp-next-combined-surface-loss-v1` — 流体と大きな黒体囲いへの対流・放射の連成損失（最も直接の対応）。"},{"x":"`supp-next-radiation-zero-emissivity-v1` — 放射率 ε→0 の極限での正味放射。"},{"x":"`supp-roadmap-parallel-surface-v1` — 一様表面から同時に出る対流熱流束と正味放射熱流束の収支。"},{"x":"`supp-solar-instant-storage-v1` — 受光体の瞬間のエネルギ収支（吸収・対流・放射・蓄熱）。"}]}]},{"n":16,"title":"参考文献","blocks":[{"t":"ul","items":[{"x":"Lienhard, J. H. IV & Lienhard, J. H. V, *A Heat Transfer Textbook*, 6th ed., Phlogiston Press（第10章、第2章、第5章）。"},{"x":"本リポジトリの検証記録：`docs/dynamic/SURFACE_EXCHANGE.md`、`docs/dynamic/SURFACE_EXCHANGE_REFERENCE_20261105.json`（Python/SciPy の Brent 法による独立参照）、`docs/dynamic/SURFACE_EXCHANGE_BENCHMARKS_20261105.json`、`scripts/dynamic-surface-exchange-benchmarks.mjs`、フェイリス側検証記録 `radiation-closure-verification-20261107.md`（項目5：表面連成 × 温度依存物性の切り分け）。"}]}]}]}];
